# ========================= ЗАГРУЗКА СЕКРЕТОВ =========================

def _load_secrets():
    _ALIASES = {
        "deepseek api key":   "DEEPSEEK_API_KEY",
                "gmail address":      "GMAIL_ADDRESS",
        "gmail app password": "GMAIL_APP_PASSWORD",
        "google app password": "GMAIL_APP_PASSWORD",
        "falcon email":       "FALCON_EMAIL",
        "falcon app password": "FALCON_APP_PASSWORD",
        "vitro email":        "VITRO_EMAIL",
        "vitro app password": "VITRO_APP_PASSWORD",
    }
    _ENV_KEYS = [
        "OPENROUTER_API_KEY", "DEEPSEEK_API_KEY", "LANGSEARCH_API_KEY",
        "GMAIL_ADDRESS", "GMAIL_APP_PASSWORD",
        "FALCON_EMAIL", "FALCON_APP_PASSWORD",
        "VITRO_EMAIL", "VITRO_APP_PASSWORD",
        "SESSION_SECRET",
    ]
    secrets = {k: v for k in _ENV_KEYS if (v := os.environ.get(k, "").strip())}

    secrets_path = Path(__file__).parent / "secrets.txt"
    if not secrets_path.exists():
        if not secrets:
            print("[ПРЕДУПРЕЖДЕНИЕ] secrets.txt не найден и переменные окружения не заданы.")
        return secrets
    with open(secrets_path, encoding="utf-8") as f:
        for line in f:
            line = line.strip()
            if not line or line.startswith("#"):
                continue
            if "=" in line and ":" not in line.split("=")[0]:
                key, _, value = line.partition("=")
                k, v = key.strip(), value.strip()
                if v:
                    secrets[k] = v
            elif ":" in line:
                key, _, value = line.partition(":")
                key_norm = key.strip().lower()
                internal = _ALIASES.get(key_norm, key.strip().upper().replace(" ", "_"))
                v = value.strip()
                if v:
                    secrets[internal] = v
    return secrets


_SECRETS = _load_secrets()


