def _is_reliable_brand(brand_hint: str) -> bool:
    """
    Возвращает True если brand_hint — конкретное название производителя,
    для которого имеет смысл запускать поиск поставщиков на мировом рынке.

    Правила:
    - None / пустая строка / < 3 символов → False
    - Содержит «информация отсутствует», «определено автоматически»,
      «требует проверки», «заполняется вручную» → False (ЛЛМ не уверен)
    - Строка длиннее 80 символов → скорее описание, не бренд → False
    - Нет ни одной латинской буквы → кириллическое нарицательное или
      российский производитель; мировой поиск бессмысленен → False
    """
    if not brand_hint:
        return False
    b = brand_hint.strip()
    if len(b) < 3:
        return False
    b_lower = b.lower()
    for bad in ('информация отсутствует', 'определено автоматически',
                'требует проверки', 'заполняется вручную'):
        if bad in b_lower:
            return False
    if len(b) > 80:
        return False
    # Требуем хотя бы одну латинскую букву — реальный бренд для глобального
    # рынка почти всегда имеет латинское написание
    if not re.search(r'[A-Za-z]', b):
        return False
    return True


