# ========================= БД РЕШЕНИЙ =========================

def init_decisions_db():
    """Создаёт data/decisions.db и нужные таблицы."""
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    conn = sqlite3.connect(str(DATA_DIR / "decisions.db"))
    conn.execute("""
        CREATE TABLE IF NOT EXISTS decisions (
            tender_number   TEXT PRIMARY KEY,
            processed_date  TEXT,
            decision        TEXT,
            subject         TEXT,
            nmck            TEXT,
            china_flag      INTEGER,
            suppliers_found INTEGER
        )
    """)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS notice_type_cache (
            reg_number  TEXT PRIMARY KEY,
            notice_type TEXT,
            base_path   TEXT
        )
    """)
    conn.commit()
    conn.close()


# ========================= ЧЕКПОИНТ =========================

def _load_checkpoint():
    """Загружает checkpoint.json. Возвращает dict или None."""
    cp_path = DATA_DIR / "checkpoint.json"
    if not cp_path.exists():
        return None
    try:
        with open(str(cp_path), encoding="utf-8") as f:
            return _json.load(f)
    except Exception:
        return None


def _save_checkpoint(data):
    """Перезаписывает checkpoint.json."""
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    with open(str(DATA_DIR / "checkpoint.json"), "w", encoding="utf-8") as f:
        _json.dump(data, f, ensure_ascii=False, indent=2)


def _delete_checkpoint():
    """Удаляет checkpoint.json если существует."""
    cp_path = DATA_DIR / "checkpoint.json"
    try:
        cp_path.unlink(missing_ok=True)
    except Exception:
        pass


# ========================= ИСТОРИЯ XLSX =========================

def append_history_xlsx(new_records):
    """
    Дописывает строки текущего прогона в data/history.xlsx.
    new_records — список dict: {processed_date, tender_number, subject, nmck, decision, china_flag, suppliers_found}
    """
    if not new_records:
        return
    try:
        from openpyxl import Workbook, load_workbook
        from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
    except ImportError:
        print("  ⚠️ openpyxl не установлен — history.xlsx не обновлён.")
        return

    DECISION_LABELS = {
        "participate":     "Участвуем",
        "clarify":         "Требуется уточнение",
        "not_participate": "Отказ",
        "error":           "Ошибка",
    }
    HEADERS = [
        "Дата обработки", "Номер тендера", "Предмет закупки",
        "НМЦК (руб.)", "Решение", "Доступен в Китае", "Поставщики найдены",
    ]
    FILL_HEADER = PatternFill("solid", fgColor="4472C4")
    THIN = Border(
        left=Side(style="thin"), right=Side(style="thin"),
        top=Side(style="thin"),  bottom=Side(style="thin"),
    )
    COL_WIDTHS = [18, 22, 55, 18, 25, 20, 22]

    DATA_DIR.mkdir(parents=True, exist_ok=True)
    hist_path = DATA_DIR / "history.xlsx"

    if hist_path.exists():
        wb = load_workbook(str(hist_path))
        ws = wb.active
        start_row = ws.max_row + 1
    else:
        wb = Workbook()
        ws = wb.active
        ws.title = "История решений"
        for col_idx, (h, w) in enumerate(zip(HEADERS, COL_WIDTHS), start=1):
            cell = ws.cell(row=1, column=col_idx, value=h)
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = FILL_HEADER
            cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
            cell.border = THIN
            ws.column_dimensions[get_column_letter(col_idx)].width = w
        ws.row_dimensions[1].height = 30
        ws.freeze_panes = "A2"
        start_row = 2

    FILL_GREEN  = PatternFill("solid", fgColor="C6EFCE")
    FILL_YELLOW = PatternFill("solid", fgColor="FFEB9C")
    FILL_RED    = PatternFill("solid", fgColor="FFC7CE")

    for rec in new_records:
        decision = rec.get("decision", "")
        fill = (FILL_GREEN if decision == "participate"
                else FILL_YELLOW if decision == "clarify"
                else FILL_RED if decision == "error"
                else None)
        row_data = [
            rec.get("processed_date", ""),
            rec.get("tender_number", ""),
            rec.get("subject", ""),
            rec.get("nmck", ""),
            DECISION_LABELS.get(decision, decision),
            "Да" if rec.get("china_flag") else "Нет",
            "Да" if rec.get("suppliers_found") else "Нет",
        ]
        for col_idx, value in enumerate(row_data, start=1):
            cell = ws.cell(row=start_row, column=col_idx, value=value)
            cell.border = THIN
            cell.alignment = Alignment(vertical="center", wrap_text=(col_idx == 3))
            if fill:
                cell.fill = fill
        start_row += 1

    wb.save(str(hist_path))
    print(f"📒 История решений обновлена: {hist_path} (+{len(new_records)} строк)")


def save_run_summary(results, output_dir, path_mapping=None):
    """
    Сохраняет Excel-сводку прогона в output_dir/итоги_прогона_<дата>.xlsx.
    results — список 9-кортежей из process_tender().
    """
    try:
        from openpyxl import Workbook
        from openpyxl.styles import PatternFill, Font, Alignment, Border, Side
        from openpyxl.utils import get_column_letter
    except ImportError:
        print("  ⚠️ openpyxl не установлен — сводная таблица не создана. pip install openpyxl")
        return

    DECISION_LABELS = {
        "participate":    "Участвуем",
        "clarify":        "Требуется уточнение",
        "not_participate": "Отказ",
        "error":          "Ошибка",
    }
    FILL_GREEN  = PatternFill("solid", fgColor="C6EFCE")
    FILL_YELLOW = PatternFill("solid", fgColor="FFEB9C")
    FILL_RED    = PatternFill("solid", fgColor="FFC7CE")
    FILL_HEADER = PatternFill("solid", fgColor="4472C4")
    FILL_TOTAL  = PatternFill("solid", fgColor="D9E1F2")
    THIN_BORDER = Border(
        left=Side(style="thin"), right=Side(style="thin"),
        top=Side(style="thin"),  bottom=Side(style="thin"),
    )

    headers = [
        "№", "Номер тендера", "Предмет закупки", "НМЦК (руб.)",
        "Решение", "Доступен в Китае", "Срок подачи заявок",
        "Поставщики найдены", "Путь к Word-отчёту",
    ]
    col_widths = [5, 22, 55, 18, 25, 18, 22, 22, 50]

    wb = Workbook()
    ws = wb.active
    ws.title = "Итоги прогона"

    for col_idx, (h, w) in enumerate(zip(headers, col_widths), start=1):
        cell = ws.cell(row=1, column=col_idx, value=h)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = FILL_HEADER
        cell.alignment = Alignment(horizontal="center", vertical="center", wrap_text=True)
        cell.border = THIN_BORDER
        ws.column_dimensions[get_column_letter(col_idx)].width = w
    ws.row_dimensions[1].height = 30

    cnt = {"participate": 0, "clarify": 0, "not_participate": 0, "error": 0}
    pm = path_mapping or {}

    for row_num, result in enumerate(results, start=1):
        reg, deadline, doc_path, decision, china_flag, _, subject_str, nmck_str, suppliers_found = result
        cnt[decision] = cnt.get(decision, 0) + 1

        final_doc = pm.get(doc_path, doc_path) if doc_path else None
        row_data = [
            row_num, reg, subject_str, nmck_str,
            DECISION_LABELS.get(decision, decision),
            "Да" if china_flag else "Нет",
            deadline,
            "Да" if suppliers_found else "Нет",
            final_doc or "—",
        ]

        if decision == "participate":
            fill = FILL_GREEN
        elif decision == "clarify":
            fill = FILL_YELLOW
        elif decision == "error":
            fill = FILL_RED
        else:
            fill = None

        excel_row = row_num + 1
        for col_idx, value in enumerate(row_data, start=1):
            cell = ws.cell(row=excel_row, column=col_idx, value=value)
            cell.border = THIN_BORDER
            cell.alignment = Alignment(vertical="center", wrap_text=(col_idx == 3))
            if fill:
                cell.fill = fill

    # Итоговая строка
    total_row = len(results) + 2
    summary_text = (
        f"Всего: {len(results)}  |  "
        f"Участвуем: {cnt.get('participate', 0)}  |  "
        f"Уточнение: {cnt.get('clarify', 0)}  |  "
        f"Отказ: {cnt.get('not_participate', 0)}  |  "
        f"Ошибок: {cnt.get('error', 0)}"
    )
    ws.merge_cells(start_row=total_row, start_column=1, end_row=total_row, end_column=len(headers))
    total_cell = ws.cell(row=total_row, column=1, value=summary_text)
    total_cell.fill = FILL_TOTAL
    total_cell.font = Font(bold=True)
    total_cell.alignment = Alignment(horizontal="center", vertical="center")
    total_cell.border = THIN_BORDER

    ws.freeze_panes = "A2"
    ws.auto_filter.ref = f"A1:{get_column_letter(len(headers))}1"

    date_tag = datetime.datetime.now().strftime("%d.%m.%Y")
    filename = f"итоги_прогона_{date_tag}.xlsx"
    os.makedirs(output_dir, exist_ok=True)
    save_path = os.path.join(output_dir, filename)
    wb.save(save_path)
    print(f"\n📊 Сводная таблица сохранена: {save_path}")

