# ========================= УТИЛИТЫ =========================

def safe_filename(name, max_len=120):
    """Создаёт безопасное имя файла из строки."""
    name = re.sub(r'[\\/:*?"<>|]', '_', name)
    name = re.sub(r'\s+', '_', name)
    return name[:max_len] if len(name) > max_len else name


def decode_content_disposition(header_val):
    """Декодирует имя файла из заголовка Content-Disposition."""
    if not header_val:
        return None
    # RFC 5987 encoding: filename*=UTF-8''...
    m = re.search(r"filename\*=UTF-8''([^;]+)", header_val, re.IGNORECASE)
    if m:
        from urllib.parse import unquote
        return unquote(m.group(1))
    # Кириллица с charset=windows-1251
    m = re.search(r'filename\*=([^;]+)', header_val, re.IGNORECASE)
    if m:
        raw = m.group(1).strip()
        if raw.startswith('"') and raw.endswith('"'):
            raw = raw[1:-1]
        try:
            return raw.encode('latin-1').decode('windows-1251')
        except Exception:
            return raw
    # Стандартный filename=
    m = re.search(r'filename="([^"]+)"', header_val, re.IGNORECASE)
    if m:
        filename = m.group(1)
        try:
            return filename.encode('latin-1').decode('windows-1251')
        except Exception:
            try:
                return filename.encode('latin-1').decode('utf-8')
            except Exception:
                return filename
    m = re.search(r"filename='([^']+)'", header_val, re.IGNORECASE)
    if m:
        return m.group(1)
    m = re.search(r'filename=([^;]+)', header_val, re.IGNORECASE)
    if m:
        filename = m.group(1).strip()
        if filename.startswith('"') and filename.endswith('"'):
            filename = filename[1:-1]
        elif filename.startswith("'") and filename.endswith("'"):
            filename = filename[1:-1]
        try:
            return filename.encode('latin-1').decode('windows-1251')
        except Exception:
            return filename
    return None


def parse_date_from_excel(date_val):
    # ── v10: пустые даты (NaT/NaN/None) из выгрузки сэмплера ──
    if date_val is None:
        return None
    try:
        import pandas as _pd_v10
        if _pd_v10.isna(date_val):
            return None
    except (TypeError, ValueError):
        pass
    if isinstance(date_val, str) and not date_val.strip():
        return None
    """Нормализует дату из Excel в строку «dd.mm.yyyy»."""
    if isinstance(date_val, datetime.datetime):
        return date_val.strftime('%d.%m.%Y')
    if isinstance(date_val, str):
        for fmt in ('%Y-%m-%d', '%d.%m.%Y', '%Y/%m/%d'):
            try:
                return datetime.datetime.strptime(date_val[:10], fmt).strftime('%d.%m.%Y')
            except ValueError:
                continue
    return datetime.datetime.now().strftime('%d.%m.%Y')


# ========================= ТИПЫ ИЗВЕЩЕНИЙ =========================

FZ44_NOTICE_TYPES = ["ea44", "ok44", "zk44", "ep44", "zp44", "ok504", "zkk44", "gk44", "ek44", "a44", "oa44"]

# SPA-типы извещений (новые форматы ЕИС, GUID не требуется)
SPA_NOTICE_TYPES = ['ea20', 'ea15', 'eap20']


FZ223_NOTICE_TYPES = [
    "notice223",
    "zapros-kotirovok",
    "zapros-predlozheniy",
    "zmo",
    "eauction223",
    "smally",
    "privacyPurchase",
    "notice223ep",
    "simplepurchase",
    "aep",
]

_notice_type_cache: dict = {}
_notice_base_path_cache: dict = {}
_notice_no_guid_cache: dict = {}


# ========================= GUID =========================

def _fz_kind(reg_number):
    s = str(reg_number).strip()
    if len(s) >= 19 and s.startswith("0") and s.isdigit():
        return "44"
    return "223"


def _parse_source_url(url):
    if not url or not isinstance(url, str):
        return None, None
    m = re.search(r'/epz/order/notice/([^/]+)(/view)?/common-info\.html', url)
    if not m:
        return None, None
    notice_type = m.group(1)
    view_part = m.group(2) or ""
    base_path = f"/epz/order/notice/{notice_type}{view_part}"
    return notice_type, base_path


def _extract_notice_guid(html):
    match = re.search(r'noticeGuid\s*[=:]\s*"([a-f0-9-]+)"', html, re.IGNORECASE)
    if match:
        return match.group(1)
    match = re.search(r"noticeGuid\s*[=:]\s*'([a-f0-9-]+)'", html, re.IGNORECASE)
    if match:
        return match.group(1)
    match = re.search(r'data-notice-guid="([a-f0-9-]+)"', html, re.IGNORECASE)
    if match:
        return match.group(1)
    match = re.search(r'documents\.html\?[^"\']*noticeGuid=([a-f0-9-]+)', html, re.IGNORECASE)
    if match:
        return match.group(1)
    _uuid_re = r'[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}'
    for key in ('purchaseGuid', 'noticeId', 'purchaseId'):
        m = re.search(rf'["\']?{key}["\']?\s*[=:]\s*["\']?({_uuid_re})', html, re.IGNORECASE)
        if m:
            return m.group(1)
    soup = BeautifulSoup(html, 'html.parser')
    inp = soup.find('input', {'name': 'noticeGuid'})
    if inp and inp.get('value'):
        return inp['value']
    return None



def _eis_get(session, url, **kwargs):
    """GET-запрос к ЕИС с автоматическим отключением SSL-верификации при ошибке (ТСПУ/прокси)."""
    try:
        return session.get(url, **kwargs)
    except requests.exceptions.SSLError:
        if session.verify:
            session.verify = False
            print(f"  ⚠️ SSL-ошибка ЕИС — отключаю верификацию (VPN/ТСПУ), повтор")
            return session.get(url, **kwargs)
        raise

def _fetch_guid_via_api(reg_number, notice_type, session):
    _uuid_full = re.compile(
        r'[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}', re.I
    )
    api_urls = [
        f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/api/purchaseNotice?number={reg_number}",
        f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/api/commonInfo?regNumber={reg_number}",
        f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/api/notice?number={reg_number}",
        f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/api/purchase?number={reg_number}",
    ]
    for url in api_urls:
        try:
            resp = _eis_get(session, url, timeout=15)
            if resp.status_code != 200:
                continue
            try:
                data = resp.json()
                for key in ('noticeGuid', 'purchaseGuid', 'guid', 'id', 'noticeId'):
                    val = data.get(key)
                    if not val and isinstance(data.get('data'), dict):
                        val = data['data'].get(key)
                    if val and _uuid_full.match(str(val)):
                        print(f"  Тип извещения: {notice_type} (REST API [{key}])")
                        return str(val)
            except Exception:
                pass
            for key in ('noticeGuid', 'purchaseGuid', 'guid'):
                m = re.search(
                    rf'["\']?{key}["\']?\s*[=:]\s*["\']?'
                    rf'([a-f0-9]{{8}}-[a-f0-9]{{4}}-[a-f0-9]{{4}}-[a-f0-9]{{4}}-[a-f0-9]{{12}})',
                    resp.text, re.I
                )
                if m:
                    print(f"  Тип извещения: {notice_type} (REST API text [{key}])")
                    return m.group(1)
        except Exception:
            continue
    return None


def _find_guid_via_search(reg_number, session):
    search_url = (
        f"https://zakupki.gov.ru/epz/order/extendedsearch/results.html"
        f"?searchString={reg_number}&morphology=on"
        f"&search-filter=%D0%94%D0%B0%D1%82%D0%B5+%D1%80%D0%B0%D0%B7%D0%BC%D0%B5%D1%89%D0%B5%D0%BD%D0%B8%D1%8F"
    )
    try:
        resp = _eis_get(session, search_url, timeout=30)
        if resp.status_code != 200:
            return None, None
        pattern = (
            r'/epz/order/notice/([^/]+)(?:/view)?/common-info\.html\?[^"\']*regNumber='
            + re.escape(str(reg_number))
        )
        match = re.search(pattern, resp.text, re.IGNORECASE)
        if not match:
            print(f"  Поиск ЕИС: тендер {reg_number} не найден в результатах")
            return None, None
        notice_type = match.group(1)
        tender_url = f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/common-info.html?regNumber={reg_number}"
        resp2 = _eis_get(session, tender_url, timeout=30)
        if resp2.status_code != 200:
            return None, None
        guid = _extract_notice_guid(resp2.text)
        if guid:
            print(f"  Найден через поиск ЕИС, тип: {notice_type}")
        return guid, notice_type
    except Exception as e:
        print(f"  Поиск ЕИС: ошибка — {e}")
        return None, None


def fetch_notice_guid(reg_number, session, source_url=None):
    if source_url:
        notice_type, base_path = _parse_source_url(source_url)
        if notice_type and base_path:
            try:
                resp = _eis_get(session, source_url, timeout=30)
                if resp.status_code == 200:
                    guid = _extract_notice_guid(resp.text)
                    if guid:
                        _notice_type_cache[str(reg_number)] = notice_type
                        _notice_base_path_cache[str(reg_number)] = base_path
                        print(f"  Тип извещения: {notice_type} (из выгрузки)")
                        return guid
                    _KNOWN_SPA_TYPES = {'ea20', 'ea15'}
                    if '/view/' in base_path or notice_type in _KNOWN_SPA_TYPES:
                        _notice_no_guid_cache[str(reg_number)] = True
                        _notice_type_cache[str(reg_number)] = notice_type
                        _notice_base_path_cache[str(reg_number)] = base_path
                        print(f"  Тип извещения: {notice_type} (SPA, GUID не требуется)")
                        return "__REG_ONLY__"
                    print(f"  ⚠️ {notice_type}: HTTP 200, GUID не в HTML — пробуем REST API")
                    guid = _fetch_guid_via_api(reg_number, notice_type, session)
                    if guid:
                        _notice_type_cache[str(reg_number)] = notice_type
                        _notice_base_path_cache[str(reg_number)] = base_path
                        return guid
                    print(f"  ⚠️ {notice_type}: REST API не вернул GUID — пробуем без GUID")
                    _notice_no_guid_cache[str(reg_number)] = True
                    _notice_type_cache[str(reg_number)] = notice_type
                    _notice_base_path_cache[str(reg_number)] = base_path
                    return "__REG_ONLY__"
            except Exception as e:
                print(f"  URL из выгрузки недоступен: {e}")
    fz = _fz_kind(reg_number)
    if fz == "223":
        url = f"https://zakupki.gov.ru/epz/order/notice/notice223/common-info.html?regNumber={reg_number}"
        try:
            resp = _eis_get(session, url, timeout=30)
            if resp.status_code == 200:
                guid = _extract_notice_guid(resp.text)
                if guid:
                    _notice_type_cache[str(reg_number)] = "notice223"
                    return guid
            guid, notice_type = _find_guid_via_search(reg_number, session)
            if guid:
                _notice_type_cache[str(reg_number)] = notice_type
                return guid
            padded = "0" + str(reg_number)
            if _fz_kind(padded) == "44":
                print(f"  Пробуем с восстановленным ведущим нулём: {padded}")
                guid, notice_type = _fetch_guid_fz44(padded, session)
                if guid:
                    _notice_type_cache[str(reg_number)] = notice_type
                    return guid
            print(f"  ⚠️ GUID не найден — пробуем страницу документов напрямую по regNumber")
            _notice_no_guid_cache[str(reg_number)] = True
            _notice_type_cache[str(reg_number)] = "notice223"
            _notice_base_path_cache[str(reg_number)] = "/epz/order/notice/notice223"
            return "__REG_ONLY__"
        except Exception as e:
            print(f"  Ошибка получения GUID: {e}")
            return None
    return _fetch_guid_fz44(reg_number, session)


def _fetch_guid_fz44(reg_number, session):
    for notice_type in FZ44_NOTICE_TYPES:
        url = f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/common-info.html?regNumber={reg_number}"
        try:
            resp = _eis_get(session, url, timeout=20)
            if resp.status_code != 200:
                continue
            guid = _extract_notice_guid(resp.text)
            if guid:
                _notice_type_cache[str(reg_number)] = notice_type
                print(f"  Тип извещения 44-ФЗ: {notice_type}")
                return guid
        except Exception:
            continue

    # Проверка SPA-типов (ea20, ea15, eap20) — GUID не требуется
    for spa_type in SPA_NOTICE_TYPES:
        url = f"https://zakupki.gov.ru/epz/order/notice/{spa_type}/view/common-info.html?regNumber={reg_number}"
        try:
            resp = session.get(url, timeout=20)
            if resp.status_code == 200:
                _notice_type_cache[str(reg_number)] = spa_type
                _notice_base_path_cache[str(reg_number)] = f"/epz/order/notice/{spa_type}/view"
                _notice_no_guid_cache[str(reg_number)] = True
                print(f"  Тип извещения 44-ФЗ: {spa_type} (SPA, GUID не требуется)")
                return "__REG_ONLY__"
        except Exception:
            continue

    # ── SPA-типы 44-ФЗ (ea20, ea15, eap20) — GUID не требуется ────────
    for _spa in ('ea20', 'ea15', 'eap20'):
        _spa_url = f"https://zakupki.gov.ru/epz/order/notice/{_spa}/view/common-info.html?regNumber={reg_number}"
        try:
            _r = session.get(_spa_url, timeout=20)
            if _r.status_code == 200 and 'common-info' in _r.text[:5000].lower() or 'notFound' not in _r.text[:2000]:
                _notice_type_cache[str(reg_number)] = _spa
                _notice_base_path_cache[str(reg_number)] = f"/epz/order/notice/{_spa}/view"
                _notice_no_guid_cache[str(reg_number)] = True
                print(f"  Тип извещения 44-ФЗ: {_spa} (SPA, GUID не требуется)")
                return "__REG_ONLY__"
        except Exception:
            continue

    guid, notice_type = _find_guid_via_search(reg_number, session)
    if guid:
        _notice_type_cache[str(reg_number)] = notice_type
    else:
        print(f"  Ошибка получения GUID: тип не найден ни перебором, ни через поиск ЕИС")
    return guid


# ========================= ССЫЛКИ НА ФАЙЛЫ =========================

def _find_fz223_documents_url(reg_number, session):
    key = str(reg_number)
    try:
        db_path = str(DATA_DIR / "decisions.db")
        with sqlite3.connect(db_path) as _conn:
            row = _conn.execute(
                "SELECT notice_type, base_path FROM notice_type_cache WHERE reg_number = ?",
                (key,)
            ).fetchone()
        if row:
            notice_type, base_path = row
            _notice_type_cache[key] = notice_type
            _notice_base_path_cache[key] = base_path
            docs_url = (
                f"https://zakupki.gov.ru{base_path}/documents.html"
                f"?regNumber={reg_number}"
            )
            print(f"  ✅ 223-ФЗ тип извещения из кэша БД: {notice_type}")
            return docs_url, notice_type
    except Exception as e:
        print(f"  ⚠️ Не удалось прочитать notice_type_cache из БД: {e}")

    for notice_type in FZ223_NOTICE_TYPES:
        url = (
            f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/documents.html"
            f"?regNumber={reg_number}"
        )
        try:
            resp = _eis_get(session, url, timeout=20)
            if resp.status_code != 200:
                continue
            if re.search(r'[?&]uid=[A-F0-9-]+', resp.text, re.IGNORECASE):
                base_path = f"/epz/order/notice/{notice_type}"
                _notice_type_cache[key] = notice_type
                _notice_base_path_cache[key] = base_path
                print(f"  ✅ 223-ФЗ тип извещения найден: {notice_type}")
                try:
                    with sqlite3.connect(str(DATA_DIR / "decisions.db")) as _conn:
                        _conn.execute(
                            "INSERT OR REPLACE INTO notice_type_cache"
                            " (reg_number, notice_type, base_path) VALUES (?, ?, ?)",
                            (key, notice_type, base_path)
                        )
                except Exception as e:
                    print(f"  ⚠️ Не удалось сохранить notice_type_cache в БД: {e}")
                return url, notice_type
        except Exception:
            continue
    tried = ", ".join(FZ223_NOTICE_TYPES)
    print(f"  ⚠️ Страница документов не найдена ни для одного типа 223-ФЗ "
          f"(проверены: {tried})")
    return None, None


def get_file_links_from_documents_page(reg_number, notice_guid, session):
    fz = _fz_kind(reg_number)
    key = str(reg_number)
    base_path = _notice_base_path_cache.get(key)
    if notice_guid == "__REG_ONLY__":
        if fz == "223" and (not base_path or base_path == "/epz/order/notice/notice223"):
            docs_url, found_type = _find_fz223_documents_url(reg_number, session)
            if not docs_url:
                return []
            base_path = _notice_base_path_cache.get(key)
        else:
            docs_url = (
                f"https://zakupki.gov.ru{base_path}/documents.html"
                f"?regNumber={reg_number}"
            )
    elif base_path:
        docs_url = (
            f"https://zakupki.gov.ru{base_path}/documents.html"
            f"?purchaseNoticeNumber={reg_number}&noticeGuid={notice_guid}"
        )
    else:
        notice_type = _notice_type_cache.get(key, f"notice{fz}")
        docs_url = (
            f"https://zakupki.gov.ru/epz/order/notice/{notice_type}/documents.html"
            f"?purchaseNoticeNumber={reg_number}&noticeGuid={notice_guid}"
        )
    try:
        resp = _eis_get(session, docs_url, timeout=30)
        resp.raise_for_status()
        soup = BeautifulSoup(resp.text, 'html.parser')
        unique_files = OrderedDict()
        for a in soup.find_all('a', href=True):
            href = a['href']
            link_text = a.get_text().strip().lower()
            if any(kw in link_text for kw in SKIP_KEYWORDS):
                print(f"    ⏭️ Пропускаем (стоп-слово): {link_text[:60]}")
                continue
            uid_match = re.search(r'[?&]uid=([A-F0-9-]+)', href, re.IGNORECASE)
            uid = uid_match.group(1) if uid_match else None
            if uid and uid not in unique_files:
                if href.startswith('http'):
                    primary_url = href
                elif href.startswith('/'):
                    primary_url = 'https://zakupki.gov.ru' + href
                else:
                    notice_type_local = _notice_type_cache.get(str(reg_number), "")
                    if notice_type_local in ('ea20', 'ea15') or notice_guid == "__REG_ONLY__":
                        primary_url = f"https://zakupki.gov.ru/44fz/filestore/public/1.0/download/priz/file.html?uid={uid}"
                    elif fz == "223":
                        primary_url = f"https://zakupki.gov.ru/223/filestore/public/1.0/download/fz223/file.html?uid={uid}"
                    else:
                        primary_url = f"https://zakupki.gov.ru/44/filestore/public/1.0/download/fz44/file.html?uid={uid}"
                unique_files[uid] = {
                    'url': primary_url,
                    'uid': uid,
                    'text': link_text
                }
        return [(info['url'], info['uid'], info['text'], docs_url) for info in unique_files.values()]
    except Exception as e:
        print(f"  Ошибка загрузки страницы документов: {e}")
        return []


# ========================= СКАЧИВАНИЕ ФАЙЛОВ =========================


def _extract_download_url_from_html(html_text, uid, page_url):
    """Из HTML-страницы filestore вытаскивает прямую ссылку на файл."""
    soup = BeautifulSoup(html_text, 'html.parser')
    uid_lower = uid.lower()

    for a in soup.find_all('a', href=True):
        href = a['href']
        if uid_lower in href.lower() or any(k in href.lower() for k in ('download', 'filestore', '/file?', '/get?')):
            if href.startswith('http'):
                return href
            if href.startswith('/'):
                return 'https://zakupki.gov.ru' + href

    meta = soup.find('meta', attrs={'http-equiv': re.compile(r'refresh', re.I)})
    if meta:
        content = meta.get('content', '')
        m = re.search(r'url=([^\s;]+)', content, re.I)
        if m:
            redirect = m.group(1).strip("'\"")
            if redirect.startswith('http'):
                return redirect
            if redirect.startswith('/'):
                return 'https://zakupki.gov.ru' + redirect

    form = soup.find('form', action=True)
    if form:
        action = form['action']
        if action.startswith('http'):
            return action
        if action.startswith('/'):
            return 'https://zakupki.gov.ru' + action

    return None


def download_file(url, uid, link_text, save_dir, session, retries=5, referer=None, _net_err=None):
    """Скачивает файл по URL с retry, HTML-detection и min-size проверкой.

    При HTTP 503 (ЕИС filestore перегружен) делает длинные паузы 45–225 сек вместо
    стандартных 2–16 сек, чтобы дождаться восстановления сервера.
    _net_err — изменяемый список; при каждом 503 добавляется True для внешнего контроля.
    """
    temp_path = os.path.join(save_dir, f"temp_{uid}.tmp")
    headers = {}
    if referer:
        headers['Referer'] = referer
    for attempt in range(retries):
        try:
            resp = session.get(url, stream=True, timeout=90, headers=headers)
            if resp.status_code == 200:
                with open(temp_path, 'wb') as f:
                    for chunk in resp.iter_content(8192):
                        f.write(chunk)
                file_size = os.path.getsize(temp_path)
                if file_size < 200:
                    os.remove(temp_path)
                    print(f"    Попытка {attempt + 1}: HTTP 200, но файл слишком мал ({file_size} байт) — пропуск")
                    continue
                content_type = resp.headers.get('Content-Type', '')
                detected_ext = _detect_extension(temp_path)
                if 'text/html' in content_type or detected_ext == '.html':
                    with open(temp_path, 'r', encoding='utf-8', errors='ignore') as f:
                        html_text = f.read()
                    os.remove(temp_path)
                    real_url = _extract_download_url_from_html(html_text, uid, url)
                    if real_url and real_url != url:
                        print(f"    Попытка {attempt + 1}: HTML-редирект → {real_url[:80]}")
                        try:
                            resp2 = session.get(real_url, stream=True, timeout=90, headers=headers)
                            if resp2.status_code == 200:
                                with open(temp_path, 'wb') as f:
                                    for chunk in resp2.iter_content(8192):
                                        f.write(chunk)
                                if os.path.getsize(temp_path) >= 200:
                                    resp = resp2
                                else:
                                    os.remove(temp_path)
                                    continue
                            else:
                                continue
                        except Exception:
                            continue
                    else:
                        stripped_url = re.sub(r'/file\.html', '/file', url)
                        if stripped_url != url:
                            try:
                                resp3 = session.get(stripped_url, stream=True, timeout=90, headers=headers)
                                if resp3.status_code == 200 and 'text/html' not in resp3.headers.get('Content-Type', ''):
                                    with open(temp_path, 'wb') as f:
                                        for chunk in resp3.iter_content(8192):
                                            f.write(chunk)
                                    if os.path.getsize(temp_path) >= 200:
                                        resp = resp3
                                    else:
                                        os.remove(temp_path)
                                        continue
                                else:
                                    continue
                            except Exception:
                                continue
                        else:
                            continue
                content_disp = resp.headers.get('Content-Disposition')
                filename = decode_content_disposition(content_disp)
                if not filename and link_text:
                    filename = link_text
                if not filename:
                    filename = uid + ".bin"
                final_filename = safe_filename(filename)
                _, ext = os.path.splitext(final_filename)
                if ext.lower() in ('', '.bin', '.tmp', '.html'):
                    re_detected = _detect_extension(temp_path)
                    if re_detected and re_detected != '.html':
                        final_filename = os.path.splitext(final_filename)[0] + re_detected
                final_path = os.path.join(save_dir, final_filename)
                counter = 1
                base, ext = os.path.splitext(final_path)
                while os.path.exists(final_path):
                    final_path = f"{base}_{counter}{ext}"
                    counter += 1
                os.rename(temp_path, final_path)
                return final_path
            else:
                if resp.status_code == 503:
                    wait = 45 * (attempt + 1)
                    print(f"    Попытка {attempt + 1}: HTTP 503 (ЕИС filestore недоступен) — ждём {wait} сек.")
                    if _net_err is not None:
                        _net_err.append(True)
                    time.sleep(wait)
                    continue  # пропускаем обычный sleep ниже
                print(f"    Попытка {attempt + 1}: HTTP {resp.status_code}")
        except requests.exceptions.SSLError:
            if session.verify:
                session.verify = False
                print("    ⚠️ SSL-ошибка — отключаю верификацию (VPN/ТСПУ), повтор")
                continue
            time.sleep(2 ** attempt)
        except Exception as e:
            print(f"    Попытка {attempt + 1}: {e}")
        if attempt < retries - 1:
            time.sleep(2 ** attempt)
    # Fallback по UID — перебираем все известные хранилища
    if uid:
        fallback_urls = [
            f"https://zakupki.gov.ru/44fz/filestore/public/1.0/download/priz/file.html?uid={uid}",
            f"https://zakupki.gov.ru/44/filestore/public/1.0/download/fz44/file.html?uid={uid}",
            f"https://zakupki.gov.ru/223/filestore/public/1.0/download/fz223/file.html?uid={uid}",
        ]
        for fallback_url in fallback_urls:
            for attempt in range(2):
                try:
                    resp = session.get(fallback_url, stream=True, timeout=90, headers=headers)
                    if resp.status_code == 200:
                        with open(temp_path, 'wb') as f:
                            for chunk in resp.iter_content(8192):
                                f.write(chunk)
                        fb_size = os.path.getsize(temp_path)
                        if fb_size < 200:
                            os.remove(temp_path)
                            continue
                        detected = _detect_extension(temp_path)
                        if detected == '.html':
                            os.remove(temp_path)
                            continue
                        fb_filename = uid + (detected if detected else ".bin")
                        final_path = os.path.join(save_dir, safe_filename(fb_filename))
                        os.rename(temp_path, final_path)
                        return final_path
                except Exception:
                    pass
                time.sleep(2)
    return None


def download_tender_documents(reg_number, row, session, tender_dir):
    """
    Скачивает все документы тендера.
    Возвращает (downloaded_paths, partner_card_found, nac_regime_found, network_failed).
    network_failed=True если 0 файлов скачалось и хотя бы один файл вернул HTTP 503
    (ЕИС filestore временно недоступен — тендер должен быть повторён, не записан в БД как «не участвуем»).
    """
    source_url = str(row.get('Ссылка на источник', '') or '').strip() or None
    notice_guid = fetch_notice_guid(reg_number, session, source_url=source_url)
    if not notice_guid:
        raise Exception("Не найден noticeGuid")
    if notice_guid != "__REG_ONLY__":
        print(f"  GUID: {notice_guid}")

    file_items = get_file_links_from_documents_page(reg_number, notice_guid, session)
    print(f"  Найдено релевантных файлов: {len(file_items)}")

    downloaded_paths = []
    seen_names = set()
    _net_err = []  # накапливает True за каждый HTTP 503 при скачивании
    for url, uid, link_text, docs_referer in file_items[:MAX_FILES_PER_TENDER]:
        saved_path = download_file(url, uid, link_text, tender_dir, session,
                                   referer=docs_referer, _net_err=_net_err)
        if saved_path and os.path.getsize(saved_path) > 0:
            basename = os.path.basename(saved_path)
            if basename not in seen_names:
                seen_names.add(basename)
                downloaded_paths.append(saved_path)
                print(f"    ✅ {basename} ({os.path.getsize(saved_path)} байт)")
            else:
                os.remove(saved_path)
                print(f"    ⏭️ Пропущен дубликат: {basename}")
        else:
            print(f"    ❌ Не удалось скачать uid={uid}")
        time.sleep(0.5)

    # Проверяем имена файлов на стоп-факторы
    partner_card_found = False
    nac_regime_found = False
    for fpath in downloaded_paths:
        fname_lower = os.path.basename(fpath).lower()
        if re.search(
            r'карт\w*[\s_+\-]*партнер|партнерск\w*[\s_+\-]*(соглашени|карт)'
            r'|дилерск\w*[\s_+\-]*соглашени|partner[\s_+\-]?card',
            fname_lower
        ):
            print(f"  ⛔ Стоп-фактор #10: '{os.path.basename(fpath)}' — карта партнёра/дилерское соглашение")
            partner_card_found = True
        if re.search(r'нац[\w+\-]*\s*режим|национальн\w*[\s_+\-]*режим', fname_lower):
            nac_regime_found = True
            print(f"  ⚠️ Файл с национальным режимом: '{os.path.basename(fpath)}'")

    # Сетевая ошибка: ни одного файла не скачалось и причина — HTTP 503
    network_failed = (len(downloaded_paths) == 0 and bool(_net_err))
    return downloaded_paths, partner_card_found, nac_regime_found, network_failed

# ======================================================================
# EXTRACTORS
# ======================================================================


# ========================= DOC / DOCX =========================

def extract_text_from_doc(filepath):
    """Читает .doc через win32com (если доступен) или antiword."""
    if WIN32COM_AVAILABLE:
        try:
            pythoncom.CoInitialize()
            word = win32com.client.Dispatch('Word.Application')
            word.Visible = False
            word.DisplayAlerts = False
            abs_path = os.path.abspath(filepath)
            try:
                doc = word.Documents.Open(abs_path, ReadOnly=True)
                paragraphs_text = '\n'.join(
                    p.Range.Text.strip()
                    for p in doc.Paragraphs
                    if p.Range.Text.strip()
                )
                tables_text = ""
                for table in doc.Tables:
                    for row_idx in range(1, table.Rows.Count + 1):
                        row_cells = []
                        for col_idx in range(1, table.Columns.Count + 1):
                            try:
                                cell_text = table.Cell(row_idx, col_idx).Range.Text.strip()
                                cell_text = cell_text.rstrip('\r\x07')
                                if cell_text:
                                    row_cells.append(cell_text)
                            except Exception:
                                pass
                        if row_cells:
                            tables_text += ' | '.join(row_cells) + '\n'
                full_text = paragraphs_text + '\n' + tables_text
                doc.Close(False)
                return full_text if full_text.strip() else None
            except Exception as e:
                print(f"      win32com doc open error: {e}")
                try:
                    word.Quit()
                except Exception:
                    pass
                return None
            finally:
                try:
                    word.Quit()
                except Exception:
                    pass
                pythoncom.CoUninitialize()
        except Exception as e:
            print(f"      win32com init error: {e}")

    try:
        antiword_exe = os.path.join(ANTIWORD_DIR, "antiword.exe")
        mapping_file = os.path.join(ANTIWORD_DIR, "8859-1.txt")
        if not os.path.exists(antiword_exe) or not os.path.exists(mapping_file):
            print(f"      antiword не найден по пути {ANTIWORD_DIR}")
            return None
        cmd = [antiword_exe, '-m', mapping_file, '-f', filepath]
        result = subprocess.run(cmd, capture_output=True, text=True, timeout=30, encoding='utf-8')
        if result.returncode == 0 and result.stdout.strip():
            return result.stdout
        else:
            print(f"      antiword вернул код {result.returncode}: {result.stderr[:200]}")
    except Exception as e:
        print(f"      antiword error: {e}")
    return None


def extract_text_from_docx(filepath):
    """Читает .docx: параграфы + все таблицы."""
    try:
        doc = Document(filepath)
        paragraphs_text = '\n'.join(
            p.text.strip() for p in doc.paragraphs if p.text.strip()
        )
        tables_text = ""
        for table in doc.tables:
            for row in table.rows:
                row_cells = []
                seen_cells = set()
                for cell in row.cells:
                    ct = cell.text.strip()
                    if ct and ct not in seen_cells:
                        row_cells.append(ct)
                        seen_cells.add(ct)
                if row_cells:
                    tables_text += ' | '.join(row_cells) + '\n'
        full = paragraphs_text + '\n' + tables_text
        return full if full.strip() else ""
    except Exception as e:
        return f"[Ошибка DOCX: {e}]"


# ========================= MAIN DISPATCHER =========================

def extract_text_from_file(filepath):
    """Извлекает текст из файла любого поддерживаемого формата."""
    ext = Path(filepath).suffix.lower()
    try:
        if ext == '.zip':
            if not zipfile.is_zipfile(filepath):
                return "[Ошибка: не ZIP]"
            extract_dir = filepath + "_extracted"
            os.makedirs(extract_dir, exist_ok=True)
            try:
                with zipfile.ZipFile(filepath, 'r') as zf:
                    zf.extractall(extract_dir)
                full_text = ""
                for root, _, files in os.walk(extract_dir):
                    for f in files:
                        sub_path = os.path.join(root, f)
                        full_text += extract_text_from_file(sub_path) + "\n"
                return full_text
            finally:
                shutil.rmtree(extract_dir, ignore_errors=True)

        elif ext in ('.rar', '.7z'):
            extract_dir = filepath + "_extracted"
            os.makedirs(extract_dir, exist_ok=True)
            try:
                try:
                    import patoolib
                    patoolib.extract_archive(filepath, outdir=extract_dir, interactive=False)
                except Exception:
                    if ext == '.rar':
                        subprocess.run(['unrar', 'x', filepath, extract_dir], capture_output=True, check=False)
                    else:
                        subprocess.run(['7z', 'x', filepath, f'-o{extract_dir}', '-y'], capture_output=True, check=False)
                full_text = ""
                for root, _, files in os.walk(extract_dir):
                    for f in files:
                        sub_path = os.path.join(root, f)
                        full_text += extract_text_from_file(sub_path) + "\n"
                return full_text
            finally:
                shutil.rmtree(extract_dir, ignore_errors=True)

        elif ext == '.docx':
            return extract_text_from_docx(filepath)

        elif ext == '.doc':
            text = extract_text_from_doc(filepath)
            return text if text is not None else "[Ошибка чтения .doc]"

        elif ext == '.xlsx':
            try:
                import openpyxl
                wb = openpyxl.load_workbook(filepath, data_only=True)
                text = ""
                for sheet in wb.worksheets:
                    for row in sheet.iter_rows(values_only=True):
                        row_text = ' | '.join(str(cell) for cell in row if cell is not None and str(cell).strip())
                        if row_text.strip():
                            text += row_text + "\n"
                return text
            except Exception as e:
                return f"[Ошибка Excel (.xlsx): {e}]"

        elif ext == '.xls':
            try:
                import xlrd
                wb = xlrd.open_workbook(filepath, formatting_info=False)
                text = ""
                for sheet in wb.sheets():
                    for row in range(sheet.nrows):
                        row_text = ' | '.join(
                            str(sheet.cell_value(row, col))
                            for col in range(sheet.ncols)
                            if str(sheet.cell_value(row, col)).strip()
                        )
                        if row_text.strip():
                            text += row_text + "\n"
                return text
            except ImportError:
                return "[Ошибка Excel (.xls): xlrd не установлен]"
            except Exception as e:
                return f"[Ошибка Excel (.xls): {e}]"

        elif ext == '.rtf':
            if STRIPRTF_AVAILABLE:
                try:
                    with open(filepath, 'r', encoding='windows-1251', errors='ignore') as f:
                        raw = f.read()
                    result = striprtf_to_text(raw)
                    if result and result.strip():
                        return result
                except Exception:
                    pass
            try:
                with open(filepath, 'r', encoding='windows-1251', errors='ignore') as f:
                    raw = f.read()
                text = re.sub(r'\\[a-z]+\d*[ ]?', ' ', raw)
                text = re.sub(r'\{|\}', '', text)
                text = re.sub(r'\s+', ' ', text)
                return text.strip()
            except Exception as e:
                return f"[Ошибка RTF: {e}]"

        elif ext == '.txt':
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                return f.read()

        elif ext == '.pdf':
            return _extract_pdf(filepath)

        elif ext == '.odt':
            return _extract_odt(filepath)

        elif ext == '.ods':
            return _extract_ods(filepath)

        elif ext == '.pptx':
            return _extract_pptx(filepath)

        elif ext == '.bin':
            detected = _detect_extension(filepath)
            if detected and detected != '.bin' and detected != '':
                new_path = filepath[:-4] + detected
                try:
                    os.rename(filepath, new_path)
                    result = extract_text_from_file(new_path)
                    os.rename(new_path, filepath)
                    return result
                except Exception as e:
                    try:
                        tmp_path = filepath + detected
                        shutil.copy2(filepath, tmp_path)
                        result = extract_text_from_file(tmp_path)
                        os.remove(tmp_path)
                        return result
                    except Exception:
                        return f"[BIN: ошибка переименования в {detected}: {e}]"
            return "[BIN: неизвестный формат — magic bytes не распознаны]"

        elif ext in ('.jpg', '.jpeg', '.png', '.bmp', '.gif', '.tiff', '.tif'):
            return _extract_image_ocr(filepath, ext)

        else:
            return ""
    except Exception as e:
        return f"[Ошибка извлечения: {e}]"


# ========================= ВСПОМОГАТЕЛЬНЫЕ =========================

def _detect_extension(filepath):
    """Определяет расширение файла по magic bytes."""
    try:
        with open(filepath, 'rb') as f:
            header = f.read(8)
        if header[:4] == b'%PDF':
            return '.pdf'
        if header[:2] == b'PK':
            try:
                with zipfile.ZipFile(filepath, 'r') as zf:
                    names = set(zf.namelist())
                    if 'word/document.xml' in names:
                        return '.docx'
                    if 'xl/workbook.xml' in names:
                        return '.xlsx'
                    if 'ppt/presentation.xml' in names:
                        return '.pptx'
                    if '[Content_Types].xml' in names:
                        ct = zf.read('[Content_Types].xml').decode('utf-8', errors='ignore')
                        if 'wordprocessingml' in ct:
                            return '.docx'
                        if 'spreadsheetml' in ct:
                            return '.xlsx'
                        if 'presentationml' in ct:
                            return '.pptx'
                    if 'mimetype' in names:
                        mt = zf.read('mimetype').decode('utf-8', errors='ignore').strip()
                        if 'writer' in mt or 'opendocument.text' in mt:
                            return '.odt'
                        if 'calc' in mt or 'spreadsheet' in mt:
                            return '.ods'
                        if 'impress' in mt or 'presentation' in mt:
                            return '.odp'
                    return '.zip'
            except Exception:
                return '.zip'
        if header[:8] == b'\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1':
            return '.doc'
        if header[:5] in (b'{\rtf', b'{\\rtf'):
            return '.rtf'
        if header[:4] == b'\x89PNG':
            return '.png'
        if header[:2] in (b'\xff\xd8',):
            return '.jpg'
        with open(filepath, 'rb') as f:
            sample = f.read(512)
        try:
            text = sample.decode('utf-8', errors='ignore').strip()
            if text.startswith('<'):
                return '.html'
            if text.startswith('{') or text.startswith('['):
                return '.json'
        except Exception:
            pass
    except Exception:
        pass
    return ''


def _extract_pdf(filepath):
    fname = os.path.basename(filepath)
    if FITZ_AVAILABLE:
        try:
            doc = fitz.open(filepath)
            text_pages = []
            ocr_pages = []
            for page_num, page in enumerate(doc, start=1):
                page_text = page.get_text()
                if len(page_text.strip()) >= 30:
                    text_pages.append(page_text)
                else:
                    ocr_pages.append((page_num, page))
            full_text = "\n".join(text_pages)
            if ocr_pages and OCR_AVAILABLE:
                if os.path.exists(TESSERACT_PATH):
                    pytesseract.pytesseract.tesseract_cmd = TESSERACT_PATH
                total_ocr = len(ocr_pages)
                skipped = max(0, total_ocr - OCR_MAX_PAGES)
                ocr_pages_limited = ocr_pages[:OCR_MAX_PAGES]
                if skipped > 0:
                    print(f"      ⚠️ OCR: {fname} — пропущено {skipped} стр. (лимит {OCR_MAX_PAGES})")
                print(f"      ⏳ OCR (fitz): {fname} — {len(ocr_pages_limited)} стр.")
                ocr_text = ""
                for page_num, page in ocr_pages_limited:
                    try:
                        pix = page.get_pixmap(dpi=300)
                        img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                        t = pytesseract.image_to_string(img, lang='rus+eng')
                        if t:
                            ocr_text += t + "\n"
                    except Exception:
                        pass
                if ocr_text:
                    total = len(full_text) + len(ocr_text)
                    print(f"      📄 Извлечено {total} символов (текст+OCR)")
                full_text = full_text + "\n" + ocr_text if ocr_text else full_text
            doc.close()
            if full_text.strip():
                return full_text
        except Exception:
            pass

    try:
        import pdfplumber
        text = ""
        with pdfplumber.open(filepath) as pdf:
            for page in pdf.pages:
                t = page.extract_text()
                if t:
                    text += t + "\n"
        if text.strip():
            return text
    except ImportError:
        pass
    except Exception:
        pass

    if OCR_AVAILABLE and PDF2IMAGE_AVAILABLE:
        print(f"      ⏳ OCR (poppler): {fname}")
        try:
            if os.path.exists(TESSERACT_PATH):
                pytesseract.pytesseract.tesseract_cmd = TESSERACT_PATH
            images = convert_from_path(filepath, dpi=300, poppler_path=POPPLER_PATH)
            ocr_text = ""
            for img in images:
                t = pytesseract.image_to_string(img, lang='rus+eng')
                if t:
                    ocr_text += t + "\n"
            return ocr_text if ocr_text else "[OCR не дал текста]"
        except Exception as e:
            return f"[Ошибка OCR: {e}]"

    if FITZ_AVAILABLE and OCR_AVAILABLE:
        try:
            doc = fitz.open(filepath)
            if os.path.exists(TESSERACT_PATH):
                pytesseract.pytesseract.tesseract_cmd = TESSERACT_PATH
            print(f"      ⏳ OCR (fitz, повтор): {fname}")
            ocr_text = ""
            for page in doc:
                pix = page.get_pixmap(dpi=300)
                img = Image.frombytes("RGB", [pix.width, pix.height], pix.samples)
                t = pytesseract.image_to_string(img, lang='rus+eng')
                if t:
                    ocr_text += t + "\n"
            doc.close()
            return ocr_text if ocr_text else "[OCR не дал текста]"
        except Exception as e:
            return f"[Ошибка OCR: {e}]"

    return "[PDF: нет доступного метода извлечения — установите PyMuPDF: pip install pymupdf]"


def _extract_odt(filepath):
    try:
        from odf.opendocument import load as odf_load
        doc = odf_load(filepath)
        paragraphs = []
        def _collect_text(node):
            if hasattr(node, 'childNodes'):
                for child in node.childNodes:
                    if hasattr(child, 'data'):
                        paragraphs.append(child.data)
                    else:
                        _collect_text(child)
        _collect_text(doc.text)
        text = "\n".join(p for p in paragraphs if p.strip())
        if text.strip():
            return text
    except ImportError:
        pass
    except Exception:
        pass
    try:
        with zipfile.ZipFile(filepath, 'r') as zf:
            if 'content.xml' in zf.namelist():
                xml_bytes = zf.read('content.xml')
                xml_text = xml_bytes.decode('utf-8', errors='ignore')
                text = re.sub(r'<[^>]+>', ' ', xml_text)
                text = re.sub(r'\s+', ' ', text).strip()
                if text:
                    return text
    except Exception as e:
        return f"[Ошибка ODT: {e}]"
    return "[ODT: не удалось извлечь текст — установите odfpy: pip install odfpy]"


def _extract_ods(filepath):
    try:
        from odf.opendocument import load as odf_load
        from odf.table import Table, TableRow, TableCell
        from odf.text import P as OdfP
        doc = odf_load(filepath)
        rows_text = []
        for sheet in doc.spreadsheet.getElementsByType(Table):
            for row in sheet.getElementsByType(TableRow):
                cells = []
                for cell in row.getElementsByType(TableCell):
                    cell_parts = []
                    for p in cell.getElementsByType(OdfP):
                        def _collect(node, parts):
                            if hasattr(node, 'data'):
                                parts.append(node.data)
                            if hasattr(node, 'childNodes'):
                                for ch in node.childNodes:
                                    _collect(ch, parts)
                        _collect(p, cell_parts)
                    cells.append(" ".join(cell_parts))
                line = "\t".join(cells).strip()
                if line:
                    rows_text.append(line)
        text = "\n".join(rows_text)
        if text.strip():
            return text
    except ImportError:
        pass
    except Exception:
        pass
    try:
        with zipfile.ZipFile(filepath, 'r') as zf:
            if 'content.xml' in zf.namelist():
                xml_bytes = zf.read('content.xml')
                xml_text = xml_bytes.decode('utf-8', errors='ignore')
                text = re.sub(r'<[^>]+>', ' ', xml_text)
                text = re.sub(r'\s+', ' ', text).strip()
                if text:
                    return text
    except Exception as e:
        return f"[Ошибка ODS: {e}]"
    return "[ODS: не удалось извлечь текст — установите odfpy: pip install odfpy]"


def _extract_pptx(filepath):
    try:
        from pptx import Presentation
        prs = Presentation(filepath)
        slide_texts = []
        for slide in prs.slides:
            parts = []
            for shape in slide.shapes:
                if hasattr(shape, "text") and shape.text.strip():
                    parts.append(shape.text.strip())
            if parts:
                slide_texts.append("\n".join(parts))
        text = "\n\n".join(slide_texts)
        if text.strip():
            return text
    except ImportError:
        pass
    except Exception:
        pass
    try:
        with zipfile.ZipFile(filepath, 'r') as zf:
            slide_files = sorted(
                [n for n in zf.namelist() if re.match(r'ppt/slides/slide\d+\.xml', n)]
            )
            slide_texts = []
            for sf in slide_files:
                xml_bytes = zf.read(sf)
                xml_text = xml_bytes.decode('utf-8', errors='ignore')
                text = re.sub(r'<[^>]+>', ' ', xml_text)
                text = re.sub(r'\s+', ' ', text).strip()
                if text:
                    slide_texts.append(text)
            text = "\n\n".join(slide_texts)
            if text.strip():
                return text
    except Exception as e:
        return f"[Ошибка PPTX: {e}]"
    return "[PPTX: не удалось извлечь текст — установите python-pptx: pip install python-pptx]"


def _extract_image_ocr(filepath, ext):
    fname = os.path.basename(filepath)
    if OCR_AVAILABLE:
        try:
            if os.path.exists(TESSERACT_PATH):
                pytesseract.pytesseract.tesseract_cmd = TESSERACT_PATH
            img = Image.open(filepath)
            t = pytesseract.image_to_string(img, lang='rus+eng')
            if t and t.strip():
                return t
            print(f"      🖼️ Чертёж ({ext[1:].upper()}): {fname} — OCR не дал текста, просмотри вручную")
            return f"[Изображение: {fname} — OCR не дал текста, требует ручного просмотра]"
        except Exception as e:
            print(f"      🖼️ Чертёж ({ext[1:].upper()}): {fname} — просмотри вручную ({e})")
            return f"[Изображение: {fname} — требует ручного просмотра]"
    else:
        print(f"      🖼️ Чертёж ({ext[1:].upper()}): {fname} — просмотри вручную (tesseract не установлен)")
        return f"[Изображение: {fname} — требует ручного просмотра (установите tesseract для OCR)]"


# ========================= УМНАЯ ЭКСТРАКЦИЯ =========================

_SECTION_KEYWORDS = [
    'срок поставки', 'срок исполнения', 'срок выполнения', 'сроки поставки',
    'сроки исполнения', 'поставить в течение', 'поставка в течение',
    'срок приёмки', 'срок приемки', 'срок оплаты', 'порядок оплаты',
    'адрес поставки', 'адрес доставки', 'место поставки', 'место доставки',
    'казначейское сопровождение',
    'официальный дилер', 'авторизованный дилер', 'аккредитованный дилер',
    'карта партнёра', 'карта партнера', 'partner card', 'дилерское соглашение',
    'страна происхождения', 'российское производство', 'реестр российской',
    'запрет иностранных', 'национальный режим', 'ограничение допуска',
    'спецификация', 'техническое задание', 'перечень товаров', 'ведомость',
    'начальная максимальная цена', 'нмцк', 'нмцд',
    'ндс', 'налог на добавленную стоимость',
    'гарантийный срок', 'гарантия качества',
    'обеспечение заявки', 'обеспечение контракта',
    'производитель', 'изготовитель', 'торговая марка', 'товарный знак',
    'бренд', 'brand', 'made by', 'manufacturer', 'производства',
]
_SECTION_CONTEXT_CHARS = 1500


def extract_relevant_sections(full_text, first_chars=15000):
    """Умная экстракция: начало документа + релевантные разделы по ключевым словам."""
    if len(full_text) <= first_chars:
        return full_text
    result_parts = [full_text[:first_chars]]
    total_len = first_chars
    covered_buckets = set()
    remainder = full_text[first_chars:]
    remainder_offset = first_chars
    remainder_lower = remainder.lower()
    for kw in _SECTION_KEYWORDS:
        if total_len >= MAX_TEXT_PER_FILE:
            break
        pos = remainder_lower.find(kw.lower())
        if pos == -1:
            continue
        frag_start = max(0, pos - _SECTION_CONTEXT_CHARS)
        frag_end = min(len(remainder), pos + len(kw) + _SECTION_CONTEXT_CHARS)
        bucket = (remainder_offset + frag_start) // 500
        if bucket in covered_buckets:
            continue
        covered_buckets.add(bucket)
        abs_pos_k = (remainder_offset + pos) // 1000
        fragment = (
            f"\n\n[...раздел из позиции ~{abs_pos_k}к символов...]\n"
            + remainder[frag_start:frag_end]
        )
        result_parts.append(fragment)
        total_len += len(fragment)
    return "\n".join(result_parts)


def is_critical_file(filename, content, success_files):
    name_lower = filename.lower()
    has_keyword = any(kw in name_lower for kw in CRITICAL_KEYWORDS)
    if not has_keyword:
        return False
    for other in success_files:
        other_lower = other.lower()
        if any(kw in other_lower for kw in CRITICAL_KEYWORDS):
            return False
    return True


def extract_texts_from_paths(downloaded_paths, max_total=None, max_per_file=None):
    """
    Извлекает и объединяет текст из всех скачанных файлов.
    Возвращает (doc_text, critical_errors, success_files, extraction_errors).
    """
    if max_total is None:
        max_total = MAX_TEXT_TOTAL
    if max_per_file is None:
        max_per_file = MAX_TEXT_PER_FILE

    doc_text = ""
    extraction_errors = []
    success_files = []
    total_chars = 0

    brand_hints_from_full = []  # бренды найденные regex по полному тексту до обрезки

    for fpath in downloaded_paths:
        filename = os.path.basename(fpath)
        text = extract_text_from_file(fpath)
        if text and not text.startswith(("[Ошибка", "[OCR не дал текста]", "[OCR недоступен]",
                                          "[Ошибка чтения .doc]", "[PDF parsing not available]")):
            # ── Regex-сканер по ПОЛНОМУ тексту (без лимита символов) ──────────
            full_brand = extract_manufacturer_from_chunks(text, filename)
            if full_brand:
                brand_hints_from_full.append(full_brand)
                print(f"    🔎 Полный скан «{filename}»: найден производитель → {full_brand}")
            else:
                print(f"    🔎 Полный скан «{filename}»: производитель не найден regex")

            # ── Умная выборка секций для LLM (лимит контекстного окна) ───────
            file_text = extract_relevant_sections(text)
            file_block = f"\n--- Начало файла {filename} ---\n{file_text}\n--- Конец файла ---\n"
            extracted_note = f"{len(file_text)} из {len(text)}" if len(text) > len(file_text) else str(len(text))
            print(f"    📄 Извлечено {extracted_note} символов из {filename}")
            doc_text += file_block
            total_chars += len(file_block)
            success_files.append(filename)
            if total_chars >= max_total:
                print(f"  ⚠️ Достигнут лимит текста ({max_total} символов), остальные файлы пропущены")
                break
        else:
            extraction_errors.append((filename, text[:100] if text else 'пусто'))
            print(f"    ⚠️ Ошибка извлечения из {filename}: {text[:100] if text else 'пусто'}")

    # Инжектируем найденные бренды в начало doc_text как явную подсказку для LLM
    if brand_hints_from_full:
        unique_hints = list(dict.fromkeys(brand_hints_from_full))
        injection = (
            "\n[ПРОИЗВОДИТЕЛИ ИЗ ПОЛНОГО СКАНА ДОКУМЕНТОВ (найдены regex по всему тексту): "
            + ", ".join(unique_hints)
            + "]\n"
        )
        doc_text = injection + doc_text
        print(f"  💡 Инжектировано в промпт: {', '.join(unique_hints)}")

    critical_errors = []
    if doc_text.strip():
        for err_name, _ in extraction_errors:
            if is_critical_file(err_name, None, success_files):
                critical_errors.append(err_name)
    else:
        critical_errors = [name for name, _ in extraction_errors]

    return doc_text, critical_errors, success_files, extraction_errors

