# BRAND
# ======================================================================


def extract_hints_from_text(text):
    """
    Извлекает из текста документов подсказки:
    - НМЦК, количество позиций, срок поставки (с переводом из рабочих дней)
    - Заказчик, адрес поставки
    - Производители / бренды (части А→Б→В→Г)
    Возвращает строку для вставки в промпт.
    """
    hints = []
    # НМЦК
    nmck_patterns = [
        r'(?:НМЦК|НМЦД|начальная\s*(?:максимальная)?\s*цена|цена\s*контракта|стоимость\s*договора)[:\s]*([\d\s]+(?:[.,]\d+)?)\s*(?:руб|₽|RUB)',
        r'(\d{1,3}(?:[\s]\d{3})*(?:[.,]\d{2})?)\s*(?:руб|₽|RUB)',
    ]
    for pattern in nmck_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            val = match.group(1).strip().replace(' ', '')
            hints.append(f"Подсказка из файлов: возможная НМЦК = {val} руб.")
            break

    # Количество позиций
    qty_patterns = [
        r'(?:количество\s*позиций|всего\s*позиций|перечень\s*товаров)[:\s]*(\d+)',
        r'(\d+)\s*позици[ейю]',
    ]
    for pattern in qty_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            hints.append(f"Подсказка из файлов: количество позиций = {match.group(1)}.")
            break

    # Срок поставки (расширенные паттерны + перевод рабочих дней в календарные)
    term_patterns = [
        (r'(?:срок\s*поставки|срок\s*доставки|период\s*поставки)[:\s]*(\d+)\s*(рабочих?\s*дней?|календарных?\s*дней?|дней?|месяцев?)', True),
        (r'(?:доставка\s*в\s*течение|в\s*течение\s*)(\d+)\s*(рабочих?\s*дней?|календарных?\s*дней?|дней?)', True),
        (r'(?:поставка\s*(?:осуществляется|производится)\s*(?:в\s*течение)?\s*)(\d+)\s*(рабочих?\s*дней?|календарных?\s*дней?|дней?)', True),
        (r'(?:не\s*позднее\s*)(\d+)\s*(рабочих?\s*дней?|календарных?\s*дней?|дней?)', True),
        (r'(?:срок\s*исполнения[:\s]*)(\d+)\s*(рабочих?\s*дней?|календарных?\s*дней?|дней?)', True),
        (r'(\d+)\s*(рабочих?\s*дней?)\s*с\s*(?:момента|даты)\s*(?:заключения|подписания)', True),
        (r'(\d+)\s*(календарных?\s*дней?)\s*с\s*(?:момента|даты)\s*(?:заключения|подписания)', True),
        (r'(?:поставить\s*до\s*)(\d{2}\.\d{2}\.\d{4})', False),
        (r'(?:не\s*позднее\s*)(\d{2}\.\d{2}\.\d{4})', False),
    ]
    for pattern, has_unit in term_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            if 'течение' in pattern and re.search(
                    r'оплат|расч[её]т|приемк|подписан',
                    text[max(0, match.start() - 40):match.start()], re.IGNORECASE):
                continue
            days_val = match.group(1).strip()
            if has_unit and match.lastindex >= 2:
                unit_str = (match.group(2) or '').strip().lower()
                days_num_match = re.match(r'\d+', days_val)
                if days_num_match:
                    days_num = int(days_num_match.group())
                    if 'рабочих' in unit_str or 'рабочи' in unit_str:
                        days_calendar = math.ceil(days_num * 1.4)
                        hints.append(f"Подсказка из файлов: возможный срок поставки: {days_calendar} (переведено из {days_num} рабочих дней).")
                    else:
                        hints.append(f"Подсказка из файлов: возможный срок поставки: {days_num}.")
            else:
                hints.append(f"Подсказка из файлов: возможный срок поставки: {days_val}.")
            break

    # Заказчик
    customer_pattern = r'(?:заказчик|клиент|покупатель|организация)[:\s]*([А-ЯЁ][а-яё]*(?:\s+[А-ЯЁ][а-яё]*)*\s*(?:ООО|АО|ПАО|ГУП|МУП|ИП|ФГУП)\s+["«]?[А-ЯЁа-яё\s]+["»]?)'
    match = re.search(customer_pattern, text, re.IGNORECASE)
    if match:
        hints.append(f"Подсказка из файлов: возможный заказчик: {match.group(1).strip()}.")

    # Адрес
    address_patterns = [
        r'(?:адрес\s*поставки|место\s*доставки|поставка\s*по\s*адресу)[:\s]*([А-ЯЁ][а-яё\s,\.\d]+(?:г\.|обл\.|край|респ\.)[А-ЯЁа-яё\s,\.\d]+)',
        r'(?:г\.\s*([А-ЯЁ][а-яё]+)[,\s]*ул\.\s*[А-ЯЁа-яё]+[\s\d]+)',
    ]
    for pattern in address_patterns:
        match = re.search(pattern, text, re.IGNORECASE)
        if match:
            hints.append(f"Подсказка из файлов: возможный адрес поставки: {match.group(1).strip()}.")
            break

    # Python-скан бренда удалён (заменён надёжным гейтом _is_reliable_brand).
    # ЛЛМ сам определяет производителя из документов.
    return "\n".join(hints) if hints else ""


# ========================= ИЗВЛЕЧЕНИЕ БРЕНДА =========================


_MANUFACTURER_PATTERNS = [
    # ── Прямое именование производителя ──────────────────────────────────────
    r'(?:производитель|изготовитель|завод.изготовитель)\s*[:：]\s*([A-ZА-ЯЁ][^\n]{3,80})',
    r'наименование\s+(?:производителя|изготовителя|организации.изготовителя)\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    r'(?:фирма|компания|предприятие).производитель\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    # ── Торговые наименования и марки ────────────────────────────────────────
    r'торговое\s+наименование\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    r'товарное\s+наименование\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    r'(?:торговая\s+марка|товарный\s+знак|торговый\s+знак)\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    r'(?:марка\s+(?:товара|и\s+модель|оборудования|изделия)?|марка)\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    r'(?:бренд|brand)\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    # ── Модель и артикул ─────────────────────────────────────────────────────
    r'(?:модель|model)\s+(?:оборудования\s*)?[:：]\s*([A-ZА-ЯЁA-Za-z][A-ZА-ЯЁA-Za-z0-9\-]{2,40})',
    r'артикул\s+(?:производителя|изготовителя)?\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,40})',
    r'каталожный\s+номер\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,40})',
    # ── Принадлежность продукции компании ────────────────────────────────────
    r'продукция\s+(?:компании|фирмы|завода|бренда)\s+["\']?([A-ZА-ЯЁA-Za-z][^\n"\']{2,60})["\']?',
    r'(?:товары?|оборудование|изделия)\s+(?:компании|фирмы|бренда)\s+["\']?([A-ZА-ЯЁA-Za-z][^\n"\']{2,60})["\']?',
    r'поставляется?\s+(?:только\s+)?(?:товар\s+)?производства\s+["\']?([A-ZА-ЯЁA-Za-z][^\n"\']{2,60})["\']?',
    r'товар\s+производства\s+([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    # ── Страна происхождения + производитель ─────────────────────────────────
    r'страна\s+происхождения\s+(?:и\s+)?(?:производитель|изготовитель)\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,60})',
    r'(?:производитель|изготовитель)[,;]\s*страна\s*[:：]\s*([A-ZА-ЯЁA-Za-z][^\n]{2,40})',
    # ── Аналоги и эквиваленты ────────────────────────────────────────────────
    r'(?:аналог|эквивалент)\s+(?:продукции\s+)?["\']?([A-Z][A-Za-z]{2,30})["\']?',
    r'([A-Z][A-Za-z]{2,30})\s+или\s+(?:аналог|эквивалент)',
    # ── Латинские компании по юридической форме ──────────────────────────────
    r'\b([A-Z][A-Za-z]{2,30}(?:\s+[A-Z][A-Za-z]{1,20})?)\s+(?:GmbH|AG|KG|Ltd\.?|LLC|Inc\.?|S\.A\.|S\.p\.A\.|SRL|Corp\.?|B\.V\.|N\.V\.|Oy|AB|AS)\b',
    # ── Зарегистрированная марка ─────────────────────────────────────────────
    r'зарегистрированная\s+(?:торговая\s+)?марка\s+["\']?([A-ZА-ЯЁ][^\n"\']{2,60})["\']?',
    # ── Модель как первое слово перед кодом артикула ─────────────────────────
    r'(?:^|\n|\|)\s*(?:\d+[\.\)]\s*)?([A-Z]{2,15})\s+[A-Za-z0-9]{2,20}[\-/][A-Za-z0-9]{2,20}',
    # ── B4: mixed-case бренд + модель (Grundfos CR32-4, Siemens 6ES7…) ────
    r'(?:^|\n|\|)\s*(?:\d+[\.\)]\s*)?([A-Z][a-z]{2,15})\s+'
    r'(?=[A-Za-z0-9\-/]*[A-Za-z])(?=[A-Za-z0-9\-/]*[0-9])[A-Za-z0-9\-/]{3,20}',
]

_EXCLUDE_MANUFACTURER_PATTERNS = re.compile(
    r'\b(заказчик|исполнитель|поставщик|подрядчик|покупатель|продавец|сторон[аы]|'
    r'организация|учреждение|предприятие|общество|ооо|ао|зао|пао|гуп|муп|фгуп|'
    r'фгбу|министерство|департамент|управление|администрация|комитет|служба|агентство)\b',
    re.IGNORECASE
)

_CHUNK_SIZE = 5000
_CHUNK_OVERLAP = 500


def extract_manufacturer_from_chunks(doc_text, subject_str=""):
    """
    Дробит текст на чанки и ищет производителей.
    Возвращает строку или None.
    """
    if not doc_text or not doc_text.strip():
        return None

    all_candidates = []
    seen = set()
    step = _CHUNK_SIZE - _CHUNK_OVERLAP
    # Сканируем ВЕСЬ текст без раннего выхода — бренд может быть в конце документа
    for start in range(0, len(doc_text), step):
        chunk = doc_text[start:start + _CHUNK_SIZE]
        for pat in _MANUFACTURER_PATTERNS:
            for m in re.finditer(pat, chunk, re.IGNORECASE | re.MULTILINE):
                raw = m.group(1).strip().rstrip('.,;:')
                if len(raw) < 3 or len(raw) > 80:
                    continue
                if _EXCLUDE_MANUFACTURER_PATTERNS.search(raw):
                    continue
                upper = raw.upper()
                if upper in BRAND_BLACKLIST:
                    continue
                if upper not in seen:
                    seen.add(upper)
                    all_candidates.append(raw)

    if not all_candidates:
        return None
    # Предпочитаем те, что содержат латиницу (международный бренд)
    latin_first = [c for c in all_candidates if re.search(r'[A-Za-z]{3,}', c)]
    return (latin_first[0] if latin_first else all_candidates[0])


_PRODUCT_CATEGORIES = {
    # Категория → список NON-manufacturer keywords
    'equipment': [
        r'мотор|двигател|насос|компрессор|агрегат|станок|пресс|редуктор|генератор|трансформатор'
    ],
    'chemicals': [
        r'реагент|химикат|реактив|флокулянт|коагулянт|ингибитор'
    ],
    'instruments': [
        r'датчик|манометр|термометр|расходомер|счётчик|контроллер|преобразователь'
    ],
    'cables': [
        r'кабель|провод|шнур|жил[аы]'
    ],
}

_CUSTOMER_PATTERNS = re.compile(
    r'\b(государственн|муниципальн|бюджетн|казённ|автономн|унитарн|'
    r'федеральн|региональн|областн|краевой|городской)\b.*\b(учреждени|предприяти|организаци)\b',
    re.IGNORECASE
)


def validate_manufacturer_for_category(brand_str, subject_str=""):
    """
    Проверяет, что найденный бренд является производителем товара (а не заказчиком).
    Возвращает True если бренд подходит.
    """
    if not brand_str:
        return False

    # Однозначно не производитель — организационные маркеры
    if _EXCLUDE_MANUFACTURER_PATTERNS.search(brand_str):
        return False

    # Бренды с латиницей — скорее всего производители
    if re.search(r'[A-Za-z]{3,}', brand_str):
        return True

    # Проверяем по категории предмета закупки
    subject_lower = subject_str.lower()
    for cat, patterns in _PRODUCT_CATEGORIES.items():
        for pat in patterns:
            if re.search(pat, subject_lower):
                # Для этой категории — проверяем, что бренд не звучит как заказчик
                if _CUSTOMER_PATTERNS.search(brand_str):
                    return False
                return True

    # По умолчанию — принимаем
    if len(brand_str) >= 3 and not _CUSTOMER_PATTERNS.search(brand_str):
        return True
    return False


# ========================= СТРАНА ПРОИЗВОДИТЕЛЯ =========================

def lookup_brand_country(brand_hint):
    """
    Ищет страну производителя через Serper.
    Возвращает строку страны или None.
    """

    if not brand_hint or len(brand_hint) < 3:
        return None

    # Пробуем определить по известным признакам без поиска
    if re.search(r'\b(GmbH|AG|KG|OHG)\b', brand_hint):
        return "Германия"
    if re.search(r'\b(S\.A\.|SARL|SAS)\b', brand_hint):
        return "Франция"
    if re.search(r'\b(Ltd|plc|LLP)\b', brand_hint) and not re.search(r'\bInc\b', brand_hint):
        return "Великобритания"
    if re.search(r'\b(Inc\.|LLC|Corp\.|Corporation)\b', brand_hint):
        return None  # США или другие — нужен поиск

    query = f"{brand_hint} manufacturer country of origin headquarters"
    results = _web_search(query, max_results=3)
    if not results:
        return None

    combined_text = " ".join(r.get('snippet', '') + " " + r.get('title', '') for r in results).lower()

    country_patterns = [
        (r'\b(германи|germany|deutsch)\b', "Германия"),
        (r'\b(япони|japan|japanese)\b', "Япония"),
        (r'\b(китай|china|chinese|кнр)\b', "Китай"),
        (r'\b(сша|usa|united states|america|american)\b', "США"),
        (r'\b(корея|korea|korean|дания|denmark|danish)\b', "Корея"),
        (r'\b(италия|italy|italian)\b', "Италия"),
        (r'\b(швейцари|switzerland|swiss)\b', "Швейцария"),
        (r'\b(франци|france|french)\b', "Франция"),
        (r'\b(швеци|sweden|swedish)\b', "Швеция"),
        (r'\b(австри|austria|austrian)\b', "Австрия"),
        (r'\b(финлянди|finland|finnish)\b', "Финляндия"),
        (r'\b(нидерланд|netherlands|dutch|голланди)\b', "Нидерланды"),
        (r'\b(чехи|czech)\b', "Чехия"),
        (r'\b(турци|turkey|turkish)\b', "Турция"),
        (r'\b(тайван|taiwan|taiwanese)\b', "Тайвань"),
    ]
    for pat, country in country_patterns:
        if re.search(pat, combined_text, re.IGNORECASE):
            return country
    return None

