# ========================= LLM-ВЫЗОВ =========================

def call_deepseek(prompt):
    """
    Единая функция вызова LLM.
    Основной: DeepSeek (deepseek-chat).
    Резерв: OpenRouter (Qwen3-235B) если нет DEEPSEEK_API_KEY.
    """
    if DEEPSEEK_API_KEY:
        url = "https://api.deepseek.com/v1/chat/completions"
        headers = {"Authorization": f"Bearer {DEEPSEEK_API_KEY}", "Content-Type": "application/json"}
        payload = {
            "model": "deepseek-chat",
            "messages": [{"role": "user", "content": prompt}],
            "temperature": 0.2,
        }
        timeout = 90
    else:
        url = "https://openrouter.ai/api/v1/chat/completions"
        headers = {
            "Authorization": f"Bearer {OPENROUTER_API_KEY}",
            "Content-Type": "application/json",
            "HTTP-Referer": "https://vitro-logistic.ru",
            "X-Title": "Vitro Tender Tool",
        }
        payload = {
            "model": "qwen/qwen3-235b-a22b-2507",
            "messages": [{"role": "user", "content": prompt}],
            "temperature": 0.2,
        }
        timeout = 120

    for attempt in range(5):
        try:
            resp = requests.post(url, headers=headers, json=payload, timeout=timeout)
            if resp.status_code == 200:
                return resp.json()['choices'][0]['message']['content']
            elif resp.status_code == 401:
                print(f"  API ошибка 401 (неверный ключ) — повторные попытки бессмысленны")
                return None
            elif resp.status_code == 429:
                wait = 30 * (attempt + 1)
                print(f"  API ошибка 429 (rate limit) — ждём {wait} сек. (попытка {attempt + 1})")
                time.sleep(wait)
            else:
                print(f"  API ошибка {resp.status_code}, попытка {attempt + 1}")
                time.sleep(5)
        except requests.exceptions.SSLError as e:
            wait = 15 * (attempt + 1)
            print(f"  API SSL-ошибка: {e}, попытка {attempt + 1} — ждём {wait} сек.")
            time.sleep(wait)
        except Exception as e:
            wait = 5 * (2 ** attempt)
            print(f"  API исключение: {e}, попытка {attempt + 1} — ждём {wait} сек.")
            time.sleep(wait)
    return None


# ========================= РАЗБОР ОТВЕТА =========================

_SELF_CONTRADICTION_PHRASES = (
    'не является стоп-фактором',
    'стоп-фактор не применяется',
    'стоп-фактор не срабатывает',
    'решение пересмотрено',
    'стоп фактор не применяется',
)

_STOPFACTOR_TRIGGERED_PHRASES = (
    'стоп-фактор срабатывает',
    'стоп фактор срабатывает',
    'применяется стоп-фактор',
    'стоп-фактор применяется',
    'стоп фактор применяется',
    'срабатывает стоп-фактор',
    'срабатывает стоп фактор',
)

# Регулярное выражение дополнительно ловит «Стоп-фактор #N срабатывает» и «срабатывает стоп-фактор #N»
_STOPFACTOR_TRIGGERED_RE = re.compile(
    r'стоп[\s\-]?фактор\s*(?:#\s*\d+\s*)?(?:срабатывает|применяется)|'
    r'(?:срабатывает|применяется)\s*стоп[\s\-]?фактор',
    re.IGNORECASE
)


def _has_self_contradiction(text):
    lower = text.lower()
    return any(p in lower for p in _SELF_CONTRADICTION_PHRASES)


def _has_stopfactor_triggered(text):
    lower = text.lower()
    if any(p in lower for p in _STOPFACTOR_TRIGGERED_PHRASES):
        return True
    return bool(_STOPFACTOR_TRIGGERED_RE.search(text))


def classify_deepseek_response(response):
    """
    Определяет решение из ответа LLM.

    Ключевые правила:
    - Проверяем ТОЛЬКО первую строку вида «Решение: …»
    - Самопротиворечие проверяем ТОЛЬКО в коротком (≤300 символов) «ярлыке» решения,
      а не во всём длинном тексте строки — ЛЛМ иногда вставляет рассуждения прямо
      в строку «Решение:», и ранняя проверка давала ложное «clarify» вместо «not_participate».
    - Если решение «не участвуем» И в ПОЛНОМ ответе стоп-фактор всё же срабатывает
      (ЛЛМ в итоге нашёл причину) — доверяем «not_participate».
    """
    lines = response.split('\n')
    for line in lines:
        stripped = line.strip()
        if not stripped.lower().startswith('решение:'):
            continue
        decision_part = line.split(':', 1)[1].strip().lower()

        if 'не участвуем' in decision_part:
            # Проверяем самопротиворечие только в НАЧАЛЕ строки решения
            # (первые 300 символов после «Решение:»), игнорируя длинные рассуждения
            short_label = decision_part[:300]
            if _has_self_contradiction(short_label) and not _has_stopfactor_triggered(response):
                return 'clarify'
            return 'not_participate'

        elif 'участвуем' in decision_part:
            # Если ЛЛМ написал «участвуем» но в тексте всё равно сработал стоп-фактор
            if _has_stopfactor_triggered(response):
                return 'not_participate'
            return 'participate'

        elif 'требуется уточнение' in decision_part:
            if _has_stopfactor_triggered(response):
                return 'not_participate'
            return 'clarify'

        # Первая строка «Решение:» найдена, но тип не распознан — дальше не ищем
        break

    # Fallback: ищем в первых 10 строках
    first_lines = '\n'.join(response.split('\n')[:10]).lower()
    if 'не участвуем' in first_lines:
        short = first_lines[:400]
        if _has_self_contradiction(short) and not _has_stopfactor_triggered(response):
            return 'clarify'
        return 'not_participate'
    elif 'участвуем' in first_lines:
        return 'participate'
    elif 'требуется уточнение' in first_lines:
        return 'clarify'
    return 'clarify'


def extract_rejection_reason(response):
    lines = response.split('\n')
    for line in lines:
        if line.strip().startswith('Решение:') and 'не участвуем' in line:
            match = re.search(r'Причина:\s*(.+)', line, re.IGNORECASE)
            if match:
                return match.group(1).strip()
            parts = line.split('не участвуем', 1)
            if len(parts) > 1:
                reason = parts[1].strip().lstrip('.,;: ')
                if reason:
                    return reason
    return "не указана"


def extract_china_flag(response):
    match = re.search(r'Доступность закупки в Китае:\s*(Да|Нет)', response, re.IGNORECASE)
    if match:
        return match.group(1).lower() == 'да'
    if re.search(r'(китай|china)', response, re.IGNORECASE):
        if not re.search(r'(запрет|только российское|не допускаются)', response, re.IGNORECASE):
            return True
    return False


def clean_response_preamble(response):
    """Убирает <think>...</think> и выбирает последний структурный отчёт."""
    response = re.sub(r'<think>.*?</think>', '', response, flags=re.DOTALL).strip()

    # Убираем дубли «Решение:» — оставляем только последнее вхождение.
    # LLM иногда пишет промежуточный вывод («думает вслух»), затем переформулирует.
    all_lines = response.split('\n')
    decision_indices = [i for i, l in enumerate(all_lines)
                        if l.strip().lower().startswith('решение:')]
    if len(decision_indices) > 1:
        keep_idx = decision_indices[-1]
        all_lines = [l for i, l in enumerate(all_lines)
                     if not l.strip().lower().startswith('решение:') or i == keep_idx]
        response = '\n'.join(all_lines)

    matches = list(re.finditer(r'---\s*Основная информация\s*---', response))
    if matches:
        start = matches[-1].start()
        preceding_lines = [l for l in response[:start].splitlines() if l.strip()]
        decision_prefix = ""
        for line in reversed(preceding_lines[-5:]):
            if line.strip().lower().startswith('решение:'):
                decision_prefix = line.strip() + "\n\n"
                break
        response = decision_prefix + response[start:]
        return response
    section_match = re.search(r'---\s+\S', response)
    if section_match:
        response = response[section_match.start():]
    return response


def postprocess_response(response, combined_hints):
    """Постобработка ответа: замены фраз, автоподстановки, исправление НДС."""
    response = re.sub(
        r'не удалось определить',
        'информация отсутствует в документации',
        response, flags=re.IGNORECASE
    )
    response = re.sub(
        r'(Срок приемки:\s*)(информация отсутствует в документации)',
        r'\g<1>1 рабочий день',
        response, flags=re.IGNORECASE
    )
    if "возможный срок поставки:" in combined_hints:
        match = re.search(r'возможный срок поставки:\s*(\d+)', combined_hints)
        if match:
            days = match.group(1)
            if re.search(r'Срок поставки:\s*информация отсутствует в документации', response, re.IGNORECASE):
                response = re.sub(
                    r'(Срок поставки:\s*)информация отсутствует в документации',
                    r'\g<1>' + str(days) + ' дней',
                    response, flags=re.IGNORECASE
                )
                print(f"  Принудительно установлен срок поставки: {days} дней")

    def _fix_nds_rate(m):
        return re.sub(r'\b22\s*%', '20%', m.group(0))
    response = re.sub(
        r'^НДС:[^\n]*$', _fix_nds_rate, response,
        flags=re.IGNORECASE | re.MULTILINE
    )
    return response


def python_validate_term(response):
    """Python-валидация срока поставки. Возвращает (days, reason) или (None, None)."""
    match = re.search(r'Срок поставки:\s*([^\n]+)', response, re.IGNORECASE)
    if not match:
        return None, None
    term_str = match.group(1).strip()
    term_lower = term_str.lower()
    if any(x in term_lower for x in (
        'информация отсутствует', 'не указан', 'не определён',
        'не установлен', 'не указано', 'уточняется'
    )):
        return None, None
    if re.search(r'\d{1,2}\.\d{2}\.\d{4}', term_str):
        return None, None
    if re.search(
        r'\b(январ|феврал|март|апрел|май|июн|июл|август|сентябр|октябр|ноябр|декабр)',
        term_lower
    ):
        return None, None
    work_match = re.search(r'(\d+)\s*(?:\([^)]+\)\s*)?рабочих?\s*дн', term_lower)
    if work_match:
        work = int(work_match.group(1))
        cal = math.ceil(work * 1.4)
        if cal < 30:
            return cal, f"срок поставки {work} рабочих дней = {cal} кал. дней < 30"
        return None, None
    num_match = re.search(r'(\d+)\s*(?:календарных?\s*дней?|рабочих?\s*дней?|дней?)', term_lower)
    if not num_match:
        num_match = re.search(r'(\d+)', term_str)
    if num_match:
        days = int(num_match.group(1))
        if 1 <= days <= 365 and days < 30:
            return days, f"срок поставки {days} дней < 30 календарных"
    return None, None


def analyze_response_completeness(response_text):
    required_fields = ["Заказчик", "Срок поставки", "Адрес поставки", "НМЦК/НМЦД"]
    missing = []
    EMPTY_VALUES = {
        'информация отсутствует в документации',
        'не удалось определить',
        '—', '', 'не указано'
    }
    parts = re.split(r'\n---\s*(.*?)\s*---\n', response_text, flags=re.DOTALL)
    for i in range(1, len(parts) - 1, 2):
        title = parts[i].strip()
        if title == "Основная информация":
            content = parts[i + 1]
            lines = content.split('\n')
            field_values = {}
            for line in lines:
                if ':' in line:
                    key, val = line.split(':', 1)
                    field_values[key.strip()] = val.strip().lower()
            for field in required_fields:
                if field not in field_values:
                    missing.append(field)
                elif field_values[field] in EMPTY_VALUES:
                    missing.append(field)
            break
    return missing

# ======================================================================
# STOPFACTORS
# ======================================================================


# ========================= БЫСТРЫЕ СТОП-ФАКТОРЫ (ПРЕДОБРАБОТКА) =========================

def check_stopfactors_preprocess(excel_subject):
    """
    Быстрая проверка по названию предмета закупки — ДО скачивания файлов.
    Возвращает причину стоп-фактора (str) или None.
    """
    if not excel_subject or not str(excel_subject).strip():
        return None

    subject_str = str(excel_subject)
    subject_lower = subject_str.lower()
    subject_upper = subject_str.upper()

    # Подшипники
    if re.search(r'подшипник', subject_lower):
        return "подшипники в предмете закупки"

    # Запорная арматура, задвижки, затворы (стоп-фактор №8)
    if re.search(r'запорн\w*\s+арматур', subject_lower):
        return "запорная арматура в предмете закупки"
    if re.search(r'\bзадвижк', subject_lower):
        return "задвижки в предмете закупки"
    if re.search(r'\bзатвор\w*\b', subject_lower):
        return "затворы в предмете закупки"

    # Моторные масла
    if re.search(r'(моторн\w+\s+масл|масл\w+\s+моторн)', subject_lower):
        return "моторные масла в предмете закупки"

    # GPS / навигация
    if re.search(r'\b(gps|глонасс|навигатор\b)', subject_lower, re.IGNORECASE):
        return "GPS/навигация в предмете закупки"

    # Аренда / прокат (стоп-фактор #11)
    if re.search(r'\bаренд|\bпрокат\s+оборудования|\bпрокат\s+техник', subject_lower):
        return "аренда/прокат в предмете закупки (не поставка товара)"

    # Работы / услуги (стоп-фактор #11)
    if re.search(
        r'ремонтн\w*\s+работ|монтажн\w*\s+работ|строительн\w*\s+работ'
        r'|пусконаладочн|техническ\w*\s+обслуживани'
        r'|\bвыполнени\w*\s+работ|\bоказани\w*\s+услуг',
        subject_lower
    ):
        return "работы/услуги в предмете закупки (не поставка товара)"

    # ИСАС — только российское производство (стоп-фактор #3)
    if re.search(
        r'\bисас\b|интеллектуальн\w+\s+систем\w+\s+учёт\w+\s+электроэнерги'
        r'|интеллектуальн\w+\s+систем\w+\s+учета\s+электроэнерги',
        subject_lower
    ):
        return "ИСАС (интеллектуальная система учёта электроэнергии) — только российское производство (стоп-фактор #3)"

    # Российские бренды (транспорт, тракторы, двигатели)
    for abbr in RUSSIAN_BRAND_ABBREVIATIONS:
        pattern = r'\b' + re.escape(abbr.upper()) + r'\b'
        if re.search(pattern, subject_upper):
            return f"российская марка '{abbr}' в предмете закупки"

    # Российские IT-бренды — ПК и серверы российского производства (стоп-фактор #12)
    m_it = _RUSSIAN_IT_BRANDS_RE.search(subject_str)
    if m_it:
        return (f"российский IT-бренд '{m_it.group(0)}' в предмете закупки — "
                f"российский производитель выиграет тендер (стоп-фактор #12)")

    # ── Стоп-фактор #14: бытовые / потребительские товары ──────────────────
    CONSUMER_GOODS = [
        r'\bтарелк', r'\bкружк', r'\bчашк', r'\bблюдц', r'\bстакан\b',
        r'\bстоловые\s+приборы\b', r'\bвилк[аи]\b', r'\bложк[аи]\b',
        r'\bкастрюл', r'\bсковород', r'\bковш\b', r'\bдуршлаг',
        r'\bпосуда\b', r'\bстоловая\s+посуда',
        r'\bпостельное\s+бельё', r'\bпростын', r'\bнаволочк',
        r'\bполотенц', r'\bшторы\b', r'\bшторк', r'\bзанавеск',
        r'\bскатерт', r'\bсалфетк',
        r'\bвёдр[аоу]\b', r'\bведр[аоу]\b', r'\bшвабр', r'\bметёлк', r'\bметлк',
        r'\bсовок\b', r'\bщётк[аи]\s+для\s+уборк',
        r'\bмешк[аи]\s+для\s+мусор', r'\bпакет[аи]\s+для\s+мусор',
        r'\bмусорн\w+\s+пакет',
        r'\bпродукты\s+питания', r'\bпродовольстви',
        r'\bхлеб\b', r'\bбулк', r'\bвыпечк', r'\bкондитерск',
        r'\bмолок[оа]\b', r'\bкефир\b', r'\bтворог\b', r'\bсыр\b',
        r'\bмясо\b', r'\bрыба\b', r'\bкурин\w+\s+(?:мяс|филе|тушк)',
        r'\bовощ[ие]\b', r'\bфрукт[ыи]\b', r'\bчай\b', r'\bкофе\b',
        r'\bсахар\b', r'\bкрупы\b', r'\bмука\b',
        r'\bручк[аи]\s+шариков', r'\bкарандаш', r'\bблокнот',
        r'\bтетрадь', r'\bпапки?\s+(?:для\s+бумаг|канцеляр)',
        r'\bскрепк', r'\bстеплер\b', r'\bкнопки\s+канцеляр',
        r'\bбумага\s+А[34]\b',
        r'\bмоющее\s+средство', r'\bчистящее\s+средство',
        r'\bстиральн\w+\s+порошок', r'\bжидкость\s+для\s+мыть',
        r'\bсредство\s+для\s+(?:мытья|уборки|чистки)',
        r'\bодноразов\w+\s+(?:стакан|тарелк|посуд|перчатк)',
    ]
    for pat in CONSUMER_GOODS:
        if re.search(pat, subject_lower):
            matched = re.search(pat, subject_lower).group()
            return f"бытовые/потребительские товары в предмете закупки ({matched})"

    # ── Стоп-фактор #14 (доп.): лабораторная посуда, спецодежда, мебель, инвентарь ──
    CONSUMER_GOODS_EXTRA = [
        r'\bколб[аы]\b', r'\bпробирк',
        r'\bчашк[аи]\s+петри', r'\bпетри\b',
        r'\bстакан\w*\s+лабораторн', r'\bлабораторн\w+\s+стакан',
        r'\bлабораторн\w+\s+посуд',
        r'\bперчатки?\s+(?:хб|хлопчатобумажн|трикотажн)',
        r'\bхб[-\s]+перчатки?',
        r'\bкостюм\w*\s+рабоч', r'\bрабоч\w+\s+костюм\w*',
        r'\bботинки?\s+рабоч', r'\bрабоч\w+\s+ботинки?',
        r'\bбахил[аы]\b',
        r'\bхалат\w*\s+(?:рабоч|медицинск|белый)',
        r'\b(?:рабоч|медицинск)\w+\s+халат',
        r'\bмебель\s+офисн', r'\bофисн\w+\s+мебель',
        r'\bстол\w*\s+(?:письменн|компьютерн|офисн)',
        r'\b(?:письменн|компьютерн|офисн)\w*\s+стол',
        r'\bстул\w*\s+(?:офисн|компьютерн)', r'\b(?:офисн|компьютерн)\w*\s+стул',
        r'\bшкаф\w*\s+для\s+(?:документ|одежд|бумаг)',
        r'\bлопат[аыи]\b', r'\bграбл[иея]\b',
        r'\bломик[аи]?\b', r'\bлом\b(?!\s*металл)',
        r'\bтопор[аы]?\b',
    ]
    for pat in CONSUMER_GOODS_EXTRA:
        if re.search(pat, subject_lower):
            matched = re.search(pat, subject_lower).group()
            return f"бытовые/потребительские товары в предмете закупки ({matched})"

    # Молоток (отдельная проверка — не технический)
    _HAMMER_TECH = re.compile(
        r'\b(?:отбойн|пневматич|гидравлич)\w*\s+молот'
        r'|\bмолот\w*\s+(?:отбойн|пневматич|гидравлич)',
        re.IGNORECASE
    )
    if re.search(r'\bмолото[кч]\w*\b|\bмолотки\b', subject_lower) and not _HAMMER_TECH.search(subject_str):
        return "бытовые/потребительские товары в предмете закупки (молоток)"

    # ── Стоп-фактор #15а: строительные материалы ─────────────────────────
    BUILDING_MATERIALS = [
        r'\bкирпич',
        r'\b(?:газоблок|пеноблок)\w*',
        r'\b(?:газосиликатн|пенобетонн|керамзитобетонн)\w*\s+блок',
        r'\bблок[аи]?\s+(?:газосиликатн|пенобетонн|керамзитобетонн)',
        r'\bжби\b',
        r'\bжелезобетонн\w+\s+(?:издели|конструкц|свай|плит|кольц|лоток|лотк|бордюр)',
        r'\bсвай[аы]\s+(?:железобетонн|жб)\b',
        r'\bсваи\b', r'\bсвая\b',
        r'\bплит[аы]\s+перекрыти',
        r'\bкольц[оа]\s+колодц',
        r'\bфбс\b',
        r'\bасфальтобетон', r'\bасфальт\w*\s+смес',
        r'\bщебен[ьк]',
        r'\bпесок\s+(?:строительн|речн|кварцев)',
        r'\b(?:строительн|речн|кварцев)\w*\s+песок',
        r'\bгравий\b',
        r'\bбетон\s+(?:товарн|класс\s*[вb])', r'\bтоварн\w+\s+бетон',
        r'\bцемент\b',
        r'\bраствор\s+(?:строительн|кладочн|цементн)',
        r'\bкладочн\w+\s+раствор',
    ]
    for pat in BUILDING_MATERIALS:
        if re.search(pat, subject_lower):
            matched = re.search(pat, subject_lower).group()
            return (f"строительные материалы российского производства ({matched})"
                    f" — стоп-фактор #15")

    # ── Стоп-фактор #15б: металлопрокат без нержавейки/алюминия ─────────
    METAL_EXCLUDE = re.compile(
        r'(нержавею|aisi|нерж\.|алюминий|алюминиев)', re.IGNORECASE
    )
    if not METAL_EXCLUDE.search(subject_str):
        METAL_ROLL = [
            r'\bуголок\b',
            r'\bшвеллер\b',
            r'\bдвутавр\b',
            r'\bбалк[аи]\s+(?:стальн|двутавров)',
            r'\bарматура\s+(?:стальн|периодическ|класс[а]?\s*[аА][0-9])',
            r'\bарматура\s+класс[а]?\s+[аА][0-9]',
            r'\bарматура\s+[аА][0-9]',
            r'\bлист\s+стальн',
            r'\bлистов\w+\s+прокат',
            r'\bпрокат\s+листов',
            r'\bсталь\s+листов',
            r'\bпрофнастил\b',
            r'\bметаллопрокат\b',
        ]
        for pat in METAL_ROLL:
            if re.search(pat, subject_lower):
                matched = re.search(pat, subject_lower).group()
                return (f"металлопрокат российского производства ({matched})"
                        f" — стоп-фактор #15")

    # ── Стоп-фактор #15в: трубы без иностранного бренда ─────────────────
    PIPE_EXCLUDE = re.compile(
        r'(wavin|georg\s*fischer|rehau|uponor|valtec|giacomini|нержавею|aisi)',
        re.IGNORECASE
    )
    if not PIPE_EXCLUDE.search(subject_str):
        PIPE_PATTERNS = [
            r'\bтруб[аы]\s+стальн\w*\s+электросварн',
            r'\bэлектросварн\w+\s+труб',
            r'\bтруб[аы]\s+(?:вгп|водогазопровод)',
            r'\bводогазопровод\w+\s+труб',
            r'\bтруб[аы]\s+(?:профильн|квадратн\s+сеч|прямоугольн\s+сеч)',
            r'\bпрофильн\w+\s+труб',
            r'\bтруб[аы]\s+(?:пнд|пэ\b|полиэтилен)',
            r'\bполиэтиленов\w+\s+труб',
        ]
        for pat in PIPE_PATTERNS:
            if re.search(pat, subject_lower):
                matched = re.search(pat, subject_lower).group()
                return (f"трубопроводная продукция российского производства ({matched})"
                        f" — стоп-фактор #15")

    # ── Стоп-фактор #15г: противопожарное оборудование МЧС РФ ───────────
    FIRE_SAFETY = [
        r'\bрукав\w*\s+пожарн', r'\bпожарн\w+\s+рукав',
        r'\bствол\w*\s+пожарн', r'\bпожарн\w+\s+ствол',
        r'\bгидрант',
        r'\bогнетушител',
        r'\bкран\w*\s+пожарн', r'\bпожарн\w+\s+кран',
        r'\bщит\w*\s+пожарн', r'\bпожарн\w+\s+щит',
        r'\bкошм[аы]\b',
        r'\bящик\w*\s+для\s+(?:пожарн|песка)',
        r'\bшкаф\w*\s+пожарн', r'\bпожарн\w+\s+шкаф',
    ]
    for pat in FIRE_SAFETY:
        if re.search(pat, subject_lower):
            matched = re.search(pat, subject_lower).group()
            return (f"противопожарное оборудование МЧС РФ ({matched})"
                    f" — стоп-фактор #15")

    # ── Стоп-фактор #15д: котлы российских серий ─────────────────────────
    RUSSIAN_BOILERS = re.compile(
        r'\b(дквр|дкв[рp]|квтк|квгм|квм\b|квр\b|ниисту)\b',
        re.IGNORECASE
    )
    if RUSSIAN_BOILERS.search(subject_str):
        m = RUSSIAN_BOILERS.search(subject_str).group().strip()
        return (f"котёл российской серии ({m})"
                f" — производится преимущественно в РФ (стоп-фактор #15)")

    # ── Стоп-фактор #16: артикул по российской КД ────────────────────────
    RKDS_ARTICLE = re.compile(
        r'(?:чертеж[ую]?|по\s+чертеж[ую]?|соответствие\s+чертеж[ую]?|'
        r'согласно\s+чертеж[ую]?)\s+'
        r'[А-ЯЁ]{2,5}[\.\-][А-ЯЁ\d]{2,10}[\.\-]\d{3,}',
        re.IGNORECASE
    )
    if RKDS_ARTICLE.search(subject_str):
        return "артикул по российской конструкторской документации в предмете закупки (стоп-фактор #16)"

    # ── Стоп-фактор #15: российская кабельно-проводниковая продукция ─────
    RUSSIAN_CABLE_MARKS = re.compile(
        r'\b(АВВГ|ВВГ|КГ|ПВС|ВБбШв|АВБбШв|ВБШв|ААБ|ААШв|ААШП|ААПл|АСБ|'
        r'СБШв|ОСК|КВВГнг|КВВГэ|КВВГ|КВБбШв|ВКШв|ПВХ-кабель|КГтп|КГН|'
        r'КГВЭВ|КГВЭВЭ|КТВЭВ|КРПт|КПП|ЦСП|КСПВ|КВП|АКВВГнг|ОКГ)'
        r'[\s-]',
        re.IGNORECASE
    )
    if RUSSIAN_CABLE_MARKS.search(subject_str):
        m = RUSSIAN_CABLE_MARKS.search(subject_str).group().strip()
        return f"кабель российской марки ({m}) — производится преимущественно в РФ (стоп-фактор #15)"
    # ── Стоп-фактор #19: компьютерные комплектующие / ЦОД (узко) ──────────
    if re.search(
        r'\b(материнск\w*\s+плат\w*|процессор\w*|оперативн\w*\s+памят\w*|'
        r'патч[-\s]?панел\w*|патч[-\s]?корд\w*|серверн\w*\s+(?:стойк|шкаф|корпус)\w*|'
        r'центр\w*\s+обработк\w*\s+данных|ЦОД\b|дата[-\s]?центр\w*)',
        subject_lower
    ):
        return "компьютерные комплектующие/оборудование ЦОД (стоп-фактор #19)"
    return None


# ========================= POST-CHECKS (ПОСЛЕ LLM) =========================

def _log_decision(reg_number, response, extra_note=""):
    """Записывает лог отклонения."""
    logs_dir = os.path.join(OUTPUT_BASE, "logs")
    os.makedirs(logs_dir, exist_ok=True)
    with open(os.path.join(logs_dir, f"{reg_number}_log.txt"), 'w', encoding='utf-8') as f:
        f.write(f"ОТВЕТ:\n{response}")
        if extra_note:
            f.write(f"\n\n{extra_note}")


def run_post_validations(
    response, decision, reg_number,
    nac_regime_file_found=False,
    critical_errors=None,
    incomplete_list=None,
    subject_str="—", nmck_str="—", deadline_str=""
):
    """
    Запускает все Python post-check'и на ответе LLM.
    Возвращает (final_decision, early_return_tuple_or_None)
    где early_return_tuple = (reg_number, deadline_str, None, decision, False, [], subject_str, nmck_str, False)
    """

    if critical_errors is None:
        critical_errors = []
    if incomplete_list is None:
        incomplete_list = []

    _RETURN = lambda d: (reg_number, deadline_str, None, d, False, [], subject_str, nmck_str, False)

    # ── Пост-проверка 1: ложный отказ из-за «срок не указан» ──────────────
    reason = None
    if decision == "not_participate":
        reason = extract_rejection_reason(response)
        if re.search(r'(отсутствует\s*срок|срок\s*не\s*указан|не\s*указан\s*срок)', reason, re.IGNORECASE):
            match = re.search(r'Срок поставки:\s*([^\n]+)', response, re.IGNORECASE)
            if match and match.group(1).strip().lower() not in (
                'информация отсутствует в документации', 'не удалось определить', ''
            ):
                print(f"  ⚠️ Ложный отказ: причина '{reason}', но срок указан. Меняем на 'требуется уточнение'.")
                decision = 'clarify'
                reason = None

    if decision == "not_participate":
        if reason is None:
            reason = extract_rejection_reason(response)
        print(f"  Решение: НЕ УЧАСТВУЕМ (причина: {reason})")
        _log_decision(reg_number, response)
        return decision, _RETURN("not_participate")

    # ── Пост-проверка 2: Python-валидация срока ────────────────────────────
    term_days, term_reason = python_validate_term(response)
    if term_days is not None:
        print(f"  ⛔ Python-валидация: {term_reason} — меняем на 'не участвуем'")
        _log_decision(reg_number, response, f"[Python-валидация]: {term_reason}")
        return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 3: Казначейское сопровождение ───────────────────────
    if re.search(r'казначейское\s+сопровождение', response, re.IGNORECASE):
        kaz_reason = "казначейское сопровождение договора (стоп-фактор #4)"
        print(f"  ⛔ Python-проверка: {kaz_reason}")
        _log_decision(reg_number, response, f"[Python-проверка]: {kaz_reason}")
        return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 4: Соответствие чертежу российского производителя ───
    drawing_match = re.search(
        r'соответстви[еюя]\s+чертеж[уюа]?\s+[А-ЯЁA-Z]{2,}[.\-]\S+',
        response, re.IGNORECASE
    )
    if drawing_match:
        mfr_section = re.search(
            r'--- Производитель / бренд / страна ---\s*\n([^\n\-]+)',
            response, re.IGNORECASE
        )
        is_russian_mfr = False
        if mfr_section:
            mfr_text = mfr_section.group(1).lower()
            is_russian_mfr = bool(re.search(
                r'россия|рос\.|ооо\b|ао\b|зао\b|гуп\b|муп\b|беларус',
                mfr_text
            ))
        if is_russian_mfr:
            drawing_reason = f"соответствие чертежу российского производителя ({drawing_match.group(0)[:60]})"
            print(f"  ⛔ Python-проверка: {drawing_reason}")
            _log_decision(reg_number, response, f"[Python-проверка]: {drawing_reason}")
            return "not_participate", _RETURN("not_participate")

    # ── Критические ошибки извлечения ─────────────────────────────────────
    if critical_errors:
        print(f"  ❌ ОШИБКА: не удалось прочитать критически важные файлы: {critical_errors}")
        return "error", _RETURN("error")

    china_flag = extract_china_flag(response)

    # ── Пост-проверка 5: нац.режим в файле + China=Нет + УЧАСТВУЕМ ────────
    if nac_regime_file_found and not china_flag and decision == 'participate':
        nac_reason = "файл с 'нац.режим' в тендере, China=Нет — вероятное реальное ограничение происхождения (стоп-фактор #3)"
        print(f"  ⚠️ Python-проверка: {nac_reason} → меняем на 'требуется уточнение'")
        _log_decision(reg_number, response, f"[Python-проверка]: {nac_reason}")
        decision = 'clarify'

    # ── Пост-проверка 6: ПП-1875 + China=Нет + УЧАСТВУЕМ ─────────────────
    if decision == 'participate' and not china_flag:
        if re.search(r'пп.?1875|постановлени\w{0,10}\s*№?\s*1875', response, re.IGNORECASE):
            print(f"  ⚠️ Python-проверка: ПП-1875 + China=Нет → меняем на 'требуется уточнение'")
            decision = 'clarify'

    # ── Пост-проверка 7: пустая спецификация ──────────────────────────────
    if decision in ('participate', 'clarify'):
        spec_match = re.search(
            r'---\s*Что нужно поставить\s*---\s*\n(.*?)(?=\n---|\Z)',
            response, re.DOTALL | re.IGNORECASE
        )
        if spec_match:
            spec_content = spec_match.group(1).strip()
            if re.search(
                r'информация отсутствует в документации|нет структурированной спецификации'
                r'|спецификация отсутствует|не удалось извлечь спецификацию',
                spec_content, re.IGNORECASE
            ) and '|' not in spec_content:
                spec_reason = "спецификация товара отсутствует в документации — невозможно подать заявку"
                print(f"  ⛔ Python-проверка: {spec_reason}")
                _log_decision(reg_number, response, f"[Python-проверка]: {spec_reason}")
                return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 8: насос в спецификации ─────────────────────────────
    if decision in ('participate', 'clarify'):
        spec_match2 = re.search(
            r'---\s*Что нужно поставить\s*---\s*\n(.*?)(?=\n---|\Z)',
            response, re.DOTALL | re.IGNORECASE
        )
        if spec_match2:
            spec_text2 = spec_match2.group(1)
            if (re.search(r'\bнасос\w*\b', spec_text2, re.IGNORECASE)
                    and not re.search(r'запчаст|запасн\w*\s+част|комплектующ|ремкомплект',
                                      spec_text2, re.IGNORECASE)):
                pump_reason = "насос в спецификации поставки (стоп-фактор #6)"
                print(f"  ⛔ Python-проверка: {pump_reason}")
                _log_decision(reg_number, response, f"[Python-проверка]: {pump_reason}")
                return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 9: полнота ответа ───────────────────────────────────
    missing_fields = analyze_response_completeness(response)
    if missing_fields:
        print(f"  ⚠️ ВНИМАНИЕ: в отчёте отсутствуют обязательные поля: {', '.join(missing_fields)}")
        incomplete_list.append({
            'reg_number': reg_number,
            'deadline': deadline_str,
            'missing_fields': missing_fields
        })
        if 'Срок поставки' in missing_fields and decision == 'participate':
            reason_str = "срок поставки отсутствует в документации — невозможно оценить соблюдение минимального срока (стоп-фактор #2)"
            print(f"  ⛔ Python-проверка: срок поставки отсутствует → меняем на 'не участвуем'")
            incomplete_list.pop()
            _log_decision(reg_number, response, f"[Python-проверка]: {reason_str}")
            return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 10: кириллические модели (стоп #12/#16) ──────────────
    if decision in ('participate', 'clarify'):
        mined10 = mine_spec_table(response)
        if mined10['cyr_models']:
            reason10 = (f"российские обозначения моделей "
                        f"({', '.join(mined10['cyr_models'][:3])}) — стоп-фактор #12/#16")
            print(f"  ⛔ Python-проверка: {reason10}")
            _log_decision(reg_number, response, f"[Python-проверка]: {reason10}")
            return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 11: дженерик-тендер (стоп #18) ───────────────────────
    if decision in ('participate', 'clarify'):
        mined11 = mine_spec_table(response)
        bm = re.search(r'---\s*Производитель / бренд / страна\s*---\s*\n([^\n\-]+)',
                       response, re.IGNORECASE)
        brand_text = bm.group(1).strip() if bm else ""
        trusted = (is_brand_trusted(brand_text, response)
                   if brand_text and 'информация отсутствует' not in brand_text.lower()
                   else False)
        if not mined11['has_model'] and not mined11['brands'] and not trusted:
            reason11 = ("отсутствие конкретных модели/бренда — дженерик-тендер, "
                        "оборудование по характеристикам не подбираем (стоп-фактор #18)")
            print(f"  ⛔ Python-проверка: {reason11}")
            _log_decision(reg_number, response, f"[Python-проверка]: {reason11}")
            return "not_participate", _RETURN("not_participate")

    # ── Пост-проверка 12: ГОСТ на товар → уточнение (страховка #13) ────────
    if decision == 'participate':
        crit_match = re.search(r'---\s*Критичные требования ТЗ\s*---\s*\n(.*?)(?=\n---|\Z)',
                               response, re.DOTALL | re.IGNORECASE)
        if crit_match:
            gost_hits = re.findall(r'[^\n]*ГОСТ[^\n]*', crit_match.group(1), re.IGNORECASE)
            material_re = re.compile(
                r'(топлив|керосин|масл\w|материал|сырь|комплектующ|смазк|бензин|дизель)',
                re.IGNORECASE)
            real_gost = [g for g in gost_hits if not material_re.search(g)]
            if real_gost:
                print(f"  ⚠️ Python-проверка: ГОСТ на товар "
                      f"({real_gost[0].strip()[:60]}) → 'требуется уточнение'")
                decision = 'clarify'

    # ── Пост-проверка 13: потолок объёма (D5) ──────────────────────────────
    if decision in ('participate', 'clarify'):
        qty_match = re.search(r'Количество позиций:\s*(\d+)', response, re.IGNORECASE)
        if qty_match and int(qty_match.group(1)) > HARD_MAX_ITEMS:
            reason13 = (f"объём закупки {qty_match.group(1)} позиций — "
                        f"превышает потолок {HARD_MAX_ITEMS} (D5)")
            print(f"  ⛔ Python-проверка: {reason13}")
            _log_decision(reg_number, response, f"[Python-проверка]: {reason13}")
            return "not_participate", _RETURN("not_participate")

    return decision, None  # нет раннего возврата — продолжаем

