# Расширенные слова-паразиты для очистки предмета закупки
_SUBJECT_NOISE_RE = re.compile(
    r'\b(?:'
    r'поставка|закупка|приобретение|приобретения'
    r'|для нужд|нужд|для нужды'
    r'|право заключения договора на'
    r'|в количестве|количестве|количество'
    r'|объём|объем'
    r'|услуги по|работы по'
    r'|поставки'
    r')\b'
    # Количество + единица: «3 шт.», «100 единиц»
    r'|\b\d+\s*(?:шт|ед|штук|единиц|компл|комплект|пар|л|кг|м|мл)[а-я.]*\b'
    # Аббревиатуры организаций: ГБУЗ, ФГБОУ, МУП, ОАО и т.п.
    r'|\b(?:гбуз|гбоу|фгбу|фгуп|фгбоу|фгаоу|муп|мбу|мбоу|кгбуз|огбуз'
    r'|оао|зао|ооо|пао|ау|гау|мау)\b',
    re.IGNORECASE,
)


_translate_search_cache: dict = {}


def _translate_subject_for_search(subject: str) -> str:
    """
    Переводит предмет закупки на английский через LLM для поиска международных поставщиков.
    Русские запросы в Serper (Google) неэффективны — всегда нужен английский.
    Кэшируется в памяти по тексту запроса.
    При ошибке LLM — fallback к _clean_subject_for_search (словарный перевод).
    """
    key = subject.strip().lower()[:200]
    if key in _translate_search_cache:
        return _translate_search_cache[key]

    prompt = (
        "Extract the product or equipment type from this Russian procurement text and translate "
        "it into a short English technical phrase (2 to 4 words) suitable for finding "
        "international manufacturers on Google.\n"
        "Rules:\n"
        "- Return ONLY the product type in English, nothing else\n"
        "- Do NOT include organization names, city names, institution names\n"
        "- Do NOT include words like 'supply', 'procurement', 'delivery', 'purchase'\n"
        "- Focus on the actual physical product or equipment being bought\n"
        "Examples:\n"
        "  'Поставка промышленного пылесоса для нужд МУП' → 'industrial vacuum cleaner'\n"
        "  'Закупка компьютерного оборудования для оснащения МКУ г. Сочи' → 'desktop computer PC'\n"
        "  'ИЗВЕЩЕНИЕ о проведении запроса предложений на Поставку амплификатора' → 'PCR thermal cycler'\n"
        "  'Поставка компрессорной установки' → 'air compressor unit'\n"
        "  'Поставка сервера' → 'rack server'\n\n"
        f"Russian text: {subject.strip()[:300]}"
    )
    try:
        result = call_deepseek(prompt)
        if result:
            result = result.strip().strip('"\'«»').split('\n')[0].strip()
            if result and len(result) > 2:
                _translate_search_cache[key] = result
                print(f"  🌐 EN-поиск: «{subject.strip()[:70]}» → «{result}»")
                return result
    except Exception as e:
        print(f"  ⚠️ Ошибка LLM-перевода для поиска: {e}")

    # Fallback к словарному переводу
    fallback = _clean_subject_for_search(subject)
    _translate_search_cache[key] = fallback
    if fallback and fallback != subject.strip():
        print(f"  🔤 fallback EN: «{subject.strip()[:70]}» → «{fallback}»")
    else:
        print(f"  ⚠️ EN-перевод не удался, поиск по русскому тексту: «{subject.strip()[:70]}»")
    return fallback


def _clean_subject_for_search(subject: str) -> str:
    """
    Очищает предмет закупки и переводит технические термины на английский
    для получения качественных результатов в Google.

    Шаги:
    1. Убираем слова-паразиты (закупка, для нужд, единицы измерения и т.п.).
    2. Заменяем известные технические термины (биграммы → однослово,
       однослово → английский).
    3. Возвращаем очищенный текст (смешанный RU+EN — OK: Google справляется).
    """
    text = _SUBJECT_NOISE_RE.sub('', subject)
    text = re.sub(r'\s{2,}', ' ', text).strip()

    # Пробуем перевести: сначала биграммы, потом отдельные слова
    words = text.split()
    out = []
    i = 0
    while i < len(words):
        # Биграмма
        if i + 1 < len(words):
            bigram = (words[i] + ' ' + words[i + 1]).lower()
            if bigram in _TECH_TERMS_RU_EN:
                en = _TECH_TERMS_RU_EN[bigram]
                if en:
                    out.append(en)
                i += 2
                continue
        # Однослово
        word_lower = words[i].lower()
        if word_lower in _TECH_TERMS_RU_EN:
            en = _TECH_TERMS_RU_EN[word_lower]
            if en:           # пустая строка = слово-балласт, выбрасываем
                out.append(en)
        else:
            out.append(words[i])   # латиница, цифры, бренд, незнакомый термин
        i += 1

    result = ' '.join(out).strip()
    return result if result else text


