# ========================= SERPER SEARCH =========================

def langsearch_search(query, max_results=10):
    """
    Выполняет поиск через LangSearch API (бесплатно, без кредитов).
    Возвращает список dict с ключами title, link, snippet.
    Free tier: 1 QPS, 60 QPM, 1000 QPD — достаточно для любого объёма тендеров.
    """
    if not LANGSEARCH_API_KEY:
        return []
    url = "https://api.langsearch.com/v1/web-search"
    headers = {
        "Authorization": f"Bearer {LANGSEARCH_API_KEY}",
        "Content-Type": "application/json",
    }
    payload = {
        "query": query,
        "freshness": "noLimit",
        "summary": False,
        "count": min(max_results, 10),
    }
    try:
        resp = requests.post(url, headers=headers, json=payload, timeout=15)
        if resp.status_code != 200:
            try:
                err_msg = resp.json().get('message', resp.text[:200])
            except Exception:
                err_msg = resp.text[:200]
            print(f"  ⛔ LangSearch HTTP {resp.status_code}: {err_msg}")
            return []
        data = resp.json()
        # LangSearch response: {"code":200, "data":{"webPages":{"value":[...]}}}
        web_pages = (data.get('data') or {}).get('webPages', {}).get('value', [])
        results = []
        for item in web_pages[:max_results]:
            results.append({
                'title':   item.get('name', ''),
                'link':    item.get('url', ''),
                'snippet': item.get('snippet', '') or item.get('summary', ''),
            })
        return results
    except Exception as e:
        print(f"  LangSearch ошибка: {e}")
        return []


def _web_search(query, max_results=10):
    """
    Единая точка веб-поиска: LangSearch → Serper (резерв).
    Соблюдает лимит LangSearch 1 QPS — делает паузу 1.1 с между вызовами.
    Возвращает список dict с ключами title, link, snippet.
    """
    # 1) LangSearch — основной бесплатный поиск
    if LANGSEARCH_ENABLED and LANGSEARCH_API_KEY:
        results = langsearch_search(query, max_results=max_results)
        time.sleep(1.1)  # соблюдаем лимит 1 QPS
        if results:
            return results
    return []


_SUPPLIER_SEARCH_QUERY_PATTERNS = (
    'best ', 'top ', 'wholesale ', 'supplier of', 'manufacturer of',
    'buy ', 'cheap ', 'price list', 'list of', 'suppliers of',
    'where to buy', 'how to find', 'leading ', 'global ',
)


def _generate_suppliers_llm(subject, brand=None, china_available=False):
    """
    Генерирует список поставщиков через LLM (PRIMARY метод).
    Возвращает отформатированную строку для Word-документа:
      Поставщик 1 — Название (Страна)
      Поставщик 2 — Название (Страна)
      ...
      E-mail для поставщика 1 — email@domain.com
      (строки E-mail — только для тех поставщиков, у кого email известен)
    """
    if not OPENROUTER_API_KEY and not DEEPSEEK_API_KEY:
        return ""
    priority = (
        "Приоритет: производители из Китая, Тайваня, Гонконга. "
        "Затем ОАЭ (параллельный импорт), Европа, США."
        if china_available else
        "Приоритет: европейские, тайваньские, японские или американские производители."
    )
    brand_hint = f"\nТорговая марка / бренд в ТЗ: {brand}." if brand else ""
    prompt = (
        f"Ты эксперт по международным B2B-закупкам.\n"
        f"Составь список из 5 реальных поставщиков для:\n\n"
        f"Предмет закупки: {subject}{brand_hint}\n\n"
        f"{priority}\n\n"
        f"СТРОГО ЗАПРЕЩЕНО выводить:\n"
        f"- компании из России, Беларуси, Казахстана и других стран СНГ\n"
        f"- агрегаторы, маркетплейсы, каталоги (Alibaba, Amazon, ThomasNet, IndiaMART и т.п.)\n"
        f"- поисковые запросы, ключевые слова или фразы вроде 'best supplier of...', 'top manufacturers'\n"
        f"- несуществующие или вымышленные компании\n"
        f"- выдуманные email-адреса\n\n"
        f"Для каждого поставщика — строго одна строка в формате:\n"
        f"Название компании | Страна | email@domain.com\n\n"
        f"Правила:\n"
        f"- Только реальные компании-производители или их официальные дистрибьюторы\n"
        f"- Email — только если ты точно знаешь реальный корпоративный адрес отдела продаж или экспорта этой компании\n"
        f"- Если email неизвестен — третье поле ОСТАВЬ ПУСТЫМ (просто две черты: Название | Страна |)\n"
        f"- Ровно 5 строк, без нумерации, без заголовков, без пояснений до или после\n"
        f"- Если бренд указан — включи оригинального производителя первым"
    )
    try:
        result = call_deepseek(prompt)
        if not result:
            return ""
        result = clean_response_preamble(result)

        suppliers = []  # list of (name, country, email_or_None)
        for raw_line in result.strip().split('\n'):
            line = raw_line.strip()
            if not line or line.startswith('#') or line.startswith('//'):
                continue
            if '|' not in line:
                continue
            parts = [p.strip() for p in line.split('|')]
            if len(parts) < 2:
                continue
            # Убираем нумерацию/маркеры из начала названия
            name = re.sub(r'^[\d\s\.\-\*\•]+', '', parts[0]).strip()
            country = parts[1].strip() if len(parts) > 1 else ""
            email_raw = parts[2].strip() if len(parts) > 2 else ""

            # Пропускаем пустые названия или слишком длинные (признак поискового запроса)
            if not name or len(name) > 80:
                continue
            # Пропускаем строки, где название — поисковый запрос
            name_lower = name.lower()
            if any(pat in name_lower for pat in _SUPPLIER_SEARCH_QUERY_PATTERNS):
                continue
            # Пропускаем строки-заголовки
            if name_lower in ('название компании', 'company name', 'поставщик', 'supplier'):
                continue

            # Парсим email — только реальный, не выдуманный
            email = None
            if email_raw and '@' in email_raw:
                m = re.search(r'[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}', email_raw)
                if m:
                    candidate = m.group(0).lower()
                    # Отбрасываем явно шаблонные/выдуманные адреса
                    if not any(stub in candidate for stub in (
                        '@example.', '@domain.', '@company.', '@yourcompany.',
                        '@email.', '@mail.com', '@supplier.',
                    )):
                        email = m.group(0)

            suppliers.append((name, country, email))

        suppliers = suppliers[:5]
        if not suppliers:
            return ""

        # Формируем строки для docx: сначала все поставщики, потом блок email
        name_lines = []
        email_lines = []
        for i, (name, country, email) in enumerate(suppliers, 1):
            country_str = f" ({country})" if country else ""
            name_lines.append(f"Поставщик {i} — {name}{country_str}")
            if email:
                email_lines.append(f"E-mail для поставщика {i} — {email}")

        return '\n'.join(name_lines + email_lines)

    except Exception as e:
        print(f"  LLM-поставщики ошибка: {e}")
        return ""


# ========================= EMAIL SCRAPING =========================

_EMAIL_RE = re.compile(r'[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}')


def _clean_raw_email(raw):
    """
    Очищает артефакты URL-кодирования и HTML-сущностей из «сырого» email.
    Возвращает чистый email или None если невалиден.
    """
    if not raw:
        return None
    # Убираем %20 и аналогичные URL-encoded префиксы
    cleaned = re.sub(r'^(%[0-9A-Fa-f]{2})+', '', raw)
    # Убираем u003e (HTML entity для >)
    if cleaned.lower().startswith('u003e'):
        cleaned = cleaned[5:]
    # Убираем ведущие > < символы
    cleaned = cleaned.lstrip('><')
    cleaned = cleaned.strip()
    # Проверяем что результат — валидный email
    if re.match(r'^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$', cleaned):
        return cleaned
    return None


_CF_EMAIL_RE = re.compile(r'data-cfemail="([0-9a-fA-F]+)"')

def _decode_cfemail(encoded):
    """Декодер Cloudflare email protection (XOR первым байтом)."""
    try:
        key = int(encoded[:2], 16)
        return ''.join(chr(int(encoded[i:i+2], 16) ^ key)
                       for i in range(2, len(encoded), 2))
    except Exception:
        return None

def _extract_emails_from_text(text):
    """Извлекает email: Cloudflare data-cfemail + html-сущности + сырой regex."""
    result = set()
    for m in _CF_EMAIL_RE.finditer(text):
        dec = _decode_cfemail(m.group(1))
        if dec and _EMAIL_RE.fullmatch(dec):
            result.add(dec)
    unescaped = _html.unescape(text)   # S3: ловит info&#64;domain&#46;com
    for raw in _EMAIL_RE.findall(unescaped):
        cleaned = _clean_raw_email(raw)
        if cleaned:
            result.add(cleaned)
    return result


def _is_b2p_domain(url):
    """Проверяет, является ли URL B2B-агрегатором из B2B_PLATFORMS."""
    try:
        host = urlparse(url).netloc.lower()
        if host.startswith("www."):
            host = host[4:]
        return any(host == p or host.endswith("." + p) for p in B2B_PLATFORMS)
    except Exception:
        return False


# Алиас для внутреннего использования
_is_b2b_domain = _is_b2p_domain


def _is_safe_host(hostname: str) -> bool:
    """
    SSRF-guard: возвращает True только если hostname резолвится в публичный IP.
    Отклоняет loopback, private, link-local, unspecified и reserved адреса.
    При любой ошибке DNS — считаем небезопасным (fail-closed).
    """
    try:
        infos = socket.getaddrinfo(hostname, None, socket.AF_UNSPEC, socket.SOCK_STREAM)
        for info in infos:
            addr_str = info[4][0]
            ip = ipaddress.ip_address(addr_str)
            if (ip.is_private or ip.is_loopback or ip.is_link_local
                    or ip.is_unspecified or ip.is_reserved
                    or ip.is_multicast):
                return False
        return bool(infos)
    except Exception:
        return False


def _safe_get_public(url, _max_hops=3):
    """GET с ручными редиректами (≤3); каждый хоп проверяется _is_safe_host."""
    headers = {"User-Agent": USER_AGENT, "Accept-Language": "en-US,en;q=0.9"}
    for _ in range(_max_hops):
        resp = requests.get(url, timeout=(3, 6), headers=headers, allow_redirects=False)
        if resp.status_code in (301, 302, 303, 307, 308):
            location = resp.headers.get("Location", "")
            if not location:
                return resp
            location = urljoin(url, location)
            next_host = urlparse(location).hostname or ""
            if next_host and not _is_safe_host(next_host):
                raise ValueError(f"Redirect to unsafe host blocked: {next_host}")
            url = location
        else:
            return resp
    raise requests.exceptions.ConnectionError("Too many redirects")

def _scrape_contact_emails(domains, max_requests=SCRAPE_MAX_REQUESTS, max_inflight=SCRAPE_MAX_INFLIGHT):
    """
    Для каждого домена пробует загрузить контактные страницы.
    Из HTML извлекает email regex. Возвращает set найденных реальных адресов.
    Доменные имена проверяются через _is_safe_host (SSRF-guard).
    Редиректы ограничены 3 переходами (allow_redirects=True, max_redirects=3).
    """
    contact_paths = ["/", "/contact", "/contacts", "/contact-us", "/about-us",
                     "/about", "/en/contact", "/en/contacts", "/en/about",
                     "/en", "/contactus", "/kontakty", "/team", "/ru/kontakty"]
    headers = {"User-Agent": USER_AGENT, "Accept-Language": "en-US,en;q=0.9"}
    bad_patterns = [
        "noreply", "no-reply", "donotreply", "example.com",
        "yourdomain", "domain.com", "test@", "user@",
        "admin@", "webmaster@", "postmaster@", "@alibaba-inc",
    ]

    counter = {"tried": 0}
    counter_lock = threading.Lock()
    inflight_sem = threading.Semaphore(max_inflight)

    def _claim_slot():
        with counter_lock:
            if counter["tried"] >= max_requests:
                return False
            counter["tried"] += 1
            return True

    def _refund_slot():
        with counter_lock:
            counter["tried"] -= 1

    def _safe_get(url, _max_hops=3):
        """
        GET с ручным следованием редиректов (не более _max_hops переходов).
        Каждый Location-хост проверяется через _is_safe_host ДО перехода —
        защита от SSRF на промежуточных хопах.
        Использует requests.get (не Session) для совместимости с тест-патчами.
        """
        for _ in range(_max_hops):
            resp = requests.get(url, timeout=(3, 6), headers=headers,
                                allow_redirects=False)
            if resp.status_code in (301, 302, 303, 307, 308):
                location = resp.headers.get("Location", "")
                if not location:
                    return resp
                # Превращаем relative URL в absolute
                location = urljoin(url, location)
                next_host = urlparse(location).hostname or ""
                if next_host and not _is_safe_host(next_host):
                    raise ValueError(f"Redirect to unsafe host blocked: {next_host}")
                url = location
            else:
                return resp
        raise requests.exceptions.ConnectionError("Too many redirects")

    def _fetch_domain(domain):
        if _is_b2p_domain("http://" + domain):
            return set()
        # SSRF-guard: проверяем до первого запроса
        if not _is_safe_host(domain):
            return set()
        local_emails = set()
        for path in contact_paths:
            if not _claim_slot():
                break
            url_https = f"https://{domain}{path}"
            try:
                with inflight_sem:
                    resp = _safe_get(url_https)
                if resp.status_code == 200:
                    emails = _extract_emails_from_text(resp.text)
                    real = {e for e in emails if not any(bad in e.lower() for bad in bad_patterns)}
                    local_emails.update(real)
                    if real:
                        break
                continue
            except (requests.exceptions.SSLError, requests.exceptions.ConnectionError):
                _refund_slot()
            except Exception:
                continue

            if not _claim_slot():
                break
            url_http = f"http://{domain}{path}"
            try:
                with inflight_sem:
                    resp = _safe_get(url_http)
                if resp.status_code == 200:
                    emails = _extract_emails_from_text(resp.text)
                    real = {e for e in emails if not any(bad in e.lower() for bad in bad_patterns)}
                    local_emails.update(real)
                    if real:
                        break
            except Exception:
                pass
        return local_emails

    t0 = time.time()
    found = set()
    filtered_domains = [d for d in domains if not _is_b2p_domain("http://" + d)]
    with ThreadPoolExecutor(max_workers=4) as executor:
        futures = [executor.submit(_fetch_domain, d) for d in filtered_domains]
        for future in as_completed(futures):
            try:
                found.update(future.result())
            except Exception:
                pass
    elapsed = round(time.time() - t0, 1)
    print(f"📧 Скрапинг: {elapsed} сек, найдено {len(found)} email")
    return found


def validate_emails_mx(emails):
    """MX-валидация; возвращает только адреса с реальным MX-доменом."""
    try:
        import dns.resolver as _dns_resolver
    except ImportError:
        return list(emails)
    valid = []
    cache = {}
    for email in emails:
        try:
            domain = email.split("@", 1)[1].lower()
            if domain not in cache:
                try:
                    _dns_resolver.resolve(domain, "MX", lifetime=3)
                    cache[domain] = True
                except Exception:
                    cache[domain] = False
            if cache[domain]:
                valid.append(email)
        except Exception:
            pass
    return valid


# ========================= ПАРСИНГ РЕЗУЛЬТАТОВ =========================

def _get_host(url):
    """Возвращает хост без www."""
    try:
        host = urlparse(url).netloc.lower()
        return host[4:] if host.startswith("www.") else host
    except Exception:
        return ""


def _is_junk_result(title, url):
    """True если результат поиска нерелевантен (агрегатор, Вики, Caterpillar и т.п.)."""
    host = _get_host(url)
    # Проверяем по домену
    for junk in _JUNK_DOMAINS:
        if host == junk or host.endswith('.' + junk):
            return True
    # Проверяем по title
    title_lower = title.lower()
    for kw in _JUNK_TITLE_KEYWORDS:
        if kw in title_lower:
            return True
    return False


def _extract_company_name(title, url):
    """Извлекает название компании из title поисковой выдачи."""
    # Убираем всё после | · (часть с описанием сайта)
    name = re.split(r'\s*[|·]\s*', title)[0].strip()
    # Убираем суффиксы через тире: "- Official Website", "- Contact Us"
    name = re.sub(
        r'\s*[-–—]\s*(Official\s*(Website|Site|Page|Store)?|Homepage|'
        r'Contact\s*(Us|Info)?|About(\s*Us)?|Home|Support|Products?|'
        r'Manufacturer|Distributor|Supplier|Global|Group|Company|Corp\.?).*$',
        '', name, flags=re.IGNORECASE
    ).strip()
    # Убираем те же суффиксы без тире (через пробел в конце)
    name = re.sub(
        r'\s+(Official\s*(?:Website|Site|Page|Store|Homepage)?|'
        r'Homepage|Contact\s*(?:Us|Info)?|About\s*(?:Us)?'
        r'|\.com|\.net|\.org|Ltd\.?|Inc\.?|Corp\.?)$',
        '', name, flags=re.IGNORECASE
    ).strip()
    # Убираем лидирующий "Contact" / "About" / "Support"
    name = re.sub(r'^(Contact|About|Support|Home)\s*[-–—:]\s*', '', name, flags=re.IGNORECASE).strip()
    # Обрезаем слишком длинное
    if len(name) > 70:
        name = name[:70].rsplit(' ', 1)[0].rstrip(',-') + '…'
    return name or title[:50]


def _get_country_from_url(url):
    """Определяет страну по TLD домена. Возвращает строку или None."""
    host = _get_host(url)
    # Сначала двухуровневые TLD (.co.uk)
    for tld, country in _TLD_TO_COUNTRY.items():
        if host.endswith(tld):
            return country
    return None


def _get_short_description(snippet):
    """Возвращает первое осмысленное предложение из snippet."""
    if not snippet:
        return ""
    # Берём первое предложение
    first = re.split(r'(?<=[.!?])\s+', snippet.strip())[0]
    # Убираем дату-мусор в начале
    first = re.sub(r'^\d{1,2}\s+\w+\s+\d{4}\s*[—\-·]\s*', '', first).strip()
    if len(first) > 150:
        first = first[:150].rsplit(' ', 1)[0] + '…'
    return first


def _parse_results_to_suppliers(all_results):
    """
    Преобразует список (section, results[]) в список записей поставщиков.
    Каждая запись: {'name': str, 'url': str, 'host': str, 'country': str|None, 'desc': str}
    Дубли (по хосту) удаляются.
    """
    seen_hosts = set()
    suppliers = []

    for _section, results in all_results:
        for r in results:
            url = r.get('url', r.get('link', ''))
            title = r.get('title', '')
            snippet = r.get('snippet', '')

            if not url or not title:
                continue
            if _is_junk_result(title, url):
                continue
            if _is_b2p_domain(url):
                continue

            host = _get_host(url)
            if not host or host in seen_hosts:
                continue
            seen_hosts.add(host)

            name = _extract_company_name(title, url)
            country = _get_country_from_url(url)
            desc = _get_short_description(snippet)

            suppliers.append({
                'name': name,
                'url': url,
                'host': host,
                'country': country,
                'desc': desc,
            })

    return suppliers


# ========================= ФОРМАТИРОВАНИЕ ДЛЯ DOCX =========================

_BAD_EMAIL_PATTERNS = [
    "noreply", "no-reply", "donotreply", "example.com",
    "yourdomain", "domain.com", "test@", "user@",
    "admin@", "webmaster@", "postmaster@", "@alibaba-inc",
    "privacy@", "legal@", "press@", "media@",
    "youremail@", "your@",
    "@merckgroup.com",  # Merck корпоративный — только через дистрибьюторов
    "@emdgroup.com",    # то же, другой домен Merck Group
    "@merck.com",       # Merck USA корпоративный
    "@sigmaaldrich.com", # Sigma-Aldrich (Merck) корпоративный
]


_CIS_TLD_RE = re.compile(
    r'\.(ru|by|kz|ua|uz|am|kg|tj|tm|az|ge|md)$', re.IGNORECASE
)


def _is_cis_email(email: str) -> bool:
    """Возвращает True если email принадлежит домену РФ/СНГ."""
    try:
        domain = email.split('@', 1)[1]
        return bool(_CIS_TLD_RE.search(domain))
    except (IndexError, AttributeError):
        return False


def _filter_emails(emails):
    """Убирает явно нерелевантные адреса (шаблонные, корпоративные, РФ/СНГ)."""
    return {
        e for e in emails
        if not any(bad in e.lower() for bad in _BAD_EMAIL_PATTERNS)
        and not _is_cis_email(e)
    }


_RFQ_PREFERRED_EMAIL_PARTS = (
    "sales", "sale", "export", "commercial", "quotation", "quote",
    "rfq", "procurement", "purchasing", "orders", "order", "business",
    "inquiry", "enquiry", "contact", "info", "office",
)

_RFQ_REJECTED_EMAIL_PARTS = (
    "cybersecurity", "security", "training", "academy", "career", "jobs",
    "hr", "humanresources", "legal", "privacy", "abuse", "noreply",
    "no-reply", "donotreply", "webmaster", "postmaster", "support",
    "service", "technical", "tech",
)


def _select_rfq_emails(emails, max_per_domain=2):
    """
    Выбирает контакты, подходящие для коммерческого RFQ.

    Возвращает (selected, rejected). В автоматическую рассылку попадают
    только sales/export/quote/info-подобные адреса. Технические, учебные,
    security- и служебные ящики исключаются. На один домен оставляем
    не более max_per_domain лучших адресов.
    """
    candidates = []
    rejected = []
    seen = set()

    for raw in emails or []:
        email = str(raw).strip().lower()
        if not email or email in seen or "@" not in email:
            continue
        seen.add(email)

        if (
            any(bad in email for bad in _BAD_EMAIL_PATTERNS)
            or _is_cis_email(email)
        ):
            rejected.append((email, "служебный/неподходящий домен"))
            continue

        local, _, domain = email.partition("@")
        if not domain:
            rejected.append((email, "некорректный email"))
            continue

        if any(part in local for part in _RFQ_REJECTED_EMAIL_PARTS):
            rejected.append((email, "технический или служебный контакт"))
            continue

        preferred_score = 0
        for part in _RFQ_PREFERRED_EMAIL_PARTS:
            if part in local:
                preferred_score = max(preferred_score, 100 if part in {
                    "sales", "sale", "export", "commercial", "quotation",
                    "quote", "rfq", "procurement", "purchasing", "orders",
                    "order",
                } else 60)

        if preferred_score == 0:
            rejected.append((email, "не найден коммерческий признак"))
            continue

        candidates.append((preferred_score, email, domain))

    selected = []
    by_domain = defaultdict(list)
    for score, email, domain in candidates:
        by_domain[domain].append((score, email))

    for domain, domain_candidates in by_domain.items():
        domain_candidates.sort(key=lambda item: (-item[0], item[1]))
        selected.extend(email for _, email in domain_candidates[:max_per_domain])
        rejected.extend(
            (email, "дополнительный адрес того же домена")
            for _, email in domain_candidates[max_per_domain:]
        )

    return selected, rejected


def _collect_domains_from_results(all_results):
    """
    Извлекает уникальные домены и email-адреса из сниппетов поисковой выдачи.
    Возвращает (found_domains: list[str], snippet_emails: set[str]).
    """
    found_domains = []
    snippet_emails = set()
    for _section, results in all_results:
        for r in results:
            url     = r.get('url', r.get('link', ''))
            snippet = r.get('snippet', '')
            title   = r.get('title', '')
            snippet_emails.update(_extract_emails_from_text(snippet))
            snippet_emails.update(_extract_emails_from_text(title))
            if url and not _is_b2p_domain(url) and not _is_junk_result(title, url):
                try:
                    host = _get_host(url)
                    if host and host not in found_domains and not _CIS_TLD_RE.search(host):
                        found_domains.append(host)
                except Exception:
                    pass
    return found_domains, snippet_emails


def _inject_emails_into_suppliers_text(suppliers_text, emails):
    """
    Добавляет найденные email к уже сформированному тексту поставщиков.
    Email сопоставляется с поставщиком по совпадению domain-root и токенов названия.
    Несопоставленные email НЕ добавляются — только верифицированные совпадения.
    """
    if not emails or not suppliers_text:
        return suppliers_text

    lines = suppliers_text.split('\n')
    supplier_re = re.compile(
        r'^Поставщик\s+(\d+)\s+[—–\-]\s+(.+?)(?:\s*\([^)]*\))?\s*$'
    )
    existing_email_re = re.compile(r'^E-mail для поставщика\s+(\d+)', re.IGNORECASE)

    suppliers_map = {}   # num → company_name_lower
    has_email = set()    # nums that already have an email line

    for line in lines:
        m = supplier_re.match(line.strip())
        if m:
            suppliers_map[int(m.group(1))] = m.group(2).strip().lower()
        m2 = existing_email_re.match(line.strip())
        if m2:
            has_email.add(int(m2.group(1)))

    if not suppliers_map:
        return suppliers_text

    email_assignments = {}  # supplier_num → email

    for email in sorted(emails):
        try:
            # «mobatime» из «info@mobatime.com»
            domain_root = email.split('@')[1].rsplit('.', 1)[0].lower()
        except Exception:
            continue

        for num, name_lower in sorted(suppliers_map.items()):
            if num in has_email or num in email_assignments:
                continue
            # Токены имени компании длиной ≥ 4
            name_tokens = re.findall(r'[a-z]{4,}', name_lower)
            if (domain_root in name_lower
                    or any(tok in domain_root for tok in name_tokens)):
                email_assignments[num] = email
                break

    if not email_assignments:
        return suppliers_text

    new_lines = [f"E-mail для поставщика {n} — {e}"
                 for n, e in sorted(email_assignments.items())]

    # Вставляем после последней существующей строки E-mail
    last_email_idx = -1
    for i, line in enumerate(lines):
        if re.match(r'^E-mail', line.strip(), re.IGNORECASE):
            last_email_idx = i
    insert_at = last_email_idx + 1 if last_email_idx >= 0 else len(lines)
    for j, el in enumerate(new_lines):
        lines.insert(insert_at + j, el)

    return '\n'.join(lines)


def _inject_scraped_emails(suppliers_text, found_domains, snippet_emails):
    """
    1. Фильтрует email из сниппетов поиска.
    2. Запускает _scrape_contact_emails по доменам из поиска.
    3. Инжектирует всё найденное в текст поставщиков.
    Возвращает обновлённый текст поставщиков.
    """
    if not suppliers_text:
        return suppliers_text

    all_emails = _filter_emails(snippet_emails)

    if found_domains:
        scraped = _scrape_contact_emails(found_domains[:SCRAPE_MAX_DOMAINS])
        if scraped:
            all_emails.update(_filter_emails(scraped))   # фильтруем scraped отдельно

    if not all_emails:
        return suppliers_text

    before_count = suppliers_text.count('E-mail для поставщика')
    result = _inject_emails_into_suppliers_text(suppliers_text, all_emails)
    after_count  = result.count('E-mail для поставщика')
    added = after_count - before_count
    print(f"  📧 Email после скрапинга: {added} добавлено"
          f", всего строк E-mail: {after_count}")
    return result


def _enrich_suppliers_emails(suppliers_text, max_queries=4):
    """
    Для поставщиков без email — ищет контакты через веб-поиск.
    Используется когда доменов из поиска нет (LLM-из-знаний ветка).
    """
    if not suppliers_text:
        return suppliers_text

    supplier_re = re.compile(
        r'^Поставщик\s+(\d+)\s+[—–\-]\s+(.+?)(?:\s*\([^)]*\))?\s*$'
    )
    email_re = re.compile(r'^E-mail для поставщика\s+(\d+)', re.IGNORECASE)

    lines = suppliers_text.split('\n')
    suppliers_map = {}
    has_email = set()

    for line in lines:
        m = supplier_re.match(line.strip())
        if m:
            suppliers_map[int(m.group(1))] = m.group(2).strip()
        m2 = email_re.match(line.strip())
        if m2:
            has_email.add(int(m2.group(1)))

    without_email = [(num, name) for num, name in sorted(suppliers_map.items())
                     if num not in has_email]
    if not without_email:
        return suppliers_text

    found_emails = {}  # num → email
    for num, name in without_email[:max_queries]:
        query = f'"{name}" email contact sales export'
        results = _web_search(query, max_results=5)
        if not results:
            continue
        all_text = ' '.join(
            (r.get('snippet', '') + ' ' + r.get('title', ''))
            for r in results
        )
        emails = _filter_emails(_extract_emails_from_text(all_text))
        if not emails:   # S5: скрапим топ-страницы, сниппетов мало
            for r in results[:2]:
                url = r.get('link', '') or r.get('url', '')
                host = _get_host(url)
                if not host or _is_b2p_domain(url) or _is_junk_result(r.get('title', ''), url):
                    continue
                try:
                    if not _is_safe_host(host):
                        continue
                    resp = _safe_get_public(url)
                    if resp.status_code == 200:
                        emails = _filter_emails(_extract_emails_from_text(resp.text))
                        if emails:
                            break
                except Exception:
                    continue
        if emails:
            found_emails[num] = sorted(emails)[0]

    if not found_emails:
        return suppliers_text

    new_email_lines = [f"E-mail для поставщика {n} — {e}"
                       for n, e in sorted(found_emails.items())]

    last_email_idx = -1
    for i, line in enumerate(lines):
        if re.match(r'^E-mail', line.strip(), re.IGNORECASE):
            last_email_idx = i
    insert_at = last_email_idx + 1 if last_email_idx >= 0 else len(lines)
    for j, el in enumerate(new_email_lines):
        lines.insert(insert_at + j, el)

    print(f"  📧 Email (веб-поиск по компаниям): {len(found_emails)}"
          f" из {len(without_email)} поставщиков без email")
    return '\n'.join(lines)


def _format_suppliers_for_docx(suppliers, valid_emails):
    """
    Формирует чистый текст для вставки в Word-документ.
    Формат: Название — Страна — домен (без описаний-сниппетов).
    """
    lines = []

    if suppliers:
        lines.append("Поставщики (автоматический поиск, требует проверки):")
        lines.append("")
        for i, s in enumerate(suppliers[:12], 1):
            parts = [s['name']]
            if s['country']:
                parts.append(s['country'])
            if s.get('host'):
                parts.append(s['host'])
            lines.append(f"{i}. {' — '.join(parts)}")
    else:
        lines.append("Поставщики: автоматический поиск не дал релевантных результатов.")
        lines.append("(Требуется ручной поиск поставщиков.)")

    if valid_emails:
        lines.append("")
        lines.append("Контакты для запроса:")
        for email in sorted(valid_emails)[:15]:
            lines.append(f"• {email}")

    return "\n".join(lines)


# ========================= ФОРМАТИРОВАНИЕ ПОСТАВЩИКОВ =========================

def _extract_suppliers_from_search_results(subject, brand, china_available, all_results):
    """
    Передаёт сырые результаты LangSearch/Serper в LLM для извлечения
    реальных поставщиков. LLM выбирает из найденных страниц реальные
    компании-производители, отбрасывает агрегаторы и форматирует вывод.

    Возвращает отформатированную строку для Word-документа или "".
    """
    if not OPENROUTER_API_KEY and not DEEPSEEK_API_KEY:
        return ""

    # Собираем компактный блок результатов для промпта
    # Лимит: ~3000 символов чтобы не раздувать контекст
    lines = []
    char_count = 0
    result_idx = 0
    for _section, results in all_results:
        for r in results:
            title   = (r.get('title', '') or '').strip()
            link    = (r.get('link', '') or r.get('url', '') or '').strip()
            snippet = (r.get('snippet', '') or '').strip()
            if not title and not link:
                continue
            # Вырезаем домен из URL для краткости
            try:
                domain = link.split('/')[2] if '//' in link else link
            except Exception:
                domain = link
            entry = f"[{result_idx + 1}] {title}\n    {domain}\n    {snippet[:200]}"
            if char_count + len(entry) > 3000:
                break
            lines.append(entry)
            char_count += len(entry)
            result_idx += 1
        if char_count > 3000:
            break

    if not lines:
        return ""

    search_block = '\n'.join(lines)
    priority = (
        "Приоритет: производители из Китая, Тайваня, Гонконга. Затем ОАЭ, Европа, США."
        if china_available else
        "Приоритет: европейские, тайваньские, японские или американские производители."
    )
    brand_hint = f"\nБренд в ТЗ: {brand}." if brand else ""
    prompt = (
        f"Ты эксперт по международным B2B-закупкам.\n"
        f"Предмет закупки: {subject}{brand_hint}\n"
        f"{priority}\n\n"
        f"Ниже — результаты веб-поиска. Проанализируй их и выбери до 5 реальных "
        f"компаний-производителей или официальных дистрибьюторов данного товара.\n\n"
        f"РЕЗУЛЬТАТЫ ПОИСКА:\n{search_block}\n\n"
        f"СТРОГО ЗАПРЕЩЕНО:\n"
        f"- включать агрегаторы, маркетплейсы, каталоги, рейтинговые статьи\n"
        f"- включать компании из России, Беларуси, Казахстана и других СНГ\n"
        f"- выдумывать компании которых нет в результатах поиска\n"
        f"- выдумывать email — только те, что реально встречаются в сниппетах выше\n\n"
        f"Формат — строго одна строка на компанию:\n"
        f"Название компании | Страна | email@domain.com\n\n"
        f"Если email нет в результатах поиска — третье поле ОСТАВЬ ПУСТЫМ.\n"
        f"Только реальные строки, без нумерации, без заголовков, без пояснений."
    )
    try:
        result = call_deepseek(prompt)
        if not result:
            return ""
        result = clean_response_preamble(result)
        # Парсинг идентичен _generate_suppliers_llm
        suppliers = []
        for raw_line in result.strip().split('\n'):
            line = raw_line.strip()
            if not line or line.startswith('#') or '|' not in line:
                continue
            parts = [p.strip() for p in line.split('|')]
            if len(parts) < 2:
                continue
            name = re.sub(r'^[\d\s\.\-\*\•]+', '', parts[0]).strip()
            country   = parts[1].strip() if len(parts) > 1 else ""
            email_raw = parts[2].strip() if len(parts) > 2 else ""
            if not name or len(name) > 80:
                continue
            name_lower = name.lower()
            if any(pat in name_lower for pat in _SUPPLIER_SEARCH_QUERY_PATTERNS):
                continue
            if name_lower in ('название компании', 'company name', 'поставщик', 'supplier'):
                continue
            email = None
            if email_raw and '@' in email_raw:
                m = re.search(r'[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}', email_raw)
                if m:
                    candidate = m.group(0).lower()
                    if not any(stub in candidate for stub in (
                        '@example.', '@domain.', '@company.', '@yourcompany.',
                        '@email.', '@mail.com', '@supplier.',
                    )):
                        email = m.group(0)
            suppliers.append((name, country, email))

        suppliers = suppliers[:5]
        if not suppliers:
            return ""

        name_lines  = []
        email_lines = []
        for i, (name, country, email) in enumerate(suppliers, 1):
            country_str = f" ({country})" if country else ""
            name_lines.append(f"Поставщик {i} — {name}{country_str}")
            if email:
                email_lines.append(f"E-mail для поставщика {i} — {email}")
        return '\n'.join(name_lines + email_lines)
    except Exception as e:
        print(f"  LLM-очистка результатов поиска ошибка: {e}")
        return ""


def search_and_format_suppliers(subject, brand=None, mode="global", china_available=False):
    """
    Ищет поставщиков: LangSearch/Serper (первичный) → LLM чистит результаты.
    Если поиск не дал ничего — LLM генерирует из своих знаний.
    Если LLM недоступен — старый форматтер с email-скрапингом.
    """
    llm_available    = bool(OPENROUTER_API_KEY) or bool(DEEPSEEK_API_KEY)
    search_available = (LANGSEARCH_ENABLED and bool(LANGSEARCH_API_KEY))

    if not llm_available and not search_available:
        return ""

    subject_clean = _translate_subject_for_search(subject)

    # ── Шаг 1: Веб-поиск (LangSearch → Serper) ───────────────────────────
    all_results = []
    if search_available:
        if brand:
            queries = [
                (f"{brand} manufacturer official site", "Производитель"),
                (f"{brand} authorized distributor reseller supplier", "Дистрибьюторы"),
                (f"{subject_clean} China manufacturer factory", "Азия"),
                (f"{subject_clean} European manufacturer supplier industrial", "Европа"),
            ]
        else:
            queries = [
                (f"{subject_clean} manufacturer factory supplier", "Производители"),
                (f"{subject_clean} China manufacturer factory", "Азия"),
                (f"{subject_clean} European manufacturer supplier", "Европа"),
                (f"{subject_clean} UAE Middle East distributor supplier", "Ближний Восток"),
            ]
        used = 0
        for query, section in queries:
            if used >= SEARCH_MAX_QUERIES_PER_TENDER:
                break
            results = _web_search(query, max_results=10)
            used += 1
            if results:
                all_results.append((section, results))

    # ── Сбор доменов и email из сниппетов (общий блок для всех веток) ─────
    found_domains, snippet_emails = _collect_domains_from_results(all_results)

    # ── Шаг 2a: LangSearch нашёл страницы → LLM их чистит ───────────────
    if all_results and llm_available:
        print(f"  🔍 Найдено {sum(len(r) for _, r in all_results)} страниц → LLM извлекает поставщиков...")
        cleaned = _extract_suppliers_from_search_results(
            subject, brand, china_available, all_results
        )
        if cleaned:
            print(f"  ✅ LLM извлёк поставщиков из результатов поиска ({len(cleaned.splitlines())} строк)")
            # Скрапим email с сайтов из поисковой выдачи и инжектируем в текст
            cleaned = _inject_scraped_emails(cleaned, found_domains, snippet_emails)
            cleaned = _enrich_suppliers_emails(cleaned, max_queries=2)
            return cleaned
        print("  ⚠️ LLM не смог извлечь поставщиков из результатов → генерируем из знаний...")

    # ── Шаг 2b: LLM генерирует из своих знаний ───────────────────────────
    if llm_available:
        print("  🤖 Генерируем поставщиков через LLM (из знаний)...")
        llm_text = _generate_suppliers_llm(subject, brand=brand, china_available=china_available)
        if llm_text:
            print(f"  ✅ LLM сгенерировал поставщиков ({len(llm_text.splitlines())} строк)")
            # Если в поиске нашлись домены — скрапим с них; иначе — ищем email по имени
            if found_domains:
                llm_text = _inject_scraped_emails(llm_text, found_domains, snippet_emails)
            else:
                llm_text = _enrich_suppliers_emails(llm_text, max_queries=3)
            return llm_text

    # ── Шаг 2c: Только поиск, без LLM (старый форматтер) ─────────────────
    if not all_results:
        print("  ℹ️ Поставщики не найдены")
        return ""

    # Домены уже собраны выше; скрапим email и форматируем без LLM
    found_emails = _filter_emails(snippet_emails)
    if found_domains:
        scraped = _scrape_contact_emails(found_domains[:SCRAPE_MAX_DOMAINS])
        if scraped:
            found_emails.update(scraped)
            print(f"  📧 Найдено {len(scraped)} email с сайтов компаний")
    if found_emails:
        valid = validate_emails_mx(found_emails)
        if len(valid) < len(found_emails):
            print(f"  ✅ MX-валидация: {len(valid)} из {len(found_emails)} email прошли")
        found_emails = set(valid)
    suppliers = _parse_results_to_suppliers(all_results)
    print(f"  📋 Релевантных поставщиков (без LLM): {len(suppliers)}")
    return _format_suppliers_for_docx(suppliers, found_emails)

