def mine_spec_table(response):
    """
    B1: майнит таблицу «Что нужно поставить» из ответа LLM.
    Возвращает dict: brands (set), has_model (bool), cyr_models (list).
    """
    empty = {'brands': set(), 'has_model': False, 'cyr_models': []}
    spec_match = re.search(
        r'---\s*Что нужно поставить\s*---\s*\n(.*?)(?=\n---|\Z)',
        response, re.DOTALL | re.IGNORECASE)
    if not spec_match:
        return empty
    rows = extract_markdown_table(spec_match.group(1))
    if not rows or len(rows) < 2:
        return empty
    headers = [h.lower() for h in rows[0]]
    name_idx = next((i for i, h in enumerate(headers) if 'наимен' in h or 'item' in h), 1)
    part_idx = next((i for i, h in enumerate(headers)
                     if 'артикул' in h or 'каталож' in h or 'part' in h), -1)
    blank = {'', '—', '-', '–', '−'}
    brands, cyr, has_model = set(), [], False
    for row in rows[1:]:
        name = row[name_idx] if name_idx < len(row) else ''
        part = row[part_idx] if 0 <= part_idx < len(row) else ''
        if part.strip() not in blank:
            has_model = True
        cell = f"{name} {part}"
        for tok in re.findall(r'\b[A-Za-z][A-Za-z0-9\-]{2,}\b', cell):
            if tok.lower() in _NON_BRAND_TOKENS or tok.upper() in BRAND_BLACKLIST:
                continue
            brands.add(tok)
            has_model = True
        for m in re.finditer(r'\b([А-ЯЁ]{2,6})[-\s]?(\d[\w\-]*)\b', name):
            if m.group(1) not in _CYR_MODEL_EXCLUDE:
                cyr.append(m.group(0))
                has_model = True
    return {'brands': brands, 'has_model': has_model, 'cyr_models': cyr}

def is_brand_trusted(brand, response, pre_brand=""):
    """
    D2: бренд доверяется только если подтверждён независимым источником:
    pre_brand (тема/файлы) → майнинг таблицы → словарь KNOWN_BRANDS → веб-поиск.
    """
    if not brand or not brand.strip():
        return False
    b_l = brand.strip().lower()
    if b_l in _NON_BRAND_TOKENS or brand.strip().upper() in BRAND_BLACKLIST:
        return False
    if 'информация отсутствует' in b_l:
        return False
    if pre_brand and pre_brand.strip().lower() == b_l:
        return True
    mined = mine_spec_table(response)
    if any(m.lower() == b_l or b_l in m.lower() for m in mined['brands']):
        return True
    if b_l in KNOWN_BRANDS or any(k in b_l for k in KNOWN_BRANDS if len(k) >= 4):
        return True
    if LANGSEARCH_ENABLED and LANGSEARCH_API_KEY:
        if langsearch_search(f"{brand.strip()} manufacturer", max_results=3):
            return True
    return False

def add_key_value_table(doc, content):
    """
    Добавляет раздел «ключ: значение» в Word-документ.
    """
    for line in content.split('\n'):
        line = line.strip()
        if not line:
            continue
        if ':' in line:
            key, _, val = line.partition(':')
            p = doc.add_paragraph()
            run_key = p.add_run(key.strip() + ': ')
            run_key.bold = True
            p.add_run(val.strip())
        else:
            doc.add_paragraph(line)


def add_single_column_table(doc, content):
    """
    Добавляет простой список строк в Word-документ.
    """
    for line in content.split('\n'):
        line = line.strip()
        if line and not line.startswith('---'):
            doc.add_paragraph(line, style='List Bullet')


def add_structured_report(doc, response_text):
    """
    Разбирает response_text по разделам «--- Название ---» и добавляет их в doc.
    """
    # Разбиваем по разделительным меткам
    parts = re.split(r'\n(---\s*.+?\s*---)\n', response_text)
    if len(parts) <= 1:
        doc.add_paragraph(response_text)
        return

    # Первый элемент — текст до первого раздела (строка «Решение:»)
    preamble = parts[0].strip()
    if preamble:
        for line in preamble.split('\n'):
            line = line.strip()
            if not line:
                continue
            p = doc.add_paragraph()
            if line.startswith('Решение:'):
                run = p.add_run(line)
                run.bold = True
                run.font.size = Pt(12)
            else:
                p.add_run(line)

    # Пары (заголовок_раздела, контент)
    i = 1
    while i < len(parts) - 1:
        section_title = parts[i].strip().strip('-').strip()
        section_content = parts[i + 1].strip() if i + 1 < len(parts) else ""
        i += 2

        # Добавляем заголовок раздела
        heading = doc.add_heading(section_title, level=2)

        if not section_content:
            continue

        # Пытаемся разобрать как Markdown-таблицу
        table_rows = extract_markdown_table(section_content)
        if table_rows:
            # Создаём таблицу в docx
            num_cols = max(len(row) for row in table_rows)
            if num_cols > 0:
                t = doc.add_table(rows=0, cols=num_cols)
                t.style = 'Table Grid'
                for row_idx, row_cells in enumerate(table_rows):
                    row_obj = t.add_row()
                    for col_idx, cell_text in enumerate(row_cells):
                        if col_idx < num_cols:
                            cell = row_obj.cells[col_idx]
                            cell.text = cell_text
                            if row_idx == 0:
                                for paragraph in cell.paragraphs:
                                    for run in paragraph.runs:
                                        run.bold = True
        elif ':' in section_content and '\n' in section_content:
            add_key_value_table(doc, section_content)
        else:
            add_single_column_table(doc, section_content)


# Служебные строки, которые никогда не должны попасть в Word-документ
_SERVICE_LINE_PREFIXES = (
    '=== результаты поиска',
    '=== конец результатов',
    '=== верифицированные email',
    '=== используй эти email',
    '--- аналоги бренда',
    '--- производители глобально',
    '--- азия',
    '--- азия/турция',
    '--- европа',
    '--- дистрибьюторы',
    '--- производитель',
    '--- производители',
)


def _is_service_line(line):
    """Возвращает True если строка — служебная метка, не нужная в документе."""
    low = line.strip().lower()
    return any(low.startswith(p) for p in _SERVICE_LINE_PREFIXES)


def _clean_suppliers_for_docx(suppliers_text):
    """
    Очищает текст поставщиков от всех служебных строк, сырых URL и HTML-артефактов.
    Возвращает список чистых строк для записи в документ.
    """
    if not suppliers_text:
        return []

    clean_lines = []
    for raw in suppliers_text.split('\n'):
        line = raw.strip()
        if not line:
            clean_lines.append('')
            continue
        # Пропускаем служебные строки
        if _is_service_line(line):
            continue
        # Пропускаем сырые URL
        if re.match(r'^https?://', line):
            continue
        # Убираем URL-encoded артефакты в начале строки
        line = re.sub(r'^(%[0-9A-Fa-f]{2})+', '', line).strip()
        # Убираем u003e артефакт
        if line.lower().startswith('u003e'):
            line = line[5:].strip()
        if line:
            clean_lines.append(line)

    # Убираем лишние пустые строки подряд
    result = []
    prev_empty = False
    for ln in clean_lines:
        if ln == '':
            if not prev_empty:
                result.append(ln)
            prev_empty = True
        else:
            result.append(ln)
            prev_empty = False
    return result


def create_tender_report(reg_number, deadline_str, response, suppliers_text, output_dir):
    """
    Создаёт Word-отчёт (.docx) для тендера.
    Возвращает путь к сохранённому файлу.
    """
    doc = Document()
    doc.add_heading(f"Аналитический отчёт по закупке № {reg_number}", level=1)
    doc.add_paragraph(f"Дата окончания подачи заявок: {deadline_str}")
    add_structured_report(doc, response)
    doc.add_heading("Возможные поставщики и контакты", level=2)
    if suppliers_text:
        clean_lines = _clean_suppliers_for_docx(suppliers_text)
        # Отфильтрованный текст не пуст?
        non_empty = [l for l in clean_lines if l.strip()]
        if non_empty:
            for line in clean_lines:
                if line.strip():
                    doc.add_paragraph(line)
                # пустые строки пропускаем — docx и так добавляет отступы
        else:
            doc.add_paragraph("(Заполняется вручную)")
    else:
        doc.add_paragraph("(Заполняется вручную)")

    os.makedirs(output_dir, exist_ok=True)
    doc_path = os.path.join(output_dir, f"{reg_number}.docx")
    doc.save(doc_path)
    return doc_path

