def _load_sender_config():
    """Читает sender_config.json из папки скрипта. При ошибке — пустой dict."""
    cfg_path = Path(__file__).parent / "sender_config.json"
    if not cfg_path.exists():
        return {}
    try:
        with open(cfg_path, encoding="utf-8") as f:
            return _json.load(f)
    except Exception as e:
        print(f"[ВНИМАНИЕ] Ошибка чтения sender_config.json: {e}")
        return {}


def get_sender_for_region(region_str, sender_config):
    """
    Возвращает sender_id (str) для указанного региона тендера.
    """
    default = sender_config.get("default_sender", "vitro")
    rules = sender_config.get("region_rules", [])
    region_lower = (region_str or "").lower()
    for rule in rules:
        patterns = rule.get("regions", [])
        for p in patterns:
            if p == "*" or p.lower() in region_lower:
                return rule.get("sender", default)
    return default


def resolve_sender_credentials(sender_id, sender_config, secrets=None):
    """
    Возвращает (email, password, template_path) для указанного sender_id.
    """
    if secrets is None:
        secrets = _SECRETS
    senders = sender_config.get("senders", {})
    cfg = senders.get(sender_id, {})

    email = secrets.get(cfg.get("email_secret", ""), "")
    password = secrets.get(cfg.get("password_secret", ""), "")

    if not email and "email_fallback_secret" in cfg:
        email = secrets.get(cfg["email_fallback_secret"], "")
        if email:
            print(f"  [ВНИМАНИЕ] '{sender_id}': основной ключ пуст, "
                  f"используется fallback {cfg['email_fallback_secret']}")
    if not password and "password_fallback_secret" in cfg:
        password = secrets.get(cfg["password_fallback_secret"], "")

    tpl_rel = cfg.get("template", "")
    if tpl_rel:
        tpl_path = str(Path(__file__).parent / tpl_rel)
    else:
        tpl_path = EMAIL_TEMPLATE_PATH

    return email, password, tpl_path


