def init_email_db():
    """Создаёт таблицу логов email, если её ещё нет."""
    os.makedirs(os.path.dirname(EMAIL_DB_PATH), exist_ok=True)
    conn = sqlite3.connect(EMAIL_DB_PATH)
    conn.execute("""
        CREATE TABLE IF NOT EXISTS email_log (
            id          INTEGER PRIMARY KEY AUTOINCREMENT,
            sent_at     TEXT    NOT NULL,
            tender_num  TEXT    NOT NULL,
            tender_subj TEXT,
            to_email    TEXT    NOT NULL,
            status      TEXT    NOT NULL,
            error_msg   TEXT
        )
    """)
    conn.commit()
    conn.close()


def log_email(tender_num, tender_subj, to_email, status, error_msg=""):
    """Пишет строку в email_log.db."""
    conn = sqlite3.connect(EMAIL_DB_PATH)
    conn.execute(
        "INSERT INTO email_log (sent_at, tender_num, tender_subj, to_email, status, error_msg) "
        "VALUES (?, ?, ?, ?, ?, ?)",
        (
            datetime.datetime.now().strftime("%Y-%m-%d %H:%M:%S"),
            tender_num,
            tender_subj or "",
            to_email,
            status,
            error_msg,
        ),
    )
    conn.commit()
    conn.close()


def already_sent(tender_num, to_email):
    """True если это письмо уже было успешно отправлено ранее."""
    if not os.path.exists(EMAIL_DB_PATH):
        return False
    conn = sqlite3.connect(EMAIL_DB_PATH)
    row = conn.execute(
        "SELECT 1 FROM email_log WHERE tender_num=? AND to_email=? AND status='ok' LIMIT 1",
        (tender_num, to_email),
    ).fetchone()
    conn.close()
    return row is not None


def check_mx(domain):
    """True если у домена есть MX-запись."""
    if not DNS_AVAILABLE:
        return True
    try:
        answers = dns.resolver.resolve(domain, "MX", lifetime=5)
        return len(answers) > 0
    except Exception:
        return False


def extract_emails_from_text(text):
    """Вытаскивает email-адреса из текста поставщиков."""
    raw = re.findall(r'[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}', text)
    seen = set()
    result = []
    for email in raw:
        em = email.lower().strip(".,;")
        if em not in seen:
            seen.add(em)
            result.append(em)
    return result


def load_email_template(template_path=None):
    """Читает шаблон из файла. При ошибке — встроенный fallback."""
    path = template_path or EMAIL_TEMPLATE_PATH
    try:
        with open(path, encoding="utf-8") as f:
            return f.read()
    except Exception:
        return (
            "Subject: {rfq_subject}\n\n"
            "Dear Sales Team,\n\n"
            "Tender reference: {tender_number}\n"
            "Tender subject: {tender_subject}\n"
            "Tender link: {tender_url}\n\n"
            "Please provide your quotation for the following items:\n\n"
            "{items_table}\n\n"
            "Please indicate the unit and total price, availability, lead time, "
            "payment and shipment terms, manufacturer and country of origin, "
            "warranty: {warranty_requirement}, available quality documents, "
            "packing dimensions and gross weight.\n\n"
            "Please send your quotation as soon as possible, preferably by "
            "{tender_deadline_en}."
        )


def send_rfq_email(to_email, tender_data, from_email=None, from_password=None, template_path=None):
    """
    Отправляет одно RFQ-письмо через Gmail SMTP.
    tender_data: dict с ключами tender_subject, tender_number,
                 tender_deadline, tender_price, tender_url,
                 и опционально: brand, items_table (list of dicts),
                 sender_name, sender_company
    Возвращает (True, "") или (False, "текст ошибки").
    """
    sender_email = from_email or GMAIL_ADDRESS
    sender_password = from_password or GMAIL_APP_PASSWORD
    if not sender_email or not sender_password:
        return False, "Email credentials не заданы (проверьте secrets.txt и sender_config.json)"

    _BLANK_SENTINELS = {"—", "-", "–", "−"}
    _required = ["tender_subject", "tender_number", "tender_deadline", "tender_price", "tender_url"]
    _missing = [
        f for f in _required
        if tender_data.get(f) is None
        or str(tender_data.get(f)).strip() == ""
        or str(tender_data.get(f)).strip() in _BLANK_SENTINELS
    ]
    if _missing:
        return False, f"Обязательные поля не заполнены: {', '.join(_missing)}"

    try:
        _price_val = float(
            str(tender_data.get("tender_price", "0")).replace(" ", "").replace(",", ".")
        )
        if _price_val == 0:
            return False, "tender_price равен нулю — отправка заблокирована"
    except ValueError:
        pass

    tpl_path = template_path or EMAIL_TEMPLATE_PATH
    try:
        with open(tpl_path, encoding="utf-8") as f:
            template = f.read()
    except Exception:
        template = load_email_template()

    # ── Подготовка значений плейсхолдеров ─────────────────────────────────
    tender_number   = str(tender_data.get("tender_number", "—"))
    tender_subject  = str(tender_data.get("tender_subject", "—"))
    tender_deadline = str(tender_data.get("tender_deadline", "—"))
    tender_price    = str(tender_data.get("tender_price", "—"))
    tender_url      = str(tender_data.get("tender_url", "—"))
    sender_name     = str(tender_data.get("sender_name", "Procurement Team")).strip()
    sender_company  = str(tender_data.get("sender_company", "VITRO LOGISTIC LLC")).strip()
    brand_raw       = str(tender_data.get("brand", "") or "").strip()

    # Дедлайн в английском формате
    deadline_en = _format_date_english(tender_deadline)

    # Товарные позиции обязательны: нельзя отправлять RFQ с заглушкой.
    items_raw = tender_data.get("items_table") or []
    if not isinstance(items_raw, list) or not any(
        isinstance(item, dict)
        and (
            str(item.get("item", "")).strip()
            or str(item.get("part_number", "")).strip()
        )
        for item in items_raw
    ):
        return False, "В очереди отсутствует список позиций для RFQ"

    # Бренд используется только для короткой англоязычной темы.
    if brand_raw and 'информация отсутствует' not in brand_raw.lower():
        brand_clean = re.sub(r'\s*\(.*?\)\s*$', '', brand_raw).strip()
        brand_clean = brand_clean.split(',')[0].strip()
    else:
        brand_clean   = ""
 
    # Строим короткую английскую тему по бренду и артикулу, без русского
    # названия закупки и без искусственного обрезания середины текста.
    part_number = ""
    for item in items_raw:
        if not isinstance(item, dict):
            continue
        candidate = str(item.get("part_number", "")).strip()
        if candidate and candidate not in _BLANK_SENTINELS:
            part_number = candidate
            break

    subject_parts = [f"RFQ {tender_number}"]
    if brand_clean and re.search(r"[A-Za-z]", brand_clean):
        subject_parts.append(brand_clean)
    if part_number and re.search(r"[A-Za-z0-9]", part_number):
        subject_parts.append(part_number)
    if len(subject_parts) == 1:
        subject_parts.append("Request for Quotation")
    rfq_subject = " | ".join(subject_parts)

    items_table_str = _format_items_table_as_text(items_raw)
    warranty_requirement = str(
        tender_data.get("warranty_requirement")
        or "as specified in the tender requirements"
    ).strip()

    # ── Подстановка ───────────────────────────────────────────────────────
    body = template
    for key, val in {
        "tender_subject":     tender_subject,
        "tender_number":      tender_number,
        "tender_deadline":    tender_deadline,
        "tender_deadline_en": deadline_en,
        "deadline":           deadline_en,
        "tender_price":       tender_price,
        "tender_url":         tender_url,
        "sender_name":        sender_name,
        "sender_company":     sender_company,
        "brand":              brand_clean,
        "rfq_subject":        rfq_subject,
        "warranty_requirement": warranty_requirement,
        "items_table":        items_table_str,
    }.items():
        body = body.replace("{" + key + "}", str(val))

    # ── Извлечение темы письма из первой строки ────────────────────────────
    subject_line = None
    lines = body.splitlines()
    for prefix in ("Subject:", "Тема:"):
        if lines and lines[0].startswith(prefix):
            subject_line = lines[0][len(prefix):].strip()
            rest = lines[1:]
            if rest and rest[0].strip() == "":
                rest = rest[1:]
            body = "\n".join(rest)
            break
    if not subject_line:
        subject_line = rfq_subject

    msg = MIMEMultipart("alternative")
    msg["Subject"] = subject_line
    msg["From"] = sender_email
    msg["To"] = to_email
    msg.attach(MIMEText(body, "plain", "utf-8"))

    try:
        with smtplib.SMTP("smtp.gmail.com", 587, timeout=30) as server:
            server.ehlo()
            server.starttls()
            server.login(sender_email, sender_password)
            server.sendmail(sender_email, [to_email], msg.as_string())
        return True, ""
    except Exception as e:
        return False, str(e)

