QUEUE_PATH = str(Path(__file__).parent / "data" / "rfq_queue.json")


def load_queue():
    if not os.path.exists(QUEUE_PATH):
        print(f"[ОШИБКА] Файл очереди не найден: {QUEUE_PATH}")
        print("Сначала запусти tender_auto.py — он создаст очередь после анализа.")
        return None
    with open(QUEUE_PATH, encoding="utf-8") as f:
        return json.load(f)


def doc_still_exists(doc_path):
    """True если Word-отчёт не был удалён пользователем."""
    if not doc_path:
        return False
    if os.path.exists(doc_path):
        return True
    # Fallback: ищем по имени файла в output/
    filename = os.path.basename(doc_path)
    output_dir = str(Path(__file__).parent / "output")
    for root, dirs, files in os.walk(output_dir):
        if filename in files:
            return True
    return False


REQUIRED_TENDER_FIELDS = [
    "tender_subject",
    "tender_number",
    "tender_deadline",
    "tender_price",
    "tender_url",
]


_BLANK_SENTINELS = {"—", "-", "–", "−"}  # тире-заменители, которые queue пишет вместо пустых полей


def _field_is_blank(value):
    """True если значение считается отсутствующим (None, пустая строка, тире-placeholder)."""
    if value is None:
        return True
    s = str(value).strip()
    return s == "" or s in _BLANK_SENTINELS


def validate_tender_fields(entry):
    """
    Проверяет, что все обязательные поля тендера заполнены и не равны нулю.
    Также отвергает placeholder-значения («—» и аналоги), которые queue.json
    записывает когда поле отсутствует в Excel-выгрузке.
    Возвращает список строк с описанием проблем (пустой список — всё в порядке).
    """
    problems = []
    for field in REQUIRED_TENDER_FIELDS:
        value = entry.get(field)
        if _field_is_blank(value):
            problems.append(f"поле '{field}' пустое или отсутствует")
            continue
        # Нулевая цена
        if field == "tender_price":
            try:
                numeric = float(str(value).replace(" ", "").replace(",", "."))
                if numeric == 0:
                    problems.append(f"поле '{field}' равно нулю")
            except ValueError:
                pass  # не числовое — принимаем как есть (например «не указана»)

    items = entry.get("items_table")
    if not isinstance(items, list) or not any(
        isinstance(item, dict)
        and (
            str(item.get("item", "")).strip()
            or str(item.get("part_number", "")).strip()
        )
        for item in items
    ):
        problems.append("поле 'items_table' отсутствует или не содержит позиций")

    return problems


def _check_placeholder(value):
    """True если значение выглядит как незаполненный placeholder из secrets.txt."""
    if not value:
        return True
    placeholder_markers = ("вставь_сюда", "insert_here", "your_", "<", ">", "placeholder")
    v_lower = value.lower()
    return any(m in v_lower for m in placeholder_markers)


def validate_sender_credentials(sender_id, sender_config, secrets):
    """
    Явно проверяет, что credentials отправителя заданы и не являются
    placeholder-значениями. Возвращает список строк-предупреждений (пусто — ОК).
    """
    warnings = []
    senders = sender_config.get("senders", {})
    cfg = senders.get(sender_id, {})

    email_key    = cfg.get("email_secret", "")
    password_key = cfg.get("password_secret", "")

    email_val    = secrets.get(email_key, "")
    password_val = secrets.get(password_key, "")

    if not email_key:
        warnings.append(f"'{sender_id}': email_secret не задан в sender_config.json")
    elif _check_placeholder(email_val):
        warnings.append(
            f"'{sender_id}': {email_key} = '{email_val}' выглядит как незаполненный "
            f"placeholder — замени реальным адресом в secrets.txt"
        )

    if not password_key:
        warnings.append(f"'{sender_id}': password_secret не задан в sender_config.json")
    elif _check_placeholder(password_val):
        warnings.append(
            f"'{sender_id}': {password_key} = '{password_val}' выглядит как незаполненный "
            f"placeholder — замени реальным паролем приложения в secrets.txt"
        )

    return warnings


# ========================= BUILD-QUEUE FROM REPORTS =========================

def _extract_emails_from_docx(path):
    """
    Открывает docx и возвращает список уникальных email из раздела
    «Возможные поставщики и контакты».
    Распознаёт строки «E-mail для поставщика N — email@...»
    и любые email-паттерны в том же разделе.
    """
    try:
        from docx import Document as _DocxDocument
    except ImportError:
        return []
    try:
        doc = _DocxDocument(path)
    except Exception:
        return []

    _re = re.compile(r'[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}')
    emails = []
    in_section = False

    for para in doc.paragraphs:
        text = para.text.strip()
        if not text:
            continue
        # Начало раздела поставщиков
        if 'Возможные поставщики' in text:
            in_section = True
            continue
        # Конец раздела — следующий heading
        if in_section and para.style and 'Heading' in (para.style.name or ''):
            break
        if in_section:
            for m in _re.finditer(text):
                emails.append(m.group(0))

    # Дедупликация с сохранением порядка
    seen: set = set()
    result = []
    for e in emails:
        key = e.lower()
        if key not in seen:
            seen.add(key)
            result.append(e)
    return result


def _extract_deadline_from_docx(path):
    """
    Извлекает строку дедлайна из заголовка docx.
    Ищет параграф «Дата окончания подачи заявок: ДД.ММ.ГГГГ».
    Возвращает строку вида «14.08.2026» или «—» если не найдено.
    """
    try:
        from docx import Document as _DocxDocument
        doc = _DocxDocument(path)
    except Exception:
        return "—"
    for para in doc.paragraphs[:8]:
        text = para.text.strip()
        if text.startswith("Дата окончания подачи заявок:"):
            return text.split(":", 1)[1].strip()
    return "—"
def _get_tender_meta_from_db(reg_number):
    """
    Возвращает dict {subject, nmck} из decisions.db по номеру тендера.
    Если запись не найдена — возвращает заглушки «—».
    """
    db_path = str(DATA_DIR / "decisions.db")
    if not os.path.exists(db_path):
        return {"subject": "—", "nmck": "—"}
    try:
        conn = sqlite3.connect(db_path)
        row = conn.execute(
            "SELECT subject, nmck FROM decisions WHERE tender_number=?",
            (reg_number,)
        ).fetchone()
        conn.close()
        if row:
            return {"subject": row[0] or "—", "nmck": row[1] or "—"}
    except Exception:
        pass
    return {"subject": "—", "nmck": "—"}


# ========================= DOCX-ЭКСТРАКТОРЫ ДЛЯ ОЧЕРЕДИ RFQ =========================

_RU_MONTHS_EN = {
    1: "January", 2: "February", 3: "March", 4: "April",
    5: "May", 6: "June", 7: "July", 8: "August",
    9: "September", 10: "October", 11: "November", 12: "December",
}


def _format_date_english(date_str):
    """Конвертирует «ДД.ММ.ГГГГ» в «14 August 2026». При ошибке — возвращает оригинал."""
    m = re.match(r'(\d{1,2})\.(\d{2})\.(\d{4})', str(date_str).strip())
    if m:
        day, month, year = int(m.group(1)), int(m.group(2)), int(m.group(3))
        return f"{day} {_RU_MONTHS_EN.get(month, m.group(2))} {year}"
    return str(date_str)


def _extract_warranty_requirement(text):
    """
    Возвращает безопасное англоязычное требование по гарантии.
    Не придумывает срок, если в аналитическом ответе он не найден.
    """
    source = str(text or "")
    months = re.search(
        r'гарант\w*[^.\n]{0,120}?не\s+менее\s+(\d+)\s*(?:месяц\w*|мес\.?)',
        source,
        flags=re.IGNORECASE,
    )
    if months:
        return f"at least {months.group(1)} months"

    years = re.search(
        r'гарант\w*[^.\n]{0,120}?не\s+менее\s+(\d+)\s*(?:год\w*|лет)',
        source,
        flags=re.IGNORECASE,
    )
    if years:
        return f"at least {years.group(1)} years"

    return "as specified in the tender requirements"


def _extract_brand_from_docx(path):
    """
    Извлекает бренд/производитель из раздела «Производитель / бренд / страна» docx-отчёта.
    Использует XML-обход тела документа для надёжного сопоставления заголовков и контента.
    Возвращает строку бренда или '' если раздел не найден / «информация отсутствует».
    """
    try:
        from docx import Document as _DocxDocument
    except ImportError:
        return ''
    try:
        doc = _DocxDocument(path)
    except Exception:
        return ''

    NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

    def _elem_text(el):
        return ''.join(t.text or '' for t in el.iter(f'{{{NS}}}t')).strip()

    in_section = False
    for child in doc.element.body:
        local = child.tag.split('}')[-1] if '}' in child.tag else child.tag
        if local != 'p':
            if in_section:
                break
            continue
        text = _elem_text(child)
        if 'Производитель' in text and 'бренд' in text:
            in_section = True
            continue
        if in_section:
            if not text:
                continue
            # Next heading → end of section
            pPr = child.find(f'{{{NS}}}pPr')
            if pPr is not None:
                pStyle = pPr.find(f'{{{NS}}}pStyle')
                if pStyle is not None:
                    val = pStyle.get(f'{{{NS}}}val', '')
                    if 'heading' in val.lower() or val.isdigit():
                        break
            # Skip "unavailable" placeholders
            low = text.lower()
            if 'информация отсутствует' in low:
                return ''
            if text in ('(заполняется вручную)', '—', '-', '–'):
                return ''
            return text
    return ''

def _format_items_table_as_text(items):
    """
    Formats a list of item dicts as a plain-text aligned table for email bodies.
    Combines unit and quantity into a single Qty column.
    """
    if not items:
        return '(No specific items provided — see tender documentation)'

    def _qty_str(item):
        qty  = str(item.get('quantity', '')).strip()
        unit = str(item.get('unit', '')).strip()
        if qty and unit:
            return f'{qty} {unit}'
        return qty or unit or '—'

    # Build rows: header + data
    rows = [('No.', 'Item', 'Part number', 'Quantity')]
    for item in items:
        rows.append((
            str(item.get('no', '')).strip() or '—',
            str(item.get('item', '')).strip() or '—',
            str(item.get('part_number', '—')).strip() or '—',
            _qty_str(item),
        ))

    # Compute column widths
    widths = [max(len(r[i]) for r in rows) for i in range(4)]

    def _fmt(row):
        return '  '.join(cell.ljust(widths[i]) for i, cell in enumerate(row))

    lines = [_fmt(rows[0])]
    lines.append('  '.join('-' * w for w in widths))
    for row in rows[1:]:
        lines.append(_fmt(row))
    return '\n'.join(lines)


def _extract_items_table_from_docx(path):
    """
    Извлекает таблицу позиций из раздела «Что нужно поставить» docx-отчёта.
    Возвращает list of dicts с ключами: no, item, part_number, unit, quantity.
    Нормализует сдвиг колонок, возникающий когда LLM генерирует пустую ведущую
    ячейку в строках данных (стандартная ситуация при конвертации Markdown → docx).
    Возвращает [] если раздел не найден или не содержит таблицы.
    """
    try:
        from docx import Document as _DocxDocument
    except ImportError:
        return []
    try:
        doc = _DocxDocument(path)
    except Exception:
        return []

    NS = 'http://schemas.openxmlformats.org/wordprocessingml/2006/main'

    def _elem_text(el):
        return ''.join(t.text or '' for t in el.iter(f'{{{NS}}}t')).strip()

    def _col_idx(headers, keywords):
        for kw in keywords:
            for i, h in enumerate(headers):
                if kw.lower() in h.lower():
                    return i
        return -1

    in_section = False
    for child in doc.element.body:
        local = child.tag.split('}')[-1] if '}' in child.tag else child.tag

        if local == 'p':
            text = _elem_text(child)
            if 'Что нужно поставить' in text:
                in_section = True
                continue
            if in_section and text:
                # Следующий раздел-заголовок → конец секции
                pPr = child.find(f'{{{NS}}}pPr')
                if pPr is not None:
                    pStyle = pPr.find(f'{{{NS}}}pStyle')
                    if pStyle is not None:
                        val = pStyle.get(f'{{{NS}}}val', '')
                        if 'heading' in val.lower() or val.isdigit():
                            break
        elif local == 'tbl' and in_section:
            tbl_rows = child.findall(f'{{{NS}}}tr')
            if len(tbl_rows) < 2:
                break
            headers = [_elem_text(tc) for tc in tbl_rows[0].findall(f'{{{NS}}}tc')]

            # Убираем хвостовые пустые ячейки заголовка
            # (артефакт конвертации Markdown-таблицы → docx)
            while headers and not headers[-1]:
                headers.pop()
            num_header_cols = len(headers)

            idx_no   = _col_idx(headers, ['№', 'No', '№/'])
            idx_item = _col_idx(headers, ['Наимен', 'Item', 'Назван'])
            idx_part = _col_idx(headers, ['Артикул', 'Каталож', 'Part'])
            idx_unit = _col_idx(headers, ['Ед.', 'изм', 'Unit'])
            idx_qty  = _col_idx(headers, ['Кол', 'Qty', 'Quantity'])

            result = []
            for tr in tbl_rows[1:]:
                cells = [_elem_text(tc) for tc in tr.findall(f'{{{NS}}}tc')]
                if not any(cells):
                    continue

                # Нормализация: если первая ячейка пустая, пропускаем её.
                # ЛЛМ часто генерирует пустую ведущую ячейку (вместо № строки)
                # независимо от итогового числа ячеек в строке.
                if cells and not cells[0]:
                    cells = cells[1:]

                def _get(idx, default=''):
                    return cells[idx] if 0 <= idx < len(cells) else default

                result.append({
                    'no':          _get(idx_no),
                    'item':        _get(idx_item),
                    'part_number': _get(idx_part) or '—',
                    'unit':        _get(idx_unit),
                    'quantity':    _get(idx_qty),
                })
            return result

    return []


def build_queue_from_reports(folder_arg, force=False):
    """
    Сканирует папку с docx-отчётами, извлекает email из раздела
    «Возможные поставщики и контакты» и пересобирает rfq_queue.json.
    Также извлекает таблицу позиций (items_table) и бренд (brand) из каждого отчёта.

    Вызывается командой:
        python tender_auto.py --build-queue <папка> [--force]

    <папка> — имя папки внутри output/ или полный путь.
    --force  — перезаписать rfq_queue.json без вопросов.
    """
    print("=" * 70)
    print("📥 BUILD-QUEUE — Формирование очереди RFQ из docx-отчётов")
    print("=" * 70)

    # ── Определяем папку ─────────────────────────────────────────────────
    output_base = Path(OUTPUT_BASE)
    candidate = Path(folder_arg)
    if not candidate.is_absolute():
        rel = output_base / folder_arg
        if rel.exists():
            candidate = rel
    if not candidate.exists() or not candidate.is_dir():
        print(f"❌ Папка не найдена: {folder_arg}")
        print(f"   Укажи имя папки внутри output/ (например «Козлов_10.08.2026»)")
        print(f"   или полный путь.")
        return

    print(f"  Папка: {candidate.resolve()}")

    # ── Проверка существующего queue.json ────────────────────────────────
    queue_path = str(DATA_DIR / "rfq_queue.json")
    if os.path.exists(queue_path) and not force:
        try:
            ans = input(
                f"\n  ⚠️  rfq_queue.json уже существует. Перезаписать? [y/N]: "
            ).strip().lower()
        except (EOFError, KeyboardInterrupt):
            ans = ""
        if ans not in ("y", "yes", "д", "да"):
            print("  Отменено.")
            return

    sender_config = _load_sender_config()
    default_sender = sender_config.get("default_sender", "vitro")

    tenders = []
    total_docx = 0
    skip_china = 0

    # ── Рекурсивный обход папки ───────────────────────────────────────────
    for doc_file in sorted(candidate.rglob("*.docx")):
        # Пропускаем копии из папки «Доступные к закупке в Китае» — дубли
        if "Доступные к закупке в Китае" in str(doc_file):
            skip_china += 1
            continue

        total_docx += 1
        reg_number   = doc_file.stem   # имя файла без расширения = номер тендера
        raw_emails   = _extract_emails_from_docx(str(doc_file))
        emails, rejected_emails = _select_rfq_emails(raw_emails)
        deadline_str = _extract_deadline_from_docx(str(doc_file))
        meta         = _get_tender_meta_from_db(reg_number)
        brand        = _extract_brand_from_docx(str(doc_file))
        items        = _extract_items_table_from_docx(str(doc_file))

        tender_url = (
            "https://zakupki.gov.ru/epz/order/notice/notice223/common-info.html"
            f"?regNumber={reg_number}"
        )
        tenders.append({
            "tender_number":   reg_number,
            "tender_subject":  meta["subject"],
            "tender_deadline": deadline_str,
            "tender_price":    meta["nmck"],
            "tender_url":      tender_url,
            "emails":          emails,
            "sender_id":       default_sender,
            "doc_path":        str(doc_file.resolve()),
            "brand":           brand,
            "items_table":     items,
            "warranty_requirement": "as specified in the tender requirements",
        })

        brand_note = f", бренд: {brand}" if brand else ""
        items_note = f", {len(items)} позиций" if items else ""
        email_note = f"{len(emails)} коммерческих email" if emails else "нет коммерческого email"
        icon = "✅" if emails else "⚠️ "
        print(f"  {icon} {reg_number}  ({email_note}{brand_note}{items_note})")
        if rejected_emails:
            print(f"      Отфильтровано контактов: {len(rejected_emails)}")

    # ── Сводка ───────────────────────────────────────────────────────────
    with_email    = sum(1 for t in tenders if t["emails"])
    without_email = len(tenders) - with_email

    print()
    print(f"  Найдено docx:             {total_docx}")
    if skip_china:
        print(f"  Пропущено (копии Китай):  {skip_china}")
    print(f"  Тендеров в очереди:       {len(tenders)}")
    print(f"  Из них с email:           {with_email}")
    print(f"  Без email (заполни вручную): {without_email}")

    if not tenders:
        print("\n⚠️  Нет docx-файлов для обработки. Очередь не создана.")
        return

    # ── Запись rfq_queue.json ─────────────────────────────────────────────
    DATA_DIR.mkdir(parents=True, exist_ok=True)
    payload = {
        "run_date": datetime.datetime.now().strftime("%Y-%m-%d %H:%M"),
        "source":   "build-queue",
        "folder":   str(candidate.resolve()),
        "tenders":  tenders,
    }
    with open(queue_path, "w", encoding="utf-8") as f:
        _json.dump(payload, f, ensure_ascii=False, indent=2)

    print(f"\n✅ Очередь сохранена → {os.path.abspath(queue_path)}")
    if without_email:
        print(f"  ℹ️  {without_email} тендеров без email — добавь адреса в rfq_queue.json")
    print("  Для отправки: python tender_auto.py --send-rfq")
    print("=" * 70)


def send_rfq_main():
    print("=" * 70)
    print("📧 SEND_RFQ — Отправка писем поставщикам")
    print("=" * 70)

    if not EMAIL_ENABLED:
        print("[ОШИБКА] EMAIL_ENABLED = False в tender_auto.py. Включи и повтори.")
        return

    _ALL_SECRETS  = _SECRETS          # алиас для совместимости (send_rfq использовал это имя)
    secrets       = _ALL_SECRETS
    sender_config = _load_sender_config()
    senders_cfg   = sender_config.get("senders", {})

    # --- Предварительная проверка credentials default_sender ---
    default_sender = sender_config.get("default_sender", "vitro")
    cred_warnings  = validate_sender_credentials(default_sender, sender_config, secrets)
    if cred_warnings:
        print()
        print("  ⚠️  ПРЕДУПРЕЖДЕНИЕ: credentials отправителя не готовы к работе:")
        for w in cred_warnings:
            print(f"      • {w}")
        print()
        print("  ❌ Отправка прервана — заполни secrets.txt и повтори запуск.")
        print("=" * 70)
        return

    if senders_cfg:
        print(f"  Отправители в конфиге: {', '.join(senders_cfg.keys())}")
    else:
        print("  sender_config.json не найден — используется единственный отправитель")

    init_email_db()

    queue_data = load_queue()
    if not queue_data:
        return

    tenders  = queue_data.get("tenders", [])
    run_date = queue_data.get("run_date", "?")
    print(f"  Очередь от:    {run_date}")
    print(f"  Тендеров:      {len(tenders)}")
    print()

    sent_total   = 0
    skip_deleted = 0
    skip_dup     = 0
    skip_mx      = 0
    skip_no_email = 0
    skip_invalid = 0
    err_total    = 0

    for entry in tenders:
        tender_num  = entry.get("tender_number", "?")
        tender_subj = entry.get("tender_subject", "?")
        doc_path    = entry.get("doc_path", "")
        raw_emails  = entry.get("emails", [])
        sender_id   = entry.get("sender_id", sender_config.get("default_sender", "vitro"))

        # Старые очереди тоже защищаем от технических и учебных адресов.
        # Для намеренно добавленных нестандартных адресов предусмотрен
        # явный флаг allow_noncommercial_emails=true в конкретной записи.
        if entry.get("allow_noncommercial_emails") is True:
            emails = list(dict.fromkeys(
                str(email).strip().lower()
                for email in raw_emails
                if str(email).strip()
            ))
            rejected_emails = []
        else:
            emails, rejected_emails = _select_rfq_emails(raw_emails)
        entry["emails"] = emails

        # Inject sender display info (sender_name, sender_company) from sender_config
        _sender_cfg = sender_config.get("senders", {}).get(sender_id, {})
        entry.setdefault("sender_name",    _sender_cfg.get("sender_name",    "Procurement Team"))
        entry.setdefault("sender_company", _sender_cfg.get("sender_company", "VITRO LOGISTIC LLC"))

        # Проверяем обязательные поля тендера (тема, цена, URL и др.)
        field_problems = validate_tender_fields(entry)
        if field_problems:
            print(f"  ⛔ [{tender_num}] — пропущен: неполные данные:")
            for prob in field_problems:
                print(f"       • {prob}")
            skip_invalid += 1
            continue

        # Проверяем: пользователь не удалил отчёт?
        if not doc_still_exists(doc_path):
            print(f"  ⏭️  [{tender_num}] — отчёт удалён, пропускаем")
            skip_deleted += 1
            continue

        if rejected_emails:
            print(f"  ⛔ [{tender_num}] — отфильтровано контактов: {len(rejected_emails)}")

        # Тендер без коммерческих email-адресов — нужна ручная проверка
        if not emails:
            print(f"  ⚠️  [{tender_num}] — коммерческие email не найдены "
                  f"(при необходимости добавь адреса в rfq_queue.json)")
            skip_no_email += 1
            continue

        # Разрешаем credentials для этого отправителя
        from_email, from_password, template_path = resolve_sender_credentials(
            sender_id, sender_config, secrets
        )

        if not from_email or not from_password:
            print(f"  ❌ [{tender_num}] — нет credentials для отправителя '{sender_id}' "
                  f"(проверь secrets.txt)")
            err_total += 1
            continue

        # Инжектируем sender_name/company из конфига в entry для шаблона
        sender_cfg = sender_config.get("senders", {}).get(sender_id, {})
        entry.setdefault("sender_name", sender_cfg.get("sender_name", "Procurement Team"))
        entry.setdefault("sender_company", sender_cfg.get("sender_company", "VITRO LOGISTIC LLC"))

        brand_note = f" | Бренд: {entry['brand']}" if entry.get("brand") else ""
        items_note = f" | {len(entry.get('items_table') or [])} поз." if entry.get("items_table") else ""
        print(f"\n  📋 [{tender_num}] {tender_subj[:55]}{brand_note}{items_note}")
        print(f"     Отправитель: {sender_id} ({from_email}) — {entry['sender_name']}")
        print(f"     Дедлайн: {entry.get('tender_deadline','?')}  |  "
              f"НМЦК: {entry.get('tender_price','?')} руб.  |  "
              f"Адресов: {len(emails)}")

        for em in emails:
            domain = em.split("@")[-1] if "@" in em else ""

            if already_sent(tender_num, em):
                skip_dup += 1
                continue

            if not check_mx(domain):
                print(f"    ⚠️  {em} — нет MX, пропуск")
                log_email(tender_num, tender_subj, em, "skip_no_mx")
                skip_mx += 1
                continue

            ok, err_msg = send_rfq_email(
                em, entry,
                from_email=from_email,
                from_password=from_password,
                template_path=template_path,
            )
            if ok:
                print(f"    ✉️   Отправлено → {em}")
                log_email(tender_num, tender_subj, em, "ok")
                sent_total += 1
                time.sleep(EMAIL_RATE_LIMIT_SEC)
            else:
                print(f"    ❌  Ошибка → {em}: {err_msg}")
                log_email(tender_num, tender_subj, em, "error", err_msg)
                err_total += 1

    print("\n" + "=" * 70)
    print("📧 ИТОГ")
    print("=" * 70)
    print(f"  ✉️  Отправлено:              {sent_total}")
    print(f"  ⏭️  Пропущено (удалены):     {skip_deleted}")
    print(f"  ⛔ Пропущено (неполные данные): {skip_invalid}  ← проверь rfq_queue.json")
    print(f"  ⚠️  Пропущено (нет email):   {skip_no_email}  ← заполни в rfq_queue.json")
    print(f"  🔁 Пропущено (дубли):       {skip_dup}")
    print(f"  ⚠️  Пропущено (нет MX):     {skip_mx}")
    print(f"  ❌ Ошибок отправки:         {err_total}")
    print(f"  📂 Лог: {os.path.abspath(EMAIL_DB_PATH)}")
    print("=" * 70)


