# ── Модули-спутники ───────────────────────────────────────────────────────────


# Алиасы для обратной совместимости с тестами, которые импортируют из tender_auto
_is_b2p_domain = _is_b2b_domain

# =================== ORCHESTRATOR: PROCESS_TENDER ==========================

def _build_reliable_hints(row, excel_subject, excel_nmck, excel_customer, excel_region):
    """Формирует строку достоверных данных из Excel для промпта."""
    hints = "--- ДОСТОВЕРНЫЕ ДАННЫЕ ИЗ ВЫГРУЗКИ ---\n"
    if excel_nmck and pd.notna(excel_nmck):
        hints += f"НМЦК: {excel_nmck} руб.\n"
    if excel_customer and pd.notna(excel_customer):
        hints += f"Заказчик: {excel_customer}\n"
    if excel_subject and pd.notna(excel_subject):
        hints += f"Предмет закупки: {excel_subject}\n"
    if excel_region and pd.notna(excel_region):
        hints += f"Регион поставки: {excel_region}\n"
    hints += "--- КОНЕЦ ДОСТОВЕРНЫХ ДАННЫХ ---\n"
    return hints


def extract_brand_from_subject_and_filenames(excel_subject, downloaded_paths):
    """
    Извлекает кандидата бренда из темы закупки Excel и имён скачанных файлов.

    Алгоритм:
    - Ищет латинские слова ≥ 3 букв, не входящие в BRAND_BLACKLIST и не являющиеся
      типичными нарицательными словами (spec, report, doc и т.п.)
    - Источники: строка excel_subject + имена файлов (без расширения) из downloaded_paths
    - Возвращает (brand_candidate: str | None, is_reliable: bool)

    Возвращённый кандидат используется:
    - Всегда: добавляется в combined_hints как подсказка для LLM
    - Если is_reliable=True: применяется как brand_hint после LLM, если LLM не нашёл бренд сам
    """
    _NONCORPORATE_WORDS = {
        'spec', 'specs', 'technical', 'technic', 'technics',
        'file', 'document', 'doc', 'docs',
        'report', 'data', 'info', 'list', 'draft', 'final',
        'new', 'old', 'copy', 'ver', 'rev', 'version',
        'pdf', 'xlsx', 'docx', 'word', 'excel',
        'the', 'and', 'for', 'with', 'from', 'into',
        'purchase', 'supply', 'delivery', 'order', 'contract',
        'equipment', 'product', 'material', 'item', 'part',
        'price', 'cost', 'amount', 'total', 'unit',
        'type', 'model', 'serial', 'number', 'catalog',
        'annex', 'appendix', 'attachment', 'table', 'sheet',
        'oem', 'sku', 'ref', 'pos', 'qty',
    }
    latin_word_re = re.compile(r'\b([A-Za-z][A-Za-z0-9\-]{2,})\b')

    # Placeholder values that pandas produces for missing cells
    _EMPTY_PLACEHOLDERS = {'nan', 'none', 'null', 'na', 'n/a', '-', '—'}

    sources = []
    if (excel_subject is not None
            and str(excel_subject).strip()
            and str(excel_subject).strip().lower() not in _EMPTY_PLACEHOLDERS):
        try:
            import pandas as _pd
            _notna = _pd.notna(excel_subject)
        except Exception:
            _notna = True
        if _notna:
            sources.append(str(excel_subject).strip())

    for path in (downloaded_paths or []):
        fname = Path(path).stem  # имя файла без расширения
        # Разбиваем по типичным разделителям в именах файлов
        parts = re.split(r'[\-_\s]+', fname)
        sources.extend(parts)

    candidates = []
    for source in sources:
        for m in latin_word_re.finditer(source):
            word = m.group(1)
            if len(word) < 3:
                continue
            if word.upper() in BRAND_BLACKLIST:
                continue
            if word.lower() in _NONCORPORATE_WORDS:
                continue
            # Пропускаем чисто цифровые суффиксы и версии типа «V2», «R3»
            if re.fullmatch(r'[VvRr]?\d+', word):
                continue
            candidates.append(word)

    if not candidates:
        return None, False

    # Приоритет: самое длинное слово из чистых букв (числа в бренде редкость)
    best = max(candidates, key=lambda w: (w.isalpha(), len(w)))
    return best, _is_reliable_brand(best)


def _enrich_brand_in_response(response, brand_hint, doc_text, excel_subject,
                               decision):
    """
    Пытается заполнить поле производителя несколькими способами.
    Возвращает (response, brand_hint).
    """
    if brand_hint is None and decision in ('participate', 'clarify') and doc_text.strip():
        print("  🔎 1В: фрагментный поиск производителя по тексту документов...")
        found = extract_manufacturer_from_chunks(doc_text, str(excel_subject))
        if found and validate_manufacturer_for_category(found, str(excel_subject)):
            brand_hint = found
            print(f"  ✅ 1В: производитель из чанков: {found}")
            response = re.sub(
                r'(---\s*Производитель / бренд / страна\s*---\s*\n)'
                r'(информация отсутствует[^\n]*)',
                lambda m, fb=found: m.group(1) + fb,
                response, count=1, flags=re.IGNORECASE
            )
        elif found:
            print(f"  ⚠️ 1В+: «{found}» не является производителем товара — отклонён")

    if brand_hint and LANGSEARCH_ENABLED and decision in ('participate', 'clarify'):
        bf = re.search(
            r'---\s*Производитель / бренд / страна\s*---\s*\n([^\n\-]+)',
            response, re.IGNORECASE
        )
        if bf and not re.search(r'\(', bf.group(1)):
            country = lookup_brand_country(brand_hint)
            if country:
                print(f"  🌍 Страна «{brand_hint}»: {country}")
                new_val = f"{bf.group(1).strip()} ({country})"
                response = re.sub(
                    r'(---\s*Производитель / бренд / страна\s*---\s*\n)'
                    + re.escape(bf.group(1)),
                    lambda m, nv=new_val: m.group(1) + nv,
                    response, count=1, flags=re.IGNORECASE
                )
                brand_hint = new_val

    if (decision == 'participate' and brand_hint
            and '(определено автоматически — требует проверки)' in brand_hint):
        print("  ⚠️ 1Б: производитель авто-определён → меняем на 'требуется уточнение'")
        decision = 'clarify'

    return response, brand_hint, decision


def process_tender(row, idx, total, incomplete_list, rfq_queue, sender_config=None):
    """
    Обрабатывает один тендер. Возвращает 9-кортеж:
    (reg_number, deadline_str, doc_path, decision, china_flag_for_folder,
     missing_fields, subject_str, nmck_str, suppliers_found)
    """
    if sender_config is None:
        sender_config = {}

    reg_number = str(row['Реестровый номер']).strip()
    deadline_str = parse_date_from_excel(row['Дата окончания подачи заявок'])
    if not deadline_str:
        print("  ⏭️ Пропускаем: в выгрузке нет даты подачи заявок")
        return (str(row.get('Реестровый номер', '')).strip(), "", "", "Ошибка",
                0, "в выгрузке нет даты подачи заявок", "", "", 0)
    _fz_label = " [44-ФЗ]" if _fz_kind(reg_number) == "44" else ""
    print(f"\n[{idx}/{total}] Обработка {reg_number}{_fz_label} (дедлайн {deadline_str})")

    excel_nmck = row.get('Начальная цена', None)
    excel_customer = row.get('Наименование заказа', None) or row.get('Заказчик', None)
    excel_subject = row.get('Название', None)
    excel_region = row.get('Регион', None)

    subject_str = str(excel_subject).strip() if excel_subject and pd.notna(excel_subject) else "—"
    try:
        nmck_val = float(str(excel_nmck).replace('\xa0', '').replace(' ', '').replace(',', '.'))
        nmck_str = f"{int(nmck_val):,}".replace(",", " ")
    except Exception:
        nmck_str = str(excel_nmck).strip() if excel_nmck and pd.notna(excel_nmck) else "—"

    _EARLY = lambda d: (reg_number, deadline_str, None, d, False, [], subject_str, nmck_str, False)

    # ── Шаг 1: Быстрые стоп-факторы по названию (до скачивания) ─────────
    if excel_subject and pd.notna(excel_subject):
        stop_reason = check_stopfactors_preprocess(str(excel_subject))
        if stop_reason:
            print(f"  ⛔ Стоп-фактор (предобработка): {stop_reason}")
            return _EARLY("not_participate")

    # ── Шаг 2: Сессия и скачивание документов ─────────────────────────────
    session = requests.Session()
    session.verify = False
    session.headers.update({"User-Agent": USER_AGENT})
    if PROXY_URL:
        session.proxies = {"http": PROXY_URL, "https": PROXY_URL}
    tender_dir = os.path.join("temp_files", reg_number)
    os.makedirs(tender_dir, exist_ok=True)

    try:
        downloaded_paths, partner_card_found, nac_regime_found, network_failed = \
            download_tender_documents(reg_number, row, session, tender_dir)

        if partner_card_found:
            return _EARLY("not_participate")

        # ── Шаг 3: Извлечение текста ─────────────────────────────────────
        doc_text, critical_errors, success_files, _ = extract_texts_from_paths(downloaded_paths)

        if not doc_text.strip():
            print("  ВНИМАНИЕ: не удалось извлечь текст ни из одного документа!")
            doc_text = "Текст документов не извлечён."

        if len(doc_text.strip()) < 200 and "Текст документов не извлечён" in doc_text:
            if network_failed:
                print(f"  ⚠️ Документы не скачались (HTTP 503 ЕИС) — тендер НЕ записан в БД и повторится при следующем запуске")
                return _EARLY("network_error")
            print(f"  ⏭️ Пропускаем: слишком мало текста")
            return _EARLY("not_participate")

        # ── Шаг 4: Подсказки и промпт ────────────────────────────────────
        reliable_hints = _build_reliable_hints(
            row, excel_subject, excel_nmck, excel_customer, excel_region
        )
        hints_from_files = extract_hints_from_text(doc_text)

        # Извлекаем кандидата бренда из темы закупки Excel и имён скачанных файлов
        _pre_brand, _pre_brand_reliable = extract_brand_from_subject_and_filenames(
            excel_subject, downloaded_paths
        )
        if _pre_brand:
            print(f"  🏷️ Бренд из темы/файлов: «{_pre_brand}» (надёжный: {_pre_brand_reliable})")

        brand_from_docs = None  # Python-скан бренда удалён; ЛЛМ сам определяет производителя

        # Строим подсказки: базовые + из файлов + опциональная подсказка о бренде
        _brand_hint_line = (
            f"\nПодсказка из темы/имён файлов: возможный производитель = {_pre_brand}"
            if _pre_brand else ""
        )
        combined_hints = (
            reliable_hints
            + (("\n" + hints_from_files) if hints_from_files else "")
            + _brand_hint_line
        )
        if combined_hints:
            print(f"  Подсказки: {combined_hints[:300]}...")

        # ── Шаг 5: LLM-вызов ─────────────────────────────────────────────
        prompt = MASTER_PROMPT + f"\n\nСодержание документов:\n{doc_text[:MAX_TEXT_TOTAL]}\n\n{combined_hints}"
        response = call_deepseek(prompt)
        if not response:
            raise Exception("Нет ответа от LLM (OpenRouter/DeepSeek)")

        response = clean_response_preamble(response)
        response = postprocess_response(response, combined_hints)
        decision = classify_deepseek_response(response)

        # ── Шаг 6: Обогащение бренда в ответе ────────────────────────────
        brand_match = re.search(
            r'--- Производитель / бренд / страна ---\s*\n([^\n\-]+)',
            response, re.IGNORECASE
        )
        brand_hint = None
        if brand_match:
            bv = brand_match.group(1).strip()
            if 'информация отсутствует' not in bv.lower() and len(bv) < 80:
                brand_hint = bv

        # Слова, которые ЛЛМ ошибочно выдаёт за бренд (артикул, модель и т.п.)
        _BRAND_FALSE_POSITIVES = {
            'артикул', 'наименование', 'модель', 'тип', 'обозначение',
            'изделие', 'продукт', 'товар', 'марка', 'образец',
        }

        if brand_hint:
            brand_lower = brand_hint.strip().lower()
            _STRIP_PREFIXES = ('торговая марка', 'товарный знак', 'артикул',
                               'наименование', 'модель', 'тип', 'обозначение',
                               'изделие', 'продукт', 'товар', 'марка', 'образец')
            if brand_lower in _STRIP_PREFIXES:
                print(f"  ⚠️ Бренд «{brand_hint}» — нарицательное слово — сбрасываем")
                brand_hint = None
                response = re.sub(
                    r'(---\s*Производитель / бренд / страна\s*---\s*\n)[^\n\-]+',
                    r'\1информация отсутствует в документации',
                    response, count=1, flags=re.IGNORECASE
                )
            else:
                for _p in _STRIP_PREFIXES:   # B3: срезать префикс, а не дропать
                    _m = re.match(re.escape(_p) + r'\s*[:\-—]?\s+(.+)', brand_hint, re.IGNORECASE)
                    if _m and len(_m.group(1).strip()) >= 3:
                        _old = brand_hint
                        brand_hint = _m.group(1).strip()
                        print(f"  🔧 B3: бренд очищен «{_old}» → «{brand_hint}»")
                        response = response.replace(_old, brand_hint, 1)
                        break

        # Проверяем бренд на стоп-список аббревиатур
        if brand_hint and LANGSEARCH_ENABLED:
            if brand_hint.strip().upper() in BRAND_BLACKLIST or len(brand_hint.strip()) < 3:
                print(f"  ⚠️ Бренд «{brand_hint}» в стоп-списке — поиск без бренда")
                brand_hint = None

        # Fallback: если ЛЛМ не определил бренд, но мы нашли надёжного кандидата
        # из темы закупки или имён скачанных файлов — используем его напрямую
        _PRE_BRAND_REJECTS = {'nan', 'none', 'null', 'na', 'n/a', '-', '—'}
        _pre_brand_safe = (
            _pre_brand
            and str(_pre_brand).strip().lower() not in _PRE_BRAND_REJECTS
            and len(str(_pre_brand).strip()) >= 3
        )
        if brand_hint is None and _pre_brand_reliable and _pre_brand_safe:
            brand_hint = _pre_brand
            print(f"  🏷️ Бренд из темы/файлов применён как fallback: «{brand_hint}»")
            # Вписываем в ответ ЛЛМ, чтобы поле производителя не было пустым
            response = re.sub(
                r'(---\s*Производитель / бренд / страна\s*---\s*\n)(информация отсутствует[^\n]*)',
                lambda m, b=brand_hint: m.group(1) + b + ' (определено из темы/файлов)',
                response, count=1, flags=re.IGNORECASE
            )

        response, brand_hint, decision = _enrich_brand_in_response(
            response, brand_hint, doc_text, excel_subject, decision
        )
            # ── Шаг 6.5: майнинг таблицы «Что нужно поставить» (B1) ───────────
        mined65 = mine_spec_table(response)
        if mined65['brands'] and (
                not brand_hint or 'информация отсутствует' in (brand_hint or '').lower()):
            brand_hint = sorted(mined65['brands'])[0]
            response = re.sub(
                r'(---\s*Производитель / бренд / страна\s*---\s*\n)(информация отсутствует[^\n]*)',
                lambda m, b=brand_hint: m.group(1) + b + ' (извлечено из таблицы позиций)',
                response, count=1, flags=re.IGNORECASE)
            print(f"  🏷️ B1: бренд из таблицы: «{brand_hint}»")

        # ── Шаг 7: Post-validations ───────────────────────────────────────
        decision, early_return = run_post_validations(
            response, decision, reg_number,
            nac_regime_file_found=nac_regime_found,
            critical_errors=critical_errors,
            incomplete_list=incomplete_list,
            subject_str=subject_str, nmck_str=nmck_str, deadline_str=deadline_str,
        )
        if early_return is not None:
            return early_return

        china_flag = extract_china_flag(response)

        # ── Шаг 8: Поиск поставщиков ─────────────────────────────────────
        suppliers_text = ""
        # china_flag_for_folder берём из LLM-ответа напрямую, не из результатов поиска
        china_flag_for_folder = bool(china_flag)
        if decision in ('participate', 'clarify'):
            subject_clean = str(excel_subject).strip() if excel_subject and pd.notna(excel_subject) else ""
            brand_for_search = (brand_hint.split(',')[0].strip()
                                if _is_reliable_brand(brand_hint) else None)
            if brand_for_search:
                print(f"  🔍 Поиск поставщиков (бренд: {brand_for_search})...")
            else:
                print("  🔍 Поиск поставщиков по предмету закупки...")
            suppliers_text = search_and_format_suppliers(
                subject_clean, brand_for_search, china_available=bool(china_flag)
            )
            if suppliers_text:
                print(f"  ✅ Поставщики сформированы ({len(suppliers_text)} символов)")
            else:
                print("  ℹ️ Поставщики не найдены")

        # ── Шаг 9: Логирование ────────────────────────────────────────────
        logs_dir = os.path.join(OUTPUT_BASE, "logs")
        os.makedirs(logs_dir, exist_ok=True)
        log_content = f"ОТВЕТ:\n{response}"
        if suppliers_text:
            log_content += f"\n\n=== ПОСТАВЩИКИ ===\n{suppliers_text}"
        with open(os.path.join(logs_dir, f"{reg_number}_log.txt"), 'w', encoding='utf-8') as f:
            f.write(log_content)

        if decision == 'not_participate':
            return _EARLY("not_participate")

        # ── Шаг 10: Word-отчёт ───────────────────────────────────────────
        reports_dir = os.path.join(OUTPUT_BASE, "temp_reports")
        doc_path = create_tender_report(
            reg_number, deadline_str, response, suppliers_text, reports_dir
        )

        # ── Шаг 11: RFQ-очередь ──────────────────────────────────────────
        if decision in ('participate', 'clarify'):
            raw_emails = extract_emails_from_text(suppliers_text) if suppliers_text else []
            emails, rejected_emails = _select_rfq_emails(raw_emails)
            region_val = str(excel_region).strip() if excel_region and pd.notna(excel_region) else ""
            sender_id = get_sender_for_region(region_val, sender_config)
            tender_url = (
                f"https://zakupki.gov.ru/epz/order/notice/notice223/common-info.html"
                f"?regNumber={reg_number}"
            )
            items_table = _extract_items_table_from_docx(doc_path)
            brand_for_queue = brand_hint or _extract_brand_from_docx(doc_path)
            rfq_queue.append({
                "tender_number":   reg_number,
                "tender_subject":  str(excel_subject).strip() if excel_subject and pd.notna(excel_subject) else "—",
                "tender_deadline": deadline_str,
                "tender_price":    str(int(excel_nmck)) if excel_nmck and pd.notna(excel_nmck) else "—",
                "tender_url":      tender_url,
                "emails":          emails,
                "sender_id":       sender_id,
                "doc_path":        doc_path,
                "brand":           brand_for_queue,
                "items_table":     items_table,
                "warranty_requirement": _extract_warranty_requirement(response),
            })
            email_note = f"{len(emails)} коммерческих адресов" if emails else "коммерческих адресов нет"
            print(f"  📥 В очередь RFQ [{sender_id}]: {email_note}")
            if rejected_emails:
                print(f"  ⛔ Отфильтровано нерелевантных контактов: {len(rejected_emails)}")

        missing_fields = [
            item for item in incomplete_list
            if item.get('reg_number') == reg_number
        ]
        missing_for_return = missing_fields[0]['missing_fields'] if missing_fields else []

        status_str = 'УЧАСТВУЕМ' if decision == 'participate' else 'ТРЕБУЕТСЯ УТОЧНЕНИЕ'
        src = 'найдены' if suppliers_text else 'нет'
        print(f"  Решение: {status_str} | Китай: {'Да' if china_flag_for_folder else 'Нет'} | Поставщики: {src}")
        return (reg_number, deadline_str, doc_path, decision, china_flag_for_folder,
                missing_for_return, subject_str, nmck_str, bool(suppliers_text))

    except Exception as e:
        tb = traceback.format_exc()
        print(f"  ❌ Ошибка при обработке {reg_number}: {e}")
        print(f"  Traceback:\n{tb}")
        return (reg_number, deadline_str, None, "error", False, [], subject_str, nmck_str, False)
    finally:
        shutil.rmtree(tender_dir, ignore_errors=True)
        time.sleep(DELAY_BETWEEN_TENDERS)


# =================== MAIN ===================================================

def _parse_force_args():
    force_all = False
    force_set = set()
    args = sys.argv[1:]
    if "--retry-errors" in args:
        pass  # handled separately in _parse_retry_errors_args
    if "--force" in args:
        idx = args.index("--force")
        values = []
        for v in args[idx + 1:]:
            if v.startswith("--"):
                break
            values.append(v)
        if not values:
            print("⚠️  --force указан без аргумента. Используй: --force all  или  --force НОМЕР")
        elif "all" in values:
            force_all = True
            print("🔁 Режим --force all: журнал дедупликации игнорируется для всей выгрузки.")
        else:
            force_set = set(values)
            print(f"🔁 Режим --force: принудительная переобработка {force_set}")
    return force_all, force_set


def _parse_retry_errors_args():
    """Парсит --retry-errors NUM1,NUM2,... → список номеров тендеров для удаления из decisions.db."""
    args = sys.argv[1:]
    if "--retry-errors" not in args:
        return []
    idx = args.index("--retry-errors")
    values = []
    for v in args[idx + 1:]:
        if v.startswith("--"):
            break
        for n in v.replace(" ", "").split(","):
            n = n.strip()
            if n:
                values.append(n)
    return values


def _clear_for_retry(nums):
    """
    Удаляет перечисленные тендеры из decisions.db чтобы они были обработаны при следующем запуске.
    Возвращает количество реально удалённых записей.
    """
    db_path = str(DATA_DIR / "decisions.db")
    if not os.path.exists(db_path):
        print("⚠️  decisions.db не найдена — нечего очищать.")
        return 0
    conn = sqlite3.connect(db_path)
    deleted = 0
    for n in nums:
        cur = conn.execute("DELETE FROM decisions WHERE tender_number=?", (n,))
        deleted += cur.rowcount
    conn.commit()
    conn.close()
    return deleted


# ── СРЕЗ 8: теневой режим tendercore ──
try:
    import shadow_wiring as _sw8
    _sw8.apply(globals())
except Exception as _e_sw8:
    print(f"⚠️ shadow wiring пропущен: {_e_sw8}")


def main():
    os.makedirs("temp_files", exist_ok=True)
    os.makedirs(OUTPUT_BASE, exist_ok=True)
    # ── --send-rfq: отправка писем из готовой очереди ─────────────────────
    if "--send-rfq" in sys.argv:
        send_rfq_main()
        return
    # ── --build-queue: строим очередь RFQ из готовых docx-отчётов ──────────
    # Проверяем до _parse_force_args(), чтобы --force не вызывал ложных предупреждений
    if "--build-queue" in sys.argv:
        idx = sys.argv.index("--build-queue")
        if idx + 1 < len(sys.argv) and not sys.argv[idx + 1].startswith("--"):
            folder_arg = sys.argv[idx + 1]
        else:
            print("❌ Укажи папку: python tender_auto.py --build-queue <папка> [--force]")
            return
        force_flag = "--force" in sys.argv
        build_queue_from_reports(folder_arg, force=force_flag)
        return

    force_all, force_set = _parse_force_args()

    # ── --retry-errors: сбрасываем записи в БД и выходим ─────────────────
    retry_nums = _parse_retry_errors_args()
    if retry_nums:
        deleted = _clear_for_retry(retry_nums)
        print(f"✅ Удалено {deleted} из {len(retry_nums)} записей из decisions.db.")
        print(f"   Тендеры: {', '.join(retry_nums)}")
        print("   Запусти скрипт без --retry-errors — они обработаются как новые.")
        return

    sender_config = _load_sender_config()
    senders_info = sender_config.get("senders", {})
    if senders_info:
        print(f"🔧 Отправители ({len(senders_info)}): {', '.join(senders_info.keys())}")
    else:
        print("🔧 sender_config.json не найден — используется единственный отправитель (GMAIL_*)")

    init_email_db()
    init_decisions_db()

    print(f"🔧 win32com (.doc):        {'✅' if WIN32COM_AVAILABLE else '❌ pip install pywin32'}")
    print(f"🔧 striprtf (.rtf):        {'✅' if STRIPRTF_AVAILABLE else '❌ pip install striprtf'}")
    print(f"🔧 PyMuPDF (PDF):          {'✅' if FITZ_AVAILABLE else '❌ pip install pymupdf'}")
    print(f"🔧 Tesseract OCR:          {'✅' if OCR_AVAILABLE else '❌ pip install pytesseract pillow'}")
    # ----- Диагностика поиска поставщиков -----
    # 1) LangSearch (основной, бесплатный)
    if LANGSEARCH_ENABLED and LANGSEARCH_API_KEY:
        try:
            _ls_resp = requests.post(
                "https://api.langsearch.com/v1/web-search",
                headers={"Authorization": f"Bearer {LANGSEARCH_API_KEY}", "Content-Type": "application/json"},
                json={"query": "rack server manufacturer", "count": 1, "freshness": "noLimit", "summary": False},
                timeout=10,
            )
            if _ls_resp.status_code == 200:
                _ls_pages = (_ls_resp.json().get('data') or {}).get('webPages', {}).get('value', [])
                print(f"🔧 LangSearch (поиск):     ✅ активен (тест: {len(_ls_pages)} рез.)")
            else:
                try:
                    _ls_err = _ls_resp.json().get('message', _ls_resp.text[:100])
                except Exception:
                    _ls_err = _ls_resp.text[:100]
                print(f"🔧 LangSearch (поиск):     ⛔ HTTP {_ls_resp.status_code}: {_ls_err}")
        except Exception as _e:
            print(f"🔧 LangSearch (поиск):     ⚠️ тест не прошёл: {_e}")
    else:
        print(f"🔧 LangSearch (поиск):     ❌ ключ не задан (LANGSEARCH_API_KEY)")

    # 3) LLM-фоллбэк (поставщики через OpenRouter)
    print(f"🔧 LLM-поставщики (резерв):{'✅ OpenRouter активен' if OPENROUTER_API_KEY else '❌ OPENROUTER_API_KEY не задан'}")
    print(f"🔧 Email-рассылка (RFQ):   {'✅' if EMAIL_ENABLED and GMAIL_ADDRESS else '❌ нет credentials'}")
    print(f"🔧 MX-проверка доменов:    {'✅' if DNS_AVAILABLE else '⚠️ pip install dnspython'}")
    print(f"🔧 VPN-прокси:             {'✅ ' + PROXY_URL if PROXY_URL else '⚠️ не настроен'}")

    if not EXCEL_FILE:
        print("[ОШИБКА] Excel-файл не найден. Положите .xlsx в папку со скриптом.")
        return
    try:
        df = pd.read_excel(EXCEL_FILE, sheet_name=SHEET_NAME, dtype={'Реестровый номер': str})
    except Exception as e:
        print(f"Ошибка чтения Excel: {e}")
        return

    if MAX_TENDERS:
        df = df.head(MAX_TENDERS)
    total = len(df)
    print(f"📋 Всего тендеров: {total}")

    _excel_mtime = os.path.getmtime(EXCEL_FILE) if EXCEL_FILE else 0
    _cp = _load_checkpoint()
    _resume_set = set()
    if (_cp
            and _cp.get("excel_file") == EXCEL_FILE
            and abs(_cp.get("excel_mtime", 0) - _excel_mtime) < 1):
        _already = len(_cp.get("processed", []))
        print(f"\n⚡ Найден незавершённый прогон (обработано {_already} из {_cp.get('total', total)}).")
        try:
            _answer = input("   Продолжить? [y/n]: ").strip().lower()
        except EOFError:
            _answer = "n"
        if _answer == "y":
            _resume_set = set(_cp.get("processed", []))
            print(f"   ▶ Продолжаю с тендера {_already + 1}...")
        else:
            _delete_checkpoint()
            print("   ▶ Начинаю заново.")
    _cp_processed = list(_resume_set)
    _cp_data = {
        "excel_file":  EXCEL_FILE,
        "excel_mtime": _excel_mtime,
        "processed":   _cp_processed,
        "total":       total,
        "started_at":  datetime.datetime.now().strftime("%Y-%m-%d %H:%M"),
    }
    _save_checkpoint(_cp_data)

    results = []
    incomplete_tenders_global = []
    rfq_queue = []
    new_history_records = []
    network_error_list = []   # тендеры, не скачавшиеся из-за HTTP 503 — НЕ пишутся в БД
    _run_completed = False
    skipped_count = 0

    _db_conn = sqlite3.connect(str(DATA_DIR / "decisions.db"))
    _db_conn.row_factory = sqlite3.Row
    _today = datetime.datetime.now().strftime("%Y-%m-%d")

    try:
        for idx, (_, row) in enumerate(tqdm(df.iterrows(), total=total, desc="Тендеры"), start=1):
            _reg = str(row.get('Реестровый номер', '')).strip()
            if _reg in _resume_set:
                print(f"  ⏩ Тендер {_reg} уже обработан в прерванном прогоне — пропуск")
                continue
            if not force_all and _reg not in force_set:
                _dup = _db_conn.execute(
                    "SELECT processed_date, decision FROM decisions WHERE tender_number=?",
                    (_reg,)
                ).fetchone()
                if _dup:
                    _label = {"participate": "Участвуем", "clarify": "Требуется уточнение",
                              "not_participate": "Отказ", "error": "Ошибка"}.get(_dup["decision"], _dup["decision"])
                    print(f"  ⏭ Тендер {_reg} уже обработан ({_dup['processed_date']}, решение: {_label}) — пропуск")
                    skipped_count += 1
                    continue
            elif _reg in force_set:
                print(f"  🔁 Тендер {_reg} — принудительная переобработка (--force)")

            res = process_tender(row, idx, total, incomplete_tenders_global, rfq_queue, sender_config)
            results.append(res)

            _reg2, _deadline, _doc, _decision, _china, _missing, _subj, _nmck, _sup = res

            # Сетевая ошибка ЕИС (HTTP 503) — не пишем в БД, тендер повторится при следующем запуске
            if _decision == "network_error":
                network_error_list.append(_reg2)
                _cp_processed.append(_reg2)
                _cp_data["processed"] = _cp_processed
                _save_checkpoint(_cp_data)
                continue

            _db_conn.execute(
                """INSERT OR REPLACE INTO decisions
                   (tender_number, processed_date, decision, subject, nmck, china_flag, suppliers_found)
                   VALUES (?, ?, ?, ?, ?, ?, ?)""",
                (_reg2, _today, _decision, _subj, _nmck, int(_china), int(_sup))
            )
            _db_conn.commit()

            new_history_records.append({
                "processed_date":  _today,
                "tender_number":   _reg2,
                "subject":         _subj,
                "nmck":            _nmck,
                "decision":        _decision,
                "china_flag":      _china,
                "suppliers_found": _sup,
            })

            _cp_processed.append(_reg2)
            _cp_data["processed"] = _cp_processed
            _save_checkpoint(_cp_data)

        _run_completed = True
    except KeyboardInterrupt:
        print("\n⚠️ Прервано пользователем. Чекпоинт сохранён.")
    finally:
        _db_conn.close()

    date_groups = defaultdict(list)
    china_date_groups = defaultdict(list)
    errors = []
    participate_clarify_count = 0
    path_mapping = {}

    for reg, deadline, doc_path, status, china_flag, missing, *_ in results:
        if status == "error":
            errors.append(reg)
        elif doc_path:
            date_groups[deadline].append(doc_path)
            if china_flag:
                china_date_groups[deadline].append(doc_path)
            if status in ('participate', 'clarify'):
                participate_clarify_count += 1

    if incomplete_tenders_global:
        print("\n" + "=" * 70)
        print("ТЕНДЕРЫ С НЕПОЛНОЙ ИНФОРМАЦИЕЙ")
        print("=" * 70)
        for tender in incomplete_tenders_global:
            fields_str = ", ".join(tender['missing_fields'])
            print(f"№ {tender['reg_number']} ({tender['deadline']}) — отсутствует: {fields_str}")
        with open(os.path.join(OUTPUT_BASE, "incomplete_tenders_list.txt"), 'w', encoding='utf-8') as f:
            f.write("Тендеры с неполной информацией:\n\n")
            for tender in incomplete_tenders_global:
                f.write(f"{tender['reg_number']} ({tender['deadline']}): {', '.join(tender['missing_fields'])}\n")

    if date_groups or china_date_groups:
        final_dir_name = f"Козлов_{datetime.datetime.now().strftime('%d.%m.%Y')}"
        final_dir = os.path.join(OUTPUT_BASE, final_dir_name)
        os.makedirs(final_dir, exist_ok=True)
        for deadline, paths in date_groups.items():
            folder = os.path.join(final_dir, deadline.replace('.', '_'))
            os.makedirs(folder, exist_ok=True)
            for src in paths:
                shutil.copy(src, folder)
                path_mapping[src] = os.path.join(folder, os.path.basename(src))
        china_parent = os.path.join(final_dir, "Доступные к закупке в Китае")
        os.makedirs(china_parent, exist_ok=True)
        for deadline, paths in china_date_groups.items():
            folder = os.path.join(china_parent, deadline.replace('.', '_'))
            os.makedirs(folder, exist_ok=True)
            for src in paths:
                shutil.copy(src, folder)
        for entry in rfq_queue:
            old_path = entry.get("doc_path", "")
            if old_path in path_mapping:
                entry["doc_path"] = path_mapping[old_path]
        archive_path = shutil.make_archive(final_dir, 'zip', final_dir)
        print(f"\n✅ Архив создан: {archive_path}")

    if errors:
        print("\n❌ Тендеры с ошибками:")
        for e in errors:
            print(f"  {e}")
    elif results:
        print("\n✅ Все тендеры обработаны без критических ошибок.")

    if network_error_list:
        print(f"\n⚠️  Тендеры с ошибкой сети ЕИС (HTTP 503) — НЕ записаны в БД, повторятся при следующем запуске:")
        for n in network_error_list:
            print(f"  {n}")
        nums_str = ",".join(network_error_list)
        print(f"\n  Чтобы убедиться что они не остались в БД от прошлых прогонов, запусти:")
        print(f"  python tender_auto.py --retry-errors {nums_str}")

    if results:
        summary_dir = final_dir if (date_groups or china_date_groups) else OUTPUT_BASE
        save_run_summary(results, summary_dir, path_mapping)

    append_history_xlsx(new_history_records)

    shutil.rmtree("temp_files", ignore_errors=True)
    temp_reports = os.path.join(OUTPUT_BASE, "temp_reports")
    if os.path.exists(temp_reports):
        shutil.rmtree(temp_reports)

    if rfq_queue:
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        payload = {
            "run_date": datetime.datetime.now().strftime("%Y-%m-%d %H:%M"),
            "tenders":  rfq_queue,
        }
        with open(QUEUE_PATH, "w", encoding="utf-8") as f:
            _json.dump(payload, f, ensure_ascii=False, indent=2)
        print(f"\n📥 ОЧЕРЕДЬ RFQ: {len(rfq_queue)} тендеров → {os.path.abspath(QUEUE_PATH)}")
        print("  Вызови send_rfq_main() или запусти скрипт с флагом --send-rfq")

    if _run_completed:
        _delete_checkpoint()

    if skipped_count:
        print(f"📋 Пропущено дубликатов: {skipped_count}")
    print("Готово.")


if __name__ == "__main__":
    if os.environ.get("USE_TENDERCORE") == "1":
        from tendercore.cli import main as _tc_main
        print("🧪 РЕЖИМ TENDERCORE (новый движок)")
        _tc_main()
    else:
        main()
